def _colore_visuale_testo(valore):
    s = str(valore or '').strip().upper()
    if not s:
        return None
    if 'SILVER' in s:
        return ('#DCEBFF', '#0B4F9C')
    if 'U11' in s and 'VERDE' in s:
        return ('#DDF5E3', '#146C2E')
    if 'U11' in s and 'BLU' in s:
        return ('#DCEBFF', '#0B4F9C')
    if 'U11' in s and 'ROSS' in s:
        return ('#FDE2E2', '#A61B1B')
    if 'U11' in s and 'BIANC' in s:
        return ('#F3F4F6', '#374151')
    if 'FIPAV' in s:
        return ('#FDE2E2', '#A61B1B')
    if 'UISP' in s:
        return ('#FFF0D6', '#9A4D00')
    return None

def _style_dataframe_colori(df):
    if df is None:
        return df
    def _css(v):
        c = _colore_visuale_testo(v)
        if not c:
            return ''
        bg, fg = c
        return f'background-color:{bg}; color:{fg}; font-weight:600;'
    try:
        return df.style.map(_css)
    except Exception:
        try:
            return df.style.applymap(_css)
        except Exception:
            return df

def _style_dataframe_nostra_societa(df, nomi_squadra=None):
    """Evidenzia le righe che contengono una squadra della società."""
    styled = _style_dataframe_colori(df)
    nomi = {' '.join(str(x or '').casefold().split()) for x in (nomi_squadra or []) if str(x or '').strip()}
    if not nomi or df is None:
        return styled
    def _row_css(row):
        vals = {' '.join(str(v or '').casefold().split()) for v in row.tolist()}
        hit = bool(nomi & vals)
        css = 'background-color:#FFF3BF;color:#5F3B00;font-weight:700;' if hit else ''
        return [css] * len(row)
    try:
        return styled.apply(_row_css, axis=1)
    except Exception:
        return styled

