def _pdf_da_png_grafico(png_bytes, titolo='Grafico Gestionale Volley'):
    """Crea un PDF A4 orizzontale stampabile partendo dal PNG del grafico."""
    try:
        from reportlab.lib.pagesizes import A4, landscape
        from reportlab.lib.utils import ImageReader
        from reportlab.pdfgen import canvas
        from io import BytesIO
        from PIL import Image as PILImage

        out = BytesIO()
        page_w, page_h = landscape(A4)
        c = canvas.Canvas(out, pagesize=(page_w, page_h))
        c.setFont('Helvetica-Bold', 14)
        c.drawString(28, page_h - 30, str(titolo)[:110])

        bio = BytesIO(png_bytes)
        img = PILImage.open(bio)
        iw, ih = img.size
        max_w = page_w - 56
        max_h = page_h - 80
        scale = min(max_w / iw, max_h / ih)
        dw, dh = iw * scale, ih * scale
        x = (page_w - dw) / 2
        y = (page_h - dh) / 2 - 10
        bio.seek(0)
        c.drawImage(ImageReader(bio), x, y, width=dw, height=dh, preserveAspectRatio=True)
        c.showPage()
        c.save()
        out.seek(0)
        return out.getvalue()
    except Exception:
        return None

def _grafico_esportabile(fig, *, key=None, titolo=None, use_container_width=True):
    """Mostra Plotly e rende visibili i comandi PNG/PDF sotto ogni grafico."""
    titolo_eff = titolo or getattr(getattr(fig, 'layout', None), 'title', None)
    if hasattr(titolo_eff, 'text'):
        titolo_eff = titolo_eff.text
    titolo_eff = str(titolo_eff or 'Grafico Gestionale Volley')

    # Costruisce prima la chiave del grafico per evitare collisioni anche
    # sul componente Plotly quando key non viene passata esplicitamente.
    try:
        import hashlib
        import inspect
        _caller_pre = inspect.currentframe().f_back
        _callsite_pre = f"{getattr(_caller_pre, 'f_code', None).co_name if _caller_pre else 'grafico'}:{getattr(_caller_pre, 'f_lineno', 0)}"
        try:
            _fig_signature_pre = fig.to_json()
        except Exception:
            _fig_signature_pre = repr(fig)
        _seed_pre = f"{key or ''}|{titolo_eff}|{_callsite_pre}|{_fig_signature_pre}"
        _plot_key = 'plot_' + hashlib.sha1(_seed_pre.encode('utf-8', errors='ignore')).hexdigest()[:16]
    except Exception:
        _plot_key = key

    st.plotly_chart(
        fig,
        use_container_width=use_container_width,
        config=PLOTLY_EXPORT_CONFIG,
        key=_plot_key,
    )

    # Chiave univoca e deterministica per ogni grafico.
    # La v3.14.38 usava solo il titolo: grafici diversi senza titolo
    # generavano la stessa key Streamlit (DuplicateElementKey).
    try:
        import hashlib
        import inspect
        _caller = inspect.currentframe().f_back
        _callsite = f"{getattr(_caller, 'f_code', None).co_name if _caller else 'grafico'}:{getattr(_caller, 'f_lineno', 0)}"
        try:
            _fig_signature = fig.to_json()
        except Exception:
            _fig_signature = repr(fig)
        _seed = f"{key or ''}|{titolo_eff}|{_callsite}|{_fig_signature}"
        safe_key = hashlib.sha1(_seed.encode('utf-8', errors='ignore')).hexdigest()[:16]
    except Exception:
        safe_key = re.sub(r'[^A-Za-z0-9_-]+', '_', str(key or titolo_eff))[:60] or 'grafico'

    try:
        png_bytes = fig.to_image(format='png', scale=2, width=1400, height=800)
    except Exception:
        png_bytes = None

    # I pulsanti restano sempre visibili.
    # Con Kaleido 0.2.1 su Streamlit Cloud il PNG viene generato lato server
    # senza dipendere da Chrome esterno.
    if png_bytes:
        pdf_bytes = _pdf_da_png_grafico(png_bytes, titolo_eff)
        c1, c2 = st.columns(2)
        with c1:
            st.download_button(
                '📷 SCARICA PNG',
                data=png_bytes,
                file_name=f'grafico_{safe_key}.png',
                mime='image/png',
                use_container_width=True,
                key=f'dl_png_{safe_key}',
            )
        with c2:
            if pdf_bytes:
                st.download_button(
                    '📄 ESPORTA / STAMPA PDF',
                    data=pdf_bytes,
                    file_name=f'grafico_{safe_key}.pdf',
                    mime='application/pdf',
                    use_container_width=True,
                    key=f'dl_pdf_{safe_key}',
                )
            else:
                st.button(
                    '📄 PDF NON DISPONIBILE',
                    disabled=True,
                    use_container_width=True,
                    key=f'dl_pdf_disabled_{safe_key}',
                )
    else:
        # Fallback sempre utilizzabile: salva il grafico interattivo come HTML.
        try:
            html_bytes = fig.to_html(
                include_plotlyjs='cdn',
                full_html=True,
                config=PLOTLY_EXPORT_CONFIG,
            ).encode('utf-8')
        except Exception:
            html_bytes = b''
        c1, c2 = st.columns(2)
        with c1:
            st.button(
                '📷 PNG NON DISPONIBILE',
                disabled=True,
                use_container_width=True,
                key=f'dl_png_disabled_{safe_key}',
            )
        with c2:
            if html_bytes:
                st.download_button(
                    '🖨️ SCARICA / STAMPA HTML',
                    data=html_bytes,
                    file_name=f'grafico_{safe_key}.html',
                    mime='text/html',
                    use_container_width=True,
                    key=f'dl_html_{safe_key}',
                )
        st.caption('Per attivare PNG e PDF su Streamlit Cloud usa kaleido==0.2.1 nel requirements.txt.')


def _af_report_grafici_completo(metriche, figure):
    """Report autosufficiente con riepilogo e tutti i grafici dell'Archivio Federale."""
    grafici=[]
    primo=True
    for fig in (figure or []):
        if fig is None:
            continue
        try:
            grafici.append(fig.to_html(
                full_html=False,
                include_plotlyjs=True if primo else False,
                config={'responsive':True,'displaylogo':False,'toImageButtonOptions':{'format':'png','scale':2}},
            ))
            primo=False
        except Exception:
            continue
    cards=''.join(
        f'<div class="metric"><span>{str(etichetta)}</span><strong>{str(valore)}</strong></div>'
        for etichetta,valore in (metriche or [])
    )
    charts=''.join(f'<section class="chart">{frammento}</section>' for frammento in grafici)
    generato=datetime.now().strftime('%d/%m/%Y %H:%M')
    return f'''<!doctype html>
<html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Archivio Federale - Report grafici completo</title>
<style>
@page {{ size:A4 landscape; margin:10mm; }}
* {{ box-sizing:border-box; }}
body {{ font-family:Arial,Helvetica,sans-serif; color:#172033; margin:0; padding:24px; background:#fff; }}
h1 {{ margin:0 0 4px; font-size:26px; }}
.meta {{ color:#687386; margin-bottom:18px; }}
.metrics {{ display:grid; grid-template-columns:repeat(5,minmax(120px,1fr)); gap:10px; margin-bottom:18px; }}
.metric {{ border:1px solid #dfe5ec; border-radius:9px; padding:10px 12px; background:#f8fafc; }}
.metric span {{ display:block; color:#667085; font-size:12px; margin-bottom:5px; }}
.metric strong {{ font-size:24px; }}
.charts {{ display:grid; grid-template-columns:1fr 1fr; gap:16px; }}
.chart {{ border:1px solid #dfe5ec; border-radius:10px; padding:8px; min-height:440px; break-inside:avoid; }}
.actions {{ margin:0 0 14px; }}
button {{ border:0; border-radius:7px; padding:9px 16px; background:#1769aa; color:#fff; cursor:pointer; }}
@media print {{ .actions {{ display:none; }} body {{ padding:0; }} }}
@media (max-width:900px) {{ .metrics {{ grid-template-columns:repeat(2,1fr); }} .charts {{ grid-template-columns:1fr; }} }}
</style></head><body>
<div class="actions"><button onclick="window.print()">Stampa / Salva come PDF</button></div>
<h1>Archivio Federale FIPAV / UISP</h1><div class="meta">Report completo generato il {generato}</div>
<div class="metrics">{cards}</div><div class="charts">{charts}</div>
</body></html>'''.encode('utf-8')



def _html_report_grafici_squadra(*, titolo, sottotitolo='', metriche=None, figure=None):
    """Crea un unico report HTML stampabile con più grafici Plotly."""
    metriche = metriche or []
    figure = figure or []

    cards = ''.join(
        f"""
        <div class="metric">
            <div class="metric-label">{str(lbl)}</div>
            <div class="metric-value">{str(val)}</div>
        </div>
        """
        for lbl, val in metriche
    )

    grafici_html = []
    for i, fig in enumerate(figure):
        if fig is None:
            continue
        try:
            import plotly.graph_objects as go
            fig_report = go.Figure(fig)

            fig_report.update_layout(
                template='plotly_white',
                paper_bgcolor='white',
                plot_bgcolor='white',
                font=dict(color='#172033', size=15),
                title_font=dict(color='#172033', size=20),
                autosize=True,
                height=390 if i < 2 else 430,
            )

            if i == 0:
                fig_report.update_traces(
                    marker=dict(colors=['#0B70D1', '#8CC8F4']),
                    textfont=dict(color='white', size=14),
                    insidetextfont=dict(color='white', size=14),
                )
                fig_report.update_layout(
                    legend=dict(font=dict(color='#172033', size=14)),
                    margin=dict(l=25, r=25, t=60, b=25),
                )

            elif i == 1:
                fig_report.update_xaxes(
                    title_text='',
                    tickmode='array',
                    tickvals=['Set vinti', 'Set persi'],
                    ticktext=['Set vinti', 'Set persi'],
                    tickfont=dict(color='#172033', size=16),
                    automargin=True,
                )
                fig_report.update_yaxes(
                    title_text='Set',
                    tickfont=dict(color='#172033', size=14),
                    automargin=True,
                )
                fig_report.update_traces(
                    textfont=dict(color='#172033', size=14),
                    cliponaxis=False,
                )
                fig_report.update_layout(
                    margin=dict(l=55, r=25, t=60, b=70),
                )

            else:
                fig_report.update_yaxes(
                    title_text='',
                    tickfont=dict(color='#172033', size=14),
                    automargin=True,
                )
                fig_report.update_xaxes(
                    title_text='Vittorie %',
                    tickfont=dict(color='#172033', size=13),
                    automargin=True,
                )
                fig_report.update_traces(
                    textfont=dict(color='#172033', size=13),
                    cliponaxis=False,
                )
                fig_report.update_layout(
                    margin=dict(l=230, r=65, t=60, b=60),
                )

            frag = fig_report.to_html(
                full_html=False,
                include_plotlyjs=('cdn' if i == 0 else False),
                config={'displayModeBar': False, 'responsive': True},
            )
            grafici_html.append(f'<div class="chart chart-{i+1}">{frag}</div>')
        except Exception:
            pass

    charts = ''.join(grafici_html)

    return f"""<!doctype html>
<html lang="it">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>{titolo}</title>
<style>
  @page {{ size: A4 landscape; margin: 10mm; }}
  * {{ box-sizing: border-box; }}
  body {{
    font-family: Arial, Helvetica, sans-serif;
    margin: 0;
    padding: 18px;
    color: #172033;
    background: #fff;
  }}
  h1 {{ margin: 0 0 4px 0; font-size: 24px; }}
  .subtitle {{ color:#5f6b7a; margin-bottom:16px; font-size:14px; }}
  .metrics {{
    display:grid;
    grid-template-columns: repeat(4, 1fr);
    gap:10px;
    margin: 10px 0 18px 0;
  }}
  .metric {{
    border:1px solid #dfe5ec;
    border-radius:10px;
    padding:10px 14px;
    background:#f8fafc;
  }}
  .metric-label {{ font-size:12px; color:#6b7280; }}
  .metric-value {{ font-size:22px; font-weight:700; margin-top:4px; }}
  .grid2 {{
    display:grid;
    grid-template-columns: 1fr 1fr;
    gap:14px;
    align-items:start;
  }}
  .chart {{
    border:1px solid #e5e7eb;
    border-radius:10px;
    padding:8px;
    break-inside:avoid;
    background:#fff;
  }}
  .chart-3 {{
    grid-column: 1 / -1;
  }}
  .chart .plotly-graph-div {{
    width:100% !important;
  }}
  .actions {{
    margin-bottom:14px;
    padding:10px;
    background:#eef6ff;
    border-radius:8px;
    font-size:13px;
  }}
  @media print {{
    .actions {{ display:none; }}
    body {{ padding:0; }}
  }}
</style>
</head>
<body>
  <div class="actions">
    Per stampare o creare il PDF: <b>Ctrl+P</b> → scegli <b>Salva come PDF</b>.
  </div>
  <h1>{titolo}</h1>
  <div class="subtitle">{sottotitolo}</div>
  <div class="metrics">{cards}</div>
  <div class="grid2">{charts}</div>
</body>
</html>"""


def _html_report_dashboard(*, stagione, metriche, figure):
    """Report HTML unico e stampabile per tutti i grafici della Dashboard."""
    import plotly.graph_objects as go

    cards = ''.join(
        f"""
        <div class="metric">
          <div class="label">{str(lbl)}</div>
          <div class="value">{str(val)}</div>
        </div>
        """
        for lbl, val in metriche
    )

    grafici_html = []
    for i, fig in enumerate(figure):
        if fig is None:
            continue
        try:
            f = go.Figure(fig)
            f.update_layout(
                template='plotly_white',
                paper_bgcolor='white',
                plot_bgcolor='white',
                font=dict(color='#172033', size=14),
                title_font=dict(color='#172033', size=18),
                autosize=True,
                margin=dict(l=55, r=35, t=60, b=65),
                height=420 if i < 2 else 380,
            )
            f.update_xaxes(
                tickfont=dict(color='#172033', size=12),
                title_font=dict(color='#172033', size=13),
                automargin=True,
            )
            f.update_yaxes(
                tickfont=dict(color='#172033', size=12),
                title_font=dict(color='#172033', size=13),
                automargin=True,
            )
            frag = f.to_html(
                full_html=False,
                include_plotlyjs=('cdn' if i == 0 else False),
                config={'displayModeBar': False, 'responsive': True},
            )
            grafici_html.append(f'<section class="chart chart-{i+1}">{frag}</section>')
        except Exception:
            pass

    return f"""<!doctype html>
<html lang="it">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Dashboard Monviso Volley — {stagione}</title>
<style>
@page {{ size:A4 landscape; margin:10mm; }}
* {{ box-sizing:border-box; }}
body {{
  font-family:Arial, Helvetica, sans-serif;
  color:#172033;
  margin:0;
  padding:18px;
  background:white;
}}
.actions {{
  background:#eef6ff;
  padding:10px 14px;
  border-radius:8px;
  margin-bottom:14px;
  font-size:14px;
}}
h1 {{ margin:0 0 4px 0; font-size:26px; }}
.subtitle {{ color:#657080; margin-bottom:14px; }}
.metrics {{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:10px;
  margin:12px 0 16px 0;
}}
.metric {{
  border:1px solid #dfe5ec;
  border-radius:10px;
  padding:10px 14px;
  background:#f8fafc;
}}
.label {{ font-size:12px; color:#657080; }}
.value {{ font-size:22px; font-weight:700; margin-top:4px; }}
.grid {{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:14px;
}}
.chart {{
  border:1px solid #e1e5ea;
  border-radius:10px;
  padding:8px;
  background:white;
  break-inside:avoid;
  min-width:0;
  overflow:visible;
}}
.chart-3 {{
  grid-column:1 / -1;
}}
.chart .plotly-graph-div {{
  width:100% !important;
}}
@media print {{
  .actions {{ display:none; }}
  body {{ padding:0; }}
  .chart {{ page-break-inside:avoid; }}
}}
</style>
</head>
<body>
<div class="actions">Per stampare o creare il PDF: <b>Ctrl+P</b> → <b>Salva come PDF</b>.</div>
<h1>📊 Dashboard Monviso Volley</h1>
<div class="subtitle">Stagione {stagione}</div>
<div class="metrics">{cards}</div>
<div class="grid">{''.join(grafici_html)}</div>
</body>
</html>"""

def ora_italiana():
    return datetime.now(ROME_TZ).replace(tzinfo=None)
