def _drive_service_persistenza():
    """Client Drive: usa OAuth solo se valido, altrimenti il service account."""
    oauth_signature = ""
    try:
        oauth_section = st.secrets.get("gcp_drive_oauth")
        if oauth_section:
            # Accetta entrambe le configurazioni usate in Streamlit Secrets:
            # [gcp_drive_oauth] con campi diretti oppure content="""{...}""".
            oauth = dict(oauth_section)
            oauth_content = oauth.get("content", "")
            if oauth_content:
                oauth_da_content = json.loads(oauth_content) if isinstance(oauth_content, str) else dict(oauth_content)
                if isinstance(oauth_da_content, dict):
                    oauth = {**oauth_da_content, **{k: v for k, v in oauth.items() if k != "content"}}
            client_id = str(oauth.get("client_id", "") or "").strip()
            client_secret = str(oauth.get("client_secret", "") or "").strip()
            refresh_token = str(oauth.get("refresh_token", "") or "").strip()
            token_uri = str(
                oauth.get("token_uri", "https://oauth2.googleapis.com/token")
                or "https://oauth2.googleapis.com/token"
            ).strip()
            if client_id and client_secret and refresh_token:
                oauth_signature = hashlib.sha256(
                    f"{client_id}|{refresh_token}".encode("utf-8")
                ).hexdigest()
                from google.oauth2.credentials import Credentials
                from google.auth.transport.requests import Request
                from googleapiclient.discovery import build
                creds = Credentials(
                    token=None,
                    refresh_token=refresh_token,
                    token_uri=token_uri,
                    client_id=client_id,
                    client_secret=client_secret,
                    scopes=["https://www.googleapis.com/auth/drive"],
                )
                # La costruzione del client non verifica il refresh token. Il
                # controllo esplicito permette di intercettare invalid_grant e
                # proseguire subito con il service account configurato.
                creds.refresh(Request())
                st.session_state.pop("_oauth_drive_invalid_signature", None)
                st.session_state.pop("_oauth_drive_error", None)
                servizio_oauth = build("drive", "v3", credentials=creds, cache_discovery=False)
                st.session_state["_drive_auth_mode"] = "OAuth"
                return servizio_oauth
    except Exception as exc:
        st.session_state["_oauth_drive_error"] = f"{type(exc).__name__}: {exc}"
        if oauth_signature:
            st.session_state["_oauth_drive_invalid_signature"] = oauth_signature

    try:
        section = st.secrets.get("gcp_backup_service_account")
        if not section:
            st.session_state["_drive_auth_mode"] = "Non disponibile"
            return None
        raw = section.get("content", "")
        if not raw:
            st.session_state["_drive_auth_mode"] = "Non disponibile"
            return None
        info = json.loads(raw) if isinstance(raw, str) else dict(raw)

        from google.oauth2 import service_account
        from googleapiclient.discovery import build
        creds = service_account.Credentials.from_service_account_info(
            info,
            scopes=["https://www.googleapis.com/auth/drive"],
        )
        servizio_account = build("drive", "v3", credentials=creds, cache_discovery=False)
        st.session_state["_drive_auth_mode"] = "Service Account (alternativa)"
        return servizio_account
    except Exception as exc:
        st.session_state["_drive_auth_mode"] = "Non disponibile"
        st.session_state["_drive_service_account_error"] = f"{type(exc).__name__}: {exc}"
        return None


def _drive_nome_live(file):
    rel = str(file).replace("\\", "/").strip("/")
    return f"{PERSISTENZA_DRIVE_PREFISSO}{rel.replace('/', '__')}"


def _json_valido(dati):
    return isinstance(dati, (dict, list))


def _json_contiene_dati(dati):
    if isinstance(dati, dict):
        return len(dati) > 0
    if isinstance(dati, list):
        return len(dati) > 0
    return False


def _leggi_json_locale_senza_default(file):
    p = Path(file)
    if not p.exists() or not p.is_file():
        return None
    try:
        with p.open("r", encoding="utf-8") as f:
            dati = json.load(f)
        return dati if _json_valido(dati) else None
    except Exception:
        return None


def _trova_file_drive(service, nome_file, folder_id=GOOGLE_DRIVE_BACKUP_FOLDER_ID):
    nome_esc = str(nome_file).replace("\\", "\\\\").replace("'", "\\'")
    folder_esc = str(folder_id).replace("\\", "\\\\").replace("'", "\\'")
    q = (
        f"name = '{nome_esc}' and "
        f"'{folder_esc}' in parents and trashed = false"
    )
    res = service.files().list(
        q=q,
        spaces="drive",
        fields="files(id,name,modifiedTime,size)",
        orderBy="modifiedTime desc",
        pageSize=10,
        supportsAllDrives=True,
        includeItemsFromAllDrives=True,
    ).execute()
    files = res.get("files", [])
    return files[0] if files else None


def _scarica_json_drive(service, file):
    meta = _trova_file_drive(service, _drive_nome_live(file))
    if not meta:
        return None
    try:
        from googleapiclient.http import MediaIoBaseDownload

        request = service.files().get_media(fileId=meta["id"])
        buffer = io.BytesIO()
        downloader = MediaIoBaseDownload(buffer, request)
        done = False
        while not done:
            _, done = downloader.next_chunk()
        buffer.seek(0)
        dati = json.loads(buffer.read().decode("utf-8"))
        return dati if _json_valido(dati) else None
    except Exception:
        return None


def _scrivi_json_drive(service, file, dati):
    """Aggiorna/crea LIVE_<nome>.json nella cartella Drive configurata."""
    if not _json_valido(dati):
        return {"ok": False, "error": "Dati JSON non validi."}

    try:
        from googleapiclient.http import MediaIoBaseUpload

        payload = json.dumps(
            dati, indent=4, ensure_ascii=False
        ).encode("utf-8")
        media = MediaIoBaseUpload(
            io.BytesIO(payload),
            mimetype="application/json",
            resumable=False,
        )
        nome_live = _drive_nome_live(file)
        esistente = _trova_file_drive(service, nome_live)

        if esistente:
            meta = service.files().update(
                fileId=esistente["id"],
                media_body=media,
                fields="id,name,modifiedTime,size",
            ).execute()
        else:
            meta = service.files().create(
                body={
                    "name": nome_live,
                    "parents": [str(GOOGLE_DRIVE_BACKUP_FOLDER_ID)],
                },
                media_body=media,
                fields="id,name,modifiedTime,size",
            ).execute()

        return {"ok": True, **meta}
    except Exception as exc:
        return {"ok": False, "error": f"{type(exc).__name__}: {exc}"}



def _scrivi_binario_drive(service, nome_drive, dati_bytes, mime="application/octet-stream"):
    """Aggiorna/crea un piccolo file binario LIVE nella cartella Drive."""
    try:
        from googleapiclient.http import MediaIoBaseUpload
        media = MediaIoBaseUpload(io.BytesIO(dati_bytes), mimetype=mime, resumable=False)
        esistente = _trova_file_drive(service, nome_drive)
        if esistente:
            return service.files().update(
                fileId=esistente["id"], media_body=media,
                fields="id,name,modifiedTime,size"
            ).execute()
        return service.files().create(
            body={"name": nome_drive, "parents": [str(GOOGLE_DRIVE_BACKUP_FOLDER_ID)]},
            media_body=media,
            fields="id,name,modifiedTime,size"
        ).execute()
    except Exception as exc:
        st.session_state["errore_persistenza_logo_drive"] = f"{type(exc).__name__}: {exc}"
        return None


def _scarica_binario_drive(service, nome_drive):
    """Scarica un piccolo file binario LIVE da Drive."""
    meta = _trova_file_drive(service, nome_drive)
    if not meta:
        return None
    try:
        from googleapiclient.http import MediaIoBaseDownload
        req = service.files().get_media(fileId=meta["id"])
        buf = io.BytesIO()
        dl = MediaIoBaseDownload(buf, req)
        done = False
        while not done:
            _, done = dl.next_chunk()
        return buf.getvalue()
    except Exception:
        return None


def _ripristina_logo_da_drive(service):
    """Ripristina il logo società persistente prima del rendering UI."""
    try:
        cfg = _leggi_json_locale_senza_default(FILE_CONFIG_SOCIETA) or {}
        logo_cfg = str(cfg.get("logo", "") or "").strip()
        estensioni = []
        if logo_cfg:
            ext_cfg = Path(logo_cfg).suffix.lower()
            if ext_cfg in {".png", ".jpg", ".jpeg", ".webp"}:
                estensioni.append(ext_cfg)
        estensioni += [e for e in (".png", ".jpg", ".jpeg", ".webp") if e not in estensioni]

        Path(CARTELLA_ALLEGATI).mkdir(parents=True, exist_ok=True)
        for ext in estensioni:
            nome_drive = f"LIVE_logo_societa{ext}"
            dati = _scarica_binario_drive(service, nome_drive)
            if dati:
                locale = Path(CARTELLA_ALLEGATI) / f"logo_societa{ext}"
                locale.write_bytes(dati)
                # Allinea il path nel config se necessario.
                path_atteso = str(locale)
                if cfg.get("logo") != path_atteso:
                    cfg["logo"] = path_atteso
                    temp = FILE_CONFIG_SOCIETA + ".logo.tmp"
                    with open(temp, "w", encoding="utf-8") as f:
                        json.dump(cfg, f, indent=4, ensure_ascii=False)
                        f.flush()
                        os.fsync(f.fileno())
                    os.replace(temp, FILE_CONFIG_SOCIETA)
                return path_atteso
    except Exception:
        pass
    return ""


def inizializza_persistenza_drive():
    """Ripristina i file locali quando Drive possiede una copia migliore.

    Il controllo remoto viene eseguito una sola volta per sessione Streamlit,
    così login e cambio pagina non effettuano ripetute chiamate Google Drive.
    """
    global PERSISTENZA_DRIVE_ATTIVA, PERSISTENZA_DRIVE_ERRORE

    bootstrap_key = "_persistenza_drive_bootstrap_qr_ok" if _ACCESSO_QR_PRESENZE_RAPIDO else "_persistenza_drive_bootstrap_ok"
    if st.session_state.get(bootstrap_key):
        PERSISTENZA_DRIVE_ATTIVA = True
        return True

    service = _drive_service_persistenza()
    if service is None:
        PERSISTENZA_DRIVE_ATTIVA = False
        PERSISTENZA_DRIVE_ERRORE = (
            "Google Drive non disponibile o credenziali non configurate."
        )
        return False

    try:
        # Fase 1: prima RIPRISTINO; nessun upload finché non abbiamo
        # controllato tutte le copie remote.
        # Le pagine pubbliche devono apparire rapidamente: recuperano da Drive
        # soltanto gli archivi necessari al modulo richiesto, evitando decine
        # di interrogazioni riservate all'area amministrativa.
        if _ACCESSO_QR_PRESENZE_RAPIDO:
            # All'apertura del QR bastano token, stagione e gruppo. Gli altri
            # archivi vengono letti soltanto all'invio del modulo.
            file_da_controllare = [FILE_CONFIG_SOCIETA]
        elif _ACCESSO_STAFF_PUBBLICO_RAPIDO:
            file_da_controllare = [FILE_CONFIG_SOCIETA, FILE_STAFF_SOCIETA, FILE_SQUADRE]
        else:
            file_da_controllare = FILE_PERSISTENTI_DRIVE
        stato = []
        for file in file_da_controllare:
            locale = _leggi_json_locale_senza_default(file)
            remoto = _scarica_json_drive(service, file)
            stato.append((file, locale, remoto))

            # Drive è la fonte persistente autorevole all'avvio.
            # Su Streamlit Cloud i file locali possono provenire dal repository
            # ed essere non vuoti ma più vecchi/incompleti (es. calendario presente
            # ma classifica UISP appena sincronizzata assente). Se Drive ha una copia
            # valida e con dati, ripristiniamo SEMPRE quella.
            remoto_pieno = (
                remoto is not None and _json_contiene_dati(remoto)
            )

            if remoto_pieno:
                temp = str(file) + ".restore.tmp"
                with open(temp, "w", encoding="utf-8") as f:
                    json.dump(remoto, f, indent=4, ensure_ascii=False)
                    f.flush()
                    os.fsync(f.fileno())
                os.replace(temp, file)

        try:
            _carica_json_cached.clear()
        except Exception:
            pass

        # Il logo non serve alle pagine pubbliche: evita un'altra richiesta
        # remota durante il caricamento iniziale.
        if not _ACCESSO_MODULO_PUBBLICO_RAPIDO:
            _ripristina_logo_da_drive(service)

        # Solo adesso consentiamo la persistenza delle nuove modifiche.
        PERSISTENZA_DRIVE_ATTIVA = True
        PERSISTENZA_DRIVE_ERRORE = ""
        st.session_state[bootstrap_key] = True
        st.session_state.pop("errore_persistenza_drive", None)
        st.session_state.pop("_oauth_drive_error", None)

        # Fase 2: prima inizializzazione Drive, senza sovrascrivere
        # copie remote già presenti.
        for file, _, remoto_iniziale in stato:
            if remoto_iniziale is not None:
                continue
            locale = _leggi_json_locale_senza_default(file)
            if locale is not None:
                _scrivi_json_drive(service, file, locale)

        return True
    except Exception as exc:
        PERSISTENZA_DRIVE_ATTIVA = False
        PERSISTENZA_DRIVE_ERRORE = f"{type(exc).__name__}: {exc}"
        return False


def _audit_area_da_file(file):
    """Traduce l'archivio modificato in un'area comprensibile del gestionale."""
    nome = os.path.basename(str(file))
    mappa = {
        FILE_ATLETE: "Anagrafiche atlete", FILE_STAFF_SOCIETA: "Staff e dirigenti",
        FILE_SQUADRE: "Squadre e roster", FILE_ALLENAMENTI: "Allenamenti e presenze",
        FILE_PRESENZE_PROMO: "Presenze Minivolley e Scuola",
        FILE_GARE: "Calendario gare", FILE_SCOUT: "Scout e statistiche",
        FILE_STORICO_TECNICO: "Crescita tecnica", FILE_PRIMA_NOTA: "Prima nota",
        FILE_RICEVUTE: "Ricevute e pagamenti", FILE_BUDGET: "Budget",
        FILE_CONFIG_QUOTE: "Configurazione quote", FILE_CONFIG_COSTI_STANDARD: "Configurazione costi",
        FILE_CONFIG_VOCI_COSTI: "Configurazione costi", FILE_CATEGORIE_COSTI: "Categorie costi",
        FILE_GRUPPI: "Gruppi e categorie", FILE_CATEGORIE_GRUPPI: "Gruppi e categorie",
        FILE_UTENTI: "Utenti e permessi", FILE_CONFIG_SOCIETA: "Configurazione società",
        FILE_CONFIG_NOTIFICHE: "Configurazione notifiche", FILE_LOG_NOTIFICHE: "Notifiche",
        FILE_ARCHIVIO_FEDERALE: "Archivio federale", FILE_FIPAV_ATTIVITA: "Attività FIPAV",
        FILE_CAMPIONATI_ESTERNI: "Campionati esterni", FILE_CAL_SYNC: "Sincronizzazione calendari",
        FILE_UISP_MAPPING: "Sincronizzazione UISP", FILE_ATLETE_ELIMINATE_SYNC: "Sincronizzazione atlete",
        FILE_MAG_ARTICOLI: "Magazzino", FILE_MAG_MOVIMENTI: "Magazzino",
        FILE_MAG_CONSEGNE: "Magazzino", FILE_MAG_INVENTARI: "Magazzino", FILE_MAG_CATEGORIE: "Magazzino",
    }
    return mappa.get(str(file), mappa.get(nome, Path(nome).stem.replace("_", " ").title()))


def _audit_dimensione(dati):
    if isinstance(dati, (list, dict)):
        return len(dati)
    return 1 if dati is not None else 0


def _registra_attivita_globale(file, prima, dopo):
    """Registra le modifiche persistenti senza conservare dati personali nel log."""
    if str(file) == FILE_REGISTRO_ATTIVITA:
        return
    autenticato = bool(st.session_state.get("utente_autenticato"))
    compilazione_pubblica = bool(st.query_params.get("staff_modulo") or st.query_params.get("firma_modulo") or st.query_params.get("privacy_token") or st.query_params.get("presenze_qr") or st.query_params.get("allenamento_qr"))
    if not autenticato and not compilazione_pubblica:
        return
    prima_json = json.dumps(prima, ensure_ascii=False, sort_keys=True, default=str) if prima is not None else ""
    dopo_json = json.dumps(dopo, ensure_ascii=False, sort_keys=True, default=str)
    prima_hash = hashlib.sha256(prima_json.encode("utf-8")).hexdigest() if prima_json else ""
    dopo_hash = hashlib.sha256(dopo_json.encode("utf-8")).hexdigest()
    if prima_hash and hmac.compare_digest(prima_hash, dopo_hash):
        return
    n_prima, n_dopo = _audit_dimensione(prima), _audit_dimensione(dopo)
    if prima is None:
        operazione = "CREAZIONE DATI"
    elif n_dopo < n_prima:
        operazione = f"ELIMINAZIONE / RIDUZIONE ({n_prima} → {n_dopo})"
    elif n_dopo > n_prima:
        operazione = f"INSERIMENTO ({n_prima} → {n_dopo})"
    else:
        operazione = "MODIFICA DATI"
    try:
        if os.path.exists(FILE_REGISTRO_ATTIVITA):
            with open(FILE_REGISTRO_ATTIVITA, "r", encoding="utf-8") as f:
                registro = json.load(f)
        else:
            registro = []
        if not isinstance(registro, list):
            registro = []
        precedente = str(registro[-1].get("hash_evento", "")) if registro else ""
        evento = {
            "id": uuid.uuid4().hex,
            "data_ora": ora_italiana().strftime("%d/%m/%Y %H:%M:%S"),
            "timestamp": ora_italiana().isoformat(timespec="seconds"),
            "utente": str(st.session_state.get("username_corrente", "compilazione pubblica")),
            "ruolo": str(st.session_state.get("ruolo_corrente", "Esterno" if not autenticato else "")),
            "stagione": str(globals().get("stagione_selezionata", "")),
            "area": _audit_area_da_file(file),
            "archivio": os.path.basename(str(file)),
            "operazione": operazione,
            "elementi_prima": n_prima, "elementi_dopo": n_dopo,
            "hash_prima": prima_hash, "hash_dopo": dopo_hash,
            "hash_precedente": precedente,
        }
        corpo_hash = json.dumps(evento, ensure_ascii=False, sort_keys=True, default=str)
        evento["hash_evento"] = hashlib.sha256(corpo_hash.encode("utf-8")).hexdigest()
        registro.append(evento)
        registro = registro[-50000:]
        temp_audit = FILE_REGISTRO_ATTIVITA + ".tmp"
        with open(temp_audit, "w", encoding="utf-8") as f:
            json.dump(registro, f, indent=2, ensure_ascii=False)
            f.flush(); os.fsync(f.fileno())
        os.replace(temp_audit, FILE_REGISTRO_ATTIVITA)
        if PERSISTENZA_DRIVE_ATTIVA and FILE_REGISTRO_ATTIVITA in FILE_PERSISTENTI_DRIVE:
            servizio_audit = _drive_service_persistenza()
            if servizio_audit is not None:
                _scrivi_json_drive(servizio_audit, FILE_REGISTRO_ATTIVITA, registro)
    except Exception as exc:
        st.session_state["errore_registro_attivita"] = f"{type(exc).__name__}: {exc}"


def salva_json_sicuro(file, dati):
    """Salvataggio atomico locale + copia persistente Google Drive."""
    prima = _leggi_json_locale_senza_default(file)
    esegui_backup(file)
    temp_file = file + ".tmp"
    with open(temp_file, "w", encoding="utf-8") as f:
        json.dump(dati, f, indent=4, ensure_ascii=False)
        f.flush()
        os.fsync(f.fileno())
    os.replace(temp_file, file)
    _registra_attivita_globale(file, prima, dati)

    try:
        _carica_json_cached.clear()
    except Exception:
        pass

    # Non blocca mai il gestionale se Drive ha un problema temporaneo.
    if PERSISTENZA_DRIVE_ATTIVA and file in FILE_PERSISTENTI_DRIVE:
        service = _drive_service_persistenza()
        if service is not None:
            risultato = _scrivi_json_drive(service, file, dati)
            if not risultato.get("ok"):
                st.session_state["errore_persistenza_drive"] = risultato.get(
                    "error", "Errore Google Drive sconosciuto."
                )
            else:
                st.session_state.pop("errore_persistenza_drive", None)
                st.session_state["ultimo_salvataggio_persistente_drive"] = (
                    ora_italiana().strftime("%d/%m/%Y %H:%M:%S")
                )
                st.session_state["ultimo_file_persistente_drive"] = str(file)

    if not st.session_state.get("_backup_auto_check_dopo_salvataggio"):
        st.session_state["_backup_auto_check_dopo_salvataggio"] = True
        _auto_backup = globals().get("esegui_backup_automatico_drive")
        if callable(_auto_backup):
            try:
                _auto_backup(force=False)
            except Exception:
                pass


# IMPORTANTISSIMO: il ripristino viene eseguito prima dei primi carica_json()
# top-level dell'applicazione.
inizializza_persistenza_drive()


def _presenze_rileggi_da_drive(file, default):
    """Recupera l'ultima copia condivisa e allinea la copia locale."""
    try:
        service = _drive_service_persistenza()
        remoto = _scarica_json_drive(service, file) if service is not None else None
        if isinstance(remoto, type(default)):
            temp = str(file) + ".presenze_sync.tmp"
            with open(temp, "w", encoding="utf-8") as f:
                json.dump(remoto, f, indent=4, ensure_ascii=False)
                f.flush()
                os.fsync(f.fileno())
            os.replace(temp, file)
            try:
                _carica_json_cached.clear()
            except Exception:
                pass
            return remoto
    except Exception as exc:
        st.session_state["errore_sync_presenze_drive"] = f"{type(exc).__name__}: {exc}"
    locale = carica_json(file, default)
    return locale if isinstance(locale, type(default)) else default


def safe_float(val, default=0.0):
    if val is None:
        return default
    try:
        return float(str(val).replace(",", "."))
    except Exception:
        return default


def nome_file_sicuro(nome):
    nome = Path(str(nome)).name
    stem = re.sub(r"[^A-Za-z0-9._-]+", "_", Path(nome).stem).strip("._") or "file"
    ext = Path(nome).suffix.lower()
    return f"{stem[:80]}_{uuid.uuid4().hex}{ext}"


def certificato_presente(atleta):
    """Vero solo se il certificato è realmente disponibile come file locale.
    Un semplice URL proveniente da Google Form non viene considerato
    automaticamente come certificato presente: evita falsi "✅ Presente".
    """
    path = str(atleta.get("allegato_visita", "") or "").strip()
    if path:
        try:
            if os.path.isfile(path) and os.path.getsize(path) > 0:
                return True
        except OSError:
            pass
    return False


def salva_allegato(uploaded_file, prefisso):
    dati = uploaded_file.getvalue()
    if len(dati) > MAX_UPLOAD_BYTES:
        raise ValueError("Il file supera il limite di 10 MB")
    prefisso = re.sub(r"[^A-Za-z0-9_-]+", "_", str(prefisso)).strip("_")[:80] or "allegato"
    destinazione = os.path.join(CARTELLA_ALLEGATI, f"{prefisso}_{nome_file_sicuro(uploaded_file.name)}")
    with open(destinazione, "wb") as f:
        f.write(dati)
    return destinazione


def salva_documento_atleta(uploaded_file, atleta, tipo):
    """Salva il documento in una cartella fisicamente separata per atleta."""
    dati = uploaded_file.getvalue()
    if len(dati) > MAX_UPLOAD_BYTES:
        raise ValueError("Il file supera il limite di 10 MB")
    atleta_id = re.sub(r"[^A-Za-z0-9_-]+", "_", str((atleta or {}).get("id", "") or "senza_id"))[:80]
    tipo_safe = re.sub(r"[^A-Za-z0-9_-]+", "_", str(tipo or "documento")).strip("_") or "documento"
    folder = Path(CARTELLA_ALLEGATI) / "atleti" / atleta_id / tipo_safe
    folder.mkdir(parents=True, exist_ok=True)
    prefisso = re.sub(r"[^A-Za-z0-9_-]+", "_", f"{atleta.get('cognome','atleta')}_{atleta.get('nome','')}_{tipo_safe}").strip("_")[:100]
    destinazione = folder / f"{prefisso}_{nome_file_sicuro(uploaded_file.name)}"
    destinazione.write_bytes(dati)
    return str(destinazione), hashlib.sha256(dati).hexdigest()


def _documento_sembra_privacy(dati):
    if not dati or not bytes(dati).startswith(b"%PDF"):
        return False
    try:
        from pypdf import PdfReader
        reader = PdfReader(io.BytesIO(bytes(dati)), strict=False)
        testo = "\n".join((p.extract_text() or "") for p in reader.pages[:12]).upper()
        indicatori = ("CONSENSO PRIVACY E LIBERATORIA", "INFORMATIVA ATLETA MINORE", "CONSENSO AL TRATTAMENTO DEI DATI PERSONALI")
        return any(x in testo for x in indicatori)
    except Exception:
        return False


def _nome_download_documento(atleta, label, path):
    nome_atleta = _firma_modulo_nome_sicuro(f"{atleta.get('cognome','')} {atleta.get('nome','')}")
    tipo = _firma_modulo_nome_sicuro(label)
    stagione = _firma_modulo_nome_sicuro(atleta.get("stagione", "SENZA_STAGIONE"))
    ext = Path(str(path)).suffix.lower() or ".pdf"
    return f"{nome_atleta}_{tipo}_{stagione}{ext}"
def controlla_visita(data_str):
    if data_str is None or str(data_str).strip().lower() in {"nan", "none", "nat", ""}:
        return "🔴 MANCANTE"
    txt = str(data_str).strip()
    dt = None
    for fmt in (
        "%d/%m/%Y", "%d/%m/%Y %H:%M:%S", "%Y-%m-%d", "%Y-%m-%d %H:%M:%S",
        "%d-%m-%Y", "%d-%m-%Y %H:%M:%S", "%Y/%m/%d", "%Y/%m/%d %H:%M:%S",
    ):
        try:
            dt = datetime.strptime(txt, fmt)
            break
        except ValueError:
            continue
    if dt is None:
        try:
            ts = pd.to_datetime(txt, errors="coerce", dayfirst=True)
            if not pd.isna(ts):
                dt = ts.to_pydatetime() if hasattr(ts, "to_pydatetime") else ts
        except Exception:
            dt = None
    if dt is None:
        return "🟠 DATA NON VALIDA"
    # Coerente con tutto il gestionale: data locale Europe/Rome.
    delta = (dt.date() - ora_italiana().date()).days
    if delta < 0:
        return "🔴 SCADUTA"
    if delta <= 30:
        return "🟡 IN SCADENZA"
    return "🟢 VALIDA"
def normalizza_nome_gruppo(nome):
    if not nome or str(nome).strip().lower() in ["nan", "none", ""]:
        return ""
    return str(nome).strip().title()


def normalizza_intestazione_colonna(valore):
    testo = str(valore or "").strip().lower()
    testo = unicodedata.normalize("NFKD", testo).encode("ascii", "ignore").decode("ascii")
    return re.sub(r"[^a-z0-9]+", " ", testo).strip()
def normalizza_sesso(valore):
    v = normalizza_intestazione_colonna(valore)
    if v in {"m", "maschio", "male", "uomo", "bambino", "ragazzo"}:
        return "M"
    if v in {"f", "femmina", "female", "donna", "bambina", "ragazza"}:
        return "F"
    return ""


def _gruppo_key(gruppo):
    """Chiave normalizzata per confrontare nomi gruppo in modo stabile."""
    txt = normalizza_intestazione_colonna(gruppo)
    txt = txt.replace(" degree ", " ")
    txt = re.sub(r"\s+", " ", txt).strip()
    return txt


def _gruppo_key_compact(gruppo):
    return re.sub(r"[^a-z0-9]", "", _gruppo_key(gruppo))
def _sync_norm_persona(valore):
    return re.sub(r"[^a-z0-9]", "", normalizza_intestazione_colonna(valore))
def _sync_norm_cf(valore):
    return re.sub(r"[^A-Z0-9]", "", str(valore or "").strip().upper())


def _chiave_tombstone_atleta(sync_key="", cognome="", nome="", cf="", stagione=""):
    return (
        str(stagione or "").strip(),
        str(sync_key or "").strip(),
        _sync_norm_persona(cognome),
        _sync_norm_persona(nome),
        _sync_norm_cf(cf),
    )
def _atleta_bloccata_sync(atleta, stagione, eliminati=None):
    record_list = eliminati if eliminati is not None else st.session_state.get("atlete_eliminate_sync", [])
    target_sync = str(atleta.get("sync_key", "") or "").strip()
    target_nome = _sync_norm_persona(atleta.get("cognome", ""))
    target_nome2 = _sync_norm_persona(atleta.get("nome", ""))
    target_cf = _sync_norm_cf(atleta.get("cf", ""))
    target = _chiave_tombstone_atleta(target_sync, target_nome, target_nome2, target_cf, stagione)
    for item in record_list or []:
        if not isinstance(item, dict):
            continue
        if _chiave_tombstone_atleta(item.get("sync_key", ""), item.get("cognome", ""), item.get("nome", ""), item.get("cf", ""), item.get("stagione", "")) == target:
            return True
        # Match stabile anche se il sync_key della riga Google e' cambiato.
        if str(item.get("stagione", "")).strip() == str(stagione or "").strip():
            i_sync = str(item.get("sync_key", "") or "").strip()
            if i_sync and target_sync and i_sync == target_sync:
                return True
            i_cf = _sync_norm_cf(item.get("cf", ""))
            i_cognome = _sync_norm_persona(item.get("cognome", ""))
            i_nome = _sync_norm_persona(item.get("nome", ""))
            if target_cf and i_cf and target_cf == i_cf and target_nome == i_cognome and target_nome2 == i_nome:
                return True
            if (not target_cf) and (not i_cf) and target_nome and target_nome2 and target_nome == i_cognome and target_nome2 == i_nome:
                return True
    return False


def registra_atlete_eliminate(atlete):
    elenco = st.session_state.setdefault("atlete_eliminate_sync", [])
    now = ora_italiana().strftime("%Y-%m-%d %H:%M:%S")
    for atleta in atlete:
        rec = {
            "id": str(atleta.get("id", "") or ""),
            "sync_key": str(atleta.get("sync_key", "") or "").strip(),
            "cognome": str(atleta.get("cognome", "") or "").strip(),
            "nome": str(atleta.get("nome", "") or "").strip(),
            "cf": str(atleta.get("cf", "") or "").strip(),
            "stagione": str(atleta.get("stagione", "") or "").strip(),
            "gruppo": str(atleta.get("gruppo", "") or "").strip(),
            "eliminata_il": now,
        }
        # Evita di creare più tombstone per la stessa atleta.
        elenco[:] = [r for r in elenco if not _atleta_bloccata_sync(r, rec["stagione"], [rec])]
        elenco.append(rec)
    elenco[:] = elenco[-2000:]
    try:
        salva_json_sicuro(FILE_ATLETE_ELIMINATE_SYNC, elenco)
    except Exception:
        pass


def elimina_tombstone_atlete(ids):
    ids = {str(x or "") for x in ids if x}
    elenco = st.session_state.setdefault("atlete_eliminate_sync", [])
    before = len(elenco)
    st.session_state["atlete_eliminate_sync"] = [r for r in elenco if str(r.get("id", "")) not in ids]
    if len(st.session_state["atlete_eliminate_sync"]) != before:
        try:
            salva_json_sicuro(FILE_ATLETE_ELIMINATE_SYNC, st.session_state["atlete_eliminate_sync"])
        except Exception:
            pass
def _normalizza_mappa_categorie_gruppi(valore):
    """Accetta sia il vecchio formato dict gruppo->categoria sia il formato lista."""
    risultato = {}
    if isinstance(valore, dict):
        for gruppo, categoria in valore.items():
            g = normalizza_nome_gruppo(gruppo)
            cat = str(categoria or "").strip().upper()
            if g and cat in {"PROMOZIONALE", "GIOVANILE"}:
                risultato[_gruppo_key(g)] = cat
    elif isinstance(valore, list):
        # Compatibilità opzionale con un vecchio elenco di record.
        for item in valore:
            if isinstance(item, dict):
                g = normalizza_nome_gruppo(item.get("gruppo", ""))
                cat = str(item.get("categoria", "")).strip().upper()
                if g and cat in {"PROMOZIONALE", "GIOVANILE"}:
                    risultato[_gruppo_key(g)] = cat
    return risultato
def salva_mappa_categorie_gruppi():
    """Salva l'associazione persistente gruppo -> categoria."""
    salva_json_sicuro(FILE_CATEGORIE_GRUPPI, st.session_state.get("categorie_gruppi", {}))
def categoria_da_gruppo(gruppo):
    """Fonte unica di verità: prima la configurazione admin, poi i gruppi standard."""
    key = _gruppo_key(gruppo)
    compact = _gruppo_key_compact(gruppo)

    # 1) Configurazione esplicita dell'amministratore.
    mappa = st.session_state.get("categorie_gruppi", {})
    if key in mappa:
        return mappa[key]

    # 2) Gruppi standard.
    promo_compact = {_gruppo_key_compact(g) for g in GRUPPI_PER_CATEGORIA["PROMOZIONALE"]}
    giov_compact = {_gruppo_key_compact(g) for g in GRUPPI_PER_CATEGORIA["GIOVANILE"]}
    if compact in promo_compact:
        return "PROMOZIONALE"
    if compact in giov_compact:
        return "GIOVANILE"
    # 3) Compatibilità con varianti comuni.
    if compact == "20152016" or compact in {"2016", "2017", "2018", "silver", "silver2", "minivolley", "scuola"}:
        return "PROMOZIONALE"
    if re.fullmatch(r"u(13|14|15|17|19)", compact):
        return "GIOVANILE"
    if compact in {"gold", "goldabbadia", "goldosaco", "1divisione", "2divisione", "seried", "seriec", "serieb2", "nonclassificato"}:
        return "GIOVANILE"
    return ""
def normalizza_categoria(valore, gruppo=""):
    """Il gruppo ha sempre precedenza sulla categoria scritta nei vecchi dati."""
    by_group = categoria_da_gruppo(gruppo)
    if by_group:
        return by_group
    raw = str(valore or "").strip().upper()
    if "PROMO" in raw:
        return "PROMOZIONALE"
    if "GIOVAN" in raw or "UNDER" in raw:
        return "GIOVANILE"
    return "PROMOZIONALE"
def gruppo_display_per_categoria(categoria):
    """Restituisce gruppi standard + gruppi personalizzati della categoria scelta."""
    cat = "GIOVANILE" if str(categoria or "").upper().startswith("GIOV") else "PROMOZIONALE"
    gruppi = [normalizza_nome_gruppo(g) for g in GRUPPI_PER_CATEGORIA[cat]]
    mappa = st.session_state.get("categorie_gruppi", {})
    for gruppo in st.session_state.get("gruppi_societa", []):
        ng = normalizza_nome_gruppo(gruppo)
        if ng and categoria_da_gruppo(ng) == cat and ng.lower() not in {x.lower() for x in gruppi}:
            gruppi.append(ng)
    return gruppi
