def logo_societa_path():
    percorso = str(config_societa.get("logo", "") or "").strip()
    candidati = []
    if percorso:
        candidati.extend([
            Path(percorso),
            Path(CARTELLA_ALLEGATI) / Path(percorso).name,
            Path("allegati") / Path(percorso).name,
        ])
    for candidato in candidati:
        try:
            if candidato.exists():
                return str(candidato)
        except OSError:
            pass
    return ""
def salva_logo_societa(uploaded_file):
    if not uploaded_file:
        return ""
    try:
        ext = Path(uploaded_file.name).suffix.lower()
        if ext not in {".png", ".jpg", ".jpeg", ".webp"}:
            raise ValueError("Il logo deve essere PNG, JPG o WEBP.")
        for vecchia_estensione in (".png", ".jpg", ".jpeg", ".webp"):
            vecchio = Path(CARTELLA_ALLEGATI) / f"logo_societa{vecchia_estensione}"
            if vecchio.exists() and vecchio.name != f"logo_societa{ext}":
                try:
                    vecchio.unlink()
                except OSError:
                    pass
        destinazione = Path(CARTELLA_ALLEGATI) / f"logo_societa{ext}"
        dati_logo = uploaded_file.getvalue()
        destinazione.write_bytes(dati_logo)

        # Persistenza dedicata del logo su Drive.
        if PERSISTENZA_DRIVE_ATTIVA:
            service = _drive_service_persistenza()
            if service is not None:
                mime_map = {
                    ".png": "image/png", ".jpg": "image/jpeg",
                    ".jpeg": "image/jpeg", ".webp": "image/webp"
                }
                _scrivi_binario_drive(
                    service,
                    f"LIVE_logo_societa{ext}",
                    dati_logo,
                    mime_map.get(ext, "application/octet-stream")
                )
        return str(destinazione)
    except OSError as exc:
        raise ValueError(f"Impossibile salvare il logo: {exc}")
def rimuovi_logo_societa():
    percorso = str(config_societa.get("logo", "") or "")
    candidati = []
    if percorso:
        candidati += [Path(percorso), Path(CARTELLA_ALLEGATI) / Path(percorso).name]
    for ext in (".png", ".jpg", ".jpeg", ".webp"):
        candidati.append(Path(CARTELLA_ALLEGATI) / f"logo_societa{ext}")
    for candidato in candidati:
        try:
            candidato.unlink(missing_ok=True)
        except OSError:
            pass
    config_societa["logo"] = ""

    # Rimuove anche le copie LIVE del logo da Drive.
    if PERSISTENZA_DRIVE_ATTIVA:
        try:
            service = _drive_service_persistenza()
            if service is not None:
                for ext in (".png", ".jpg", ".jpeg", ".webp"):
                    meta = _trova_file_drive(service, f"LIVE_logo_societa{ext}")
                    if meta:
                        service.files().delete(fileId=meta["id"]).execute()
        except Exception:
            pass
