def _normalizza_firma_png_b64(dati):
    """Converte JPEG/PNG in un PNG compatto, orientato e con il bianco trasparente."""
    raw=bytes(dati or b'')
    if not raw:
        raise ValueError('Il file della firma è vuoto.')
    if len(raw)>2*1024*1024:
        raise ValueError('La firma supera 2 MB. Usa un’immagine più leggera.')
    try:
        img=ImageOps.exif_transpose(Image.open(io.BytesIO(raw))).convert('RGBA')
    except Exception as exc:
        raise ValueError(f'Immagine firma non leggibile: {exc}')
    img.thumbnail((1400,500),Image.Resampling.LANCZOS)
    pixel=[]
    for r,g,b,a in img.getdata():
        # I JPEG non hanno trasparenza: rendiamo trasparente lo sfondo quasi bianco.
        if r>=245 and g>=245 and b>=245:
            pixel.append((255,255,255,0))
        else:
            pixel.append((r,g,b,a))
    img.putdata(pixel)
    alpha=img.getchannel('A'); bbox=alpha.getbbox()
    if bbox:
        img=img.crop(bbox)
    out=io.BytesIO(); img.save(out,format='PNG',optimize=True)
    return base64.b64encode(out.getvalue()).decode('ascii')

def _dati_societa_ricevuta(ricevuta):
    # Le ricevute nuove conservano uno snapshot: modifiche future alla configurazione
    # non alterano i documenti gia emessi. Le vecchie usano la configurazione corrente.
    snap = ricevuta.get("societa_snapshot") if isinstance(ricevuta, dict) else None
    if isinstance(snap, dict) and snap:
        # Le ricevute emesse prima dell'introduzione dei dati completi del legale
        # rappresentante contengono snapshot parziali: integriamo SOLO i campi
        # mancanti con i dati ufficiali configurati. Gli snapshot completi restano immutabili.
        dati = dict(snap)
        for _k in DEFAULT_DATI_RICEVUTE:
            if not str(dati.get(_k, "") or "").strip():
                dati[_k] = config_societa.get(_k, DEFAULT_DATI_RICEVUTE[_k])
        return dati
    return dict(config_societa)

def genera_pdf_ricevuta_v2(ricevuta, atleta, societa):
    """Ricevuta formale A4: wrapping per parole intere e impaginazione stabile."""
    buffer = io.BytesIO()
    p = canvas.Canvas(buffer, pagesize=A4)
    width, height = A4
    sx, dx = 50, width - 50
    usable_w = dx - sx
    cfg = _dati_societa_ricevuta(ricevuta)

    def draw_wrapped(text, x, y, font="Times-Roman", size=11, leading=15, max_width=None):
        """Disegna testo senza spezzare mai le parole a meta'."""
        max_width = max_width or usable_w
        p.setFont(font, size)
        words = str(text or "").split()
        if not words:
            return y
        line = words[0]
        for word in words[1:]:
            candidate = line + " " + word
            if pdfmetrics.stringWidth(candidate, font, size) <= max_width:
                line = candidate
            else:
                p.drawString(x, y, line)
                y -= leading
                line = word
        p.drawString(x, y, line)
        return y - leading

    # Doppio logo.
    pin_logo = _pinerolo_logo_reader()
    if pin_logo:
        try:
            p.drawImage(pin_logo, sx, height-126, width=86, height=86,
                        preserveAspectRatio=True, anchor='c', mask='auto')
        except Exception:
            pass
    monviso_logo = logo_societa_path()
    if monviso_logo:
        try:
            p.drawImage(ImageReader(monviso_logo), dx-86, height-120, width=86, height=74,
                        preserveAspectRatio=True, anchor='c', mask='auto')
        except Exception:
            pass

    tipo = str(ricevuta.get("tipo", "Ricevuta / quietanza (non fiscale)"))
    fiscale = tipo.startswith("Fiscale")
    detraibile = bool(ricevuta.get('detraibile',True))
    p.setFont("Times-Bold", 18)
    p.drawCentredString(width/2, height-62,
                        ("RICEVUTA DI PAGAMENTO" if detraibile else "QUIETANZA DI PAGAMENTO") if not fiscale else "BOZZA DATI DOCUMENTO FISCALE")
    p.setFont("Times-Bold", 11)
    p.drawCentredString(width/2, height-84,
                        ("Ai sensi e per gli effetti dell'art. 1, c. 319 L. n. 296 del 27.12.2006" if detraibile else "SINGOLO PAGAMENTO - DOCUMENTO NON DETRAIBILE"))
    p.setFont("Helvetica", 9)
    p.drawCentredString(width/2, height-103,
                        f"N. {ricevuta.get('numero','-')}  -  Emessa il {ricevuta.get('data_emissione','-')}")

    y = height - 174
    rapp = str(cfg.get('rappresentante','') or '').strip()
    luogo_r = str(cfg.get('rappresentante_luogo_nascita','') or '').strip()
    data_r = str(cfg.get('rappresentante_data_nascita','') or '').strip()
    denom = str(cfg.get('denominazione_ricevute','') or cfg.get('nome','') or societa or 'Societa sportiva').strip()
    sede = str(cfg.get('sede','') or '').strip()
    fipav = str(cfg.get('cod_fipav','') or '').strip()
    coni = str(cfg.get('numero_coni','') or '').strip()
    piva = str(cfg.get('piva_cf','') or '').strip()

    intro = f"Il sottoscritto {rapp or '-'}"
    if luogo_r: intro += f", nato a {luogo_r}"
    if data_r: intro += f" il {data_r}"
    intro += f", in qualita di presidente e legale rappresentante della {denom}"
    if fipav: intro += f" - cod. Fipav {fipav}"
    if coni: intro += f" - N. registrazione CONI {coni}"
    if sede: intro += f", con sede in {sede}"
    if piva: intro += f" - P. IVA/C.F. {piva}"
    y = draw_wrapped(intro, sx, y, "Times-Roman", 10.7, 15)

    y -= 9
    p.setFont("Times-Bold", 14)
    p.drawCentredString(width/2, y, "ATTESTA")
    y -= 25

    importo = safe_float(ricevuta.get('importo',0))
    imp_it = f"{importo:,.2f}".replace(',', 'X').replace('.', ',').replace('X', '.')
    stagione = str(ricevuta.get('stagione','-')).replace('-', '/')
    testo = (f"di aver ricevuto in data {ricevuta.get('data_pagamento','-')} la somma di Euro {imp_it} "
             f"({_importo_lettere_it(importo)}) per la quota associativa e di partecipazione all'attivita sportiva "
             f"di {ricevuta.get('attivita_sportiva','Pallavolo')} svolta nella stagione sportiva {stagione} "
             f"dall'associata/o")
    y = draw_wrapped(testo, sx, y, "Times-Roman", 10.7, 15)

    y -= 7
