    if cfg.get('dicitura_detrazione_ricevute', True) and not fiscale and ricevuta.get('detraibile',True):
        nota = ("La presente attestazione viene rilasciata anche ai fini della detrazione IRPEF prevista dall'art. 15, c. 1, "
                "lett. i-quinquies, D.P.R. 917/1986 e relativo decreto di attuazione, qualora spettante.")
        y = draw_wrapped(nota, sx, y, "Times-Roman", 9.4, 13)
    elif fiscale:
        y = draw_wrapped("BOZZA / PRO-MEMORIA: questo PDF non e una fattura elettronica e non viene trasmesso allo SDI.",
                         sx, y, "Times-Bold", 9, 12)
    elif not ricevuta.get('detraibile',True):
        y = draw_wrapped("Quietanza del singolo pagamento. Documento non utilizzabile ai fini della detrazione IRPEF: sara sostituito dalla certificazione cumulativa del periodo.",
                         sx, y, "Times-Bold", 9, 12)

    if ricevuta.get('note'):
        y -= 3
        y = draw_wrapped("Note: " + str(ricevuta.get('note')), sx, y, "Times-Roman", 9, 12)

    # Chiusura: posizione minima per lasciare respiro e firma ben separata.
    y = min(y - 12, 205)
    p.setFont("Times-Roman", 11)
    p.drawString(sx, y, "In fede.")
    y -= 34
    luogo = str(cfg.get("citta_ricevuta", "") or "Pinerolo").strip()
    p.drawString(sx, y, f"{luogo}, {ricevuta.get('data_emissione','')}")

    firma_x = 330
    firma_c = (firma_x + dx) / 2
    p.setFont("Times-Bold", 10.7)
    p.drawCentredString(firma_c, y, denom[:52])
    p.setFont("Times-Roman", 10.3)
    p.drawCentredString(firma_c, y-17, f"Il Presidente {rapp}".strip())
    firma_img=_firma_presidente_reader(cfg)
    if firma_img:
        try: p.drawImage(firma_img,firma_x+30,y-67,width=125,height=42,preserveAspectRatio=True,anchor='c',mask='auto')
        except Exception: pass
    p.line(firma_x, y-70, dx, y-70)

    p.showPage()
    p.save()
    buffer.seek(0)
    return buffer.getvalue()

