        p.setFont(font,size); parole=str(text or '').split(); riga=''
        for parola in parole:
            test=(riga+' '+parola).strip()
            if not riga or pdfmetrics.stringWidth(test,font,size)<=dx-sx:
                riga=test
            else:
                p.drawString(sx,y,riga); y-=leading; riga=parola
