def carica_archivio_federale():
    db = carica_json(FILE_ARCHIVIO_FEDERALE, {})
    if not isinstance(db, dict):
        db = {}
    db.setdefault('documenti', [])
    db.setdefault('persone', [])
    db.setdefault('partecipazioni', [])
    db.setdefault('versione_schema', 1)
    return db


def salva_archivio_federale(db):
    db['aggiornato_il'] = ora_italiana().isoformat(timespec='seconds')
    salva_json_sicuro(FILE_ARCHIVIO_FEDERALE, db)

def _af_incorpora_documento(doc, data):
    """Conserva il file originale nel database per poterlo riscaricare e includere nei backup."""
    if not isinstance(data, (bytes, bytearray)):
        return False
    dati = bytes(data)
    # Evita di rendere ingestibile il JSON centrale con singoli allegati eccezionalmente grandi.
    if len(dati) > 50 * 1024 * 1024:
        doc['allegato_errore'] = 'File superiore a 50 MB: conservati dati e impronta, non il contenuto.'
        return False
    nome = str(doc.get('nome_file', '')).lower()
    if nome.endswith('.pdf'):
        mime = 'application/pdf'
    elif nome.endswith('.xlsx'):
        mime = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    elif nome.endswith('.xls'):
        mime = 'application/vnd.ms-excel'
    else:
        mime = 'application/octet-stream'
    doc['contenuto_b64'] = base64.b64encode(dati).decode('ascii')
    doc['dimensione_bytes'] = len(dati)
    doc['mime_type'] = mime
    doc.pop('allegato_errore', None)
    return True

def _af_bytes_documento(doc):
    try:
        return base64.b64decode(str(doc.get('contenuto_b64', '') or ''), validate=True)
    except Exception:
        return b''

def _af_zip_documenti_originali(documenti):
    """Raccoglie in uno ZIP tutti gli originali realmente conservati nell'archivio."""
    out=io.BytesIO(); aggiunti=0; usati=set()
    with zipfile.ZipFile(out,'w',compression=zipfile.ZIP_DEFLATED) as zf:
        for posizione,doc in enumerate(documenti,1):
            dati=_af_bytes_documento(doc)
            if not dati:
                continue
            nome=nome_file_sicuro(str(doc.get('nome_file') or f'documento_{posizione}'))
            base,ext=os.path.splitext(nome)
            candidato=nome; n=2
            while candidato.lower() in usati:
                candidato=f'{base}_{n}{ext}'; n+=1
            usati.add(candidato.lower())
            zf.writestr(candidato,dati); aggiunti+=1
    out.seek(0)
    return out.getvalue(),aggiunti

def _af_excel_completo(db, risultati=None):
    """Esporta l'archivio federale relazionale in un unico workbook."""
    out = io.BytesIO()
    with pd.ExcelWriter(out, engine='openpyxl') as writer:
        # Il contenuto binario originale resta nel backup JSON e non viene scritto in una cella Excel.
        pd.DataFrame(db.get('documenti', [])).drop(
            columns=['contenuto_b64','_allegato_appena_recuperato'],errors='ignore'
        ).to_excel(writer, index=False, sheet_name='Documenti')
        pd.DataFrame(db.get('persone', [])).to_excel(writer, index=False, sheet_name='Persone')
        pd.DataFrame(db.get('partecipazioni', [])).to_excel(writer, index=False, sheet_name='Partecipazioni')
        if risultati is not None:
            pd.DataFrame(risultati).to_excel(writer, index=False, sheet_name='Risultati ricerca')
    out.seek(0)
    return out.getvalue()

def _af_dataframe_excel(df, titolo, sottotitolo='Archivio Federale', sheet_name='Risultati'):
    """Crea l'Excel di una singola vista dell'archivio senza dipendere dai moduli del calendario."""
    out = io.BytesIO()
    with pd.ExcelWriter(out, engine='openpyxl') as writer:
        df.to_excel(writer, index=False, sheet_name=sheet_name[:31], startrow=3)
        ws = writer.book[sheet_name[:31]]
        ws['A1'] = titolo
        ws['A2'] = sottotitolo
        for col_cells in ws.columns:
            max_len = max([len(str(c.value or '')) for c in col_cells] + [10])
            ws.column_dimensions[col_cells[0].column_letter].width = min(max(max_len + 2, 11), 38)
    return out.getvalue()

def _af_dataframe_pdf(df, titolo, sottotitolo='Archivio Federale'):
    """Crea il PDF di una singola vista dell'archivio."""
    out = io.BytesIO()
    doc = SimpleDocTemplate(
        out, pagesize=(A4[1], A4[0]),
        rightMargin=16, leftMargin=16, topMargin=18, bottomMargin=18
    )
    styles = getSampleStyleSheet()
    story = [
        Paragraph(f'<b>{titolo}</b>', styles['Heading1']),
        Paragraph(str(sottotitolo), styles['Normal']),
        Spacer(1, 8),
    ]
    if df is not None and not df.empty:
        cols = list(df.columns)
        data = [cols] + [[str(x) for x in row] for row in df.astype(str).values.tolist()]
        page_w = A4[1] - 32
        widths = [max(48, min(150, page_w / max(len(cols), 1))) for _ in cols]
        tab = Table(data, repeatRows=1, colWidths=widths)
        tab.setStyle(TableStyle([
            ('BACKGROUND',(0,0),(-1,0),colors.lightgrey),
            ('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),
            ('FONTSIZE',(0,0),(-1,-1),6.8),
            ('GRID',(0,0),(-1,-1),0.35,colors.grey),
            ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
            ('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white, colors.whitesmoke]),
        ]))
        story.append(tab)
    doc.build(story)
    return out.getvalue()

def _af_pulsanti_export_dataframe(df, prefisso, titolo, key):
    """Download coerenti per qualunque vista tabellare dell'Archivio Federale."""
    if df is None or df.empty:
        return
    c1,c2,c3=st.columns(3)
    c1.download_button('⬇️ CSV',df.to_csv(index=False).encode('utf-8-sig'),
                       file_name=f'{prefisso}.csv',mime='text/csv',use_container_width=True,key=f'{key}_csv')
    c2.download_button('📊 EXCEL',_af_dataframe_excel(df,titolo,'Archivio Federale','Risultati'),
                       file_name=f'{prefisso}.xlsx',mime='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
                       use_container_width=True,key=f'{key}_xlsx')
    c3.download_button('📄 PDF',_af_dataframe_pdf(df,titolo,'Archivio Federale'),
                       file_name=f'{prefisso}.pdf',mime='application/pdf',use_container_width=True,key=f'{key}_pdf')


def _af_norm(v):
    x = unicodedata.normalize('NFKD', str(v or '')).encode('ascii','ignore').decode('ascii')
    return re.sub(r'[^A-Z0-9]+', ' ', x.upper()).strip()


def _af_digits(v):
    return re.sub(r'\D', '', str(v or ''))


def _af_hash(data):
    return hashlib.sha256(data).hexdigest()


def _af_val(row, *names):
    cmap = {_af_norm(c): c for c in row.index}
    for n in names:
        c = cmap.get(_af_norm(n))
        if c is not None:
            v = row.get(c, '')
            if pd.isna(v):
                return ''
            if isinstance(v, float) and v.is_integer():
                return str(int(v))
            return str(v).strip()
    return ''


def _af_tipo_excel(df, nome_file=''):
    cols = {_af_norm(c) for c in df.columns}
    nf = _af_norm(nome_file)
    if 'ARBITR' in nf or any('ARBITR' in c for c in cols):
        return 'ARCHIVIO_ARBITRI'
    if 'SEGNAPUNT' in nf or any('SEGNAPUNT' in c for c in cols):
        return 'ARCHIVIO_SEGNAPUNTI'
    if _af_norm('Società Appartenenza') in cols or _af_norm('Società Provenienza') in cols:
        return 'ARCHIVIO_ATLETI'
    if _af_norm('Qual.') in cols or _af_norm('Data Qualifica') in cols:
        return 'ARCHIVIO_TECNICI'
    if _af_norm('Carica') in cols:
        return 'ARCHIVIO_DIRIGENTI'
    return 'ARCHIVIO_FIPAV'


def _af_ruolo_excel(tipo, row):
    qual = _af_val(row, 'Qual.', 'Qualifica', 'Carica', 'Ruolo', 'Funzione')
    qn = _af_norm(qual)
    if tipo == 'ARCHIVIO_ATLETI': return 'ATLETA'
    if tipo == 'ARCHIVIO_ARBITRI' or 'ARBITR' in qn: return 'ARBITRO'
    if tipo == 'ARCHIVIO_SEGNAPUNTI' or 'SEGNAPUNT' in qn: return 'SEGNAPUNTI'
    if tipo == 'ARCHIVIO_TECNICI': return 'TECNICO'
    if tipo == 'ARCHIVIO_DIRIGENTI': return 'DIRIGENTE'
    return qual or tipo


def _af_leggi_excel_con_intestazione(data):
    """Individua l'intestazione reale negli export federali con righe iniziali di titolo."""
    anteprima = pd.read_excel(io.BytesIO(data), header=None, dtype=object, nrows=60)
    riga_header = None
    for idx, row in anteprima.iterrows():
        celle = {_af_norm(v) for v in row.tolist() if not pd.isna(v) and str(v).strip()}
        ha_matricola = any(x in celle for x in {'MATRICOLA', 'N TESSERA', 'TESSERA'})
        ha_nome = any(x in celle for x in {'COGNOME E NOME', 'NOME ATLETA', 'NOME', 'NOMINATIVO'})
        if ha_matricola and ha_nome:
            riga_header = int(idx)
            break
    if riga_header is None:
        raise ValueError('Intestazione non riconosciuta: servono almeno le colonne Matricola e Cognome e Nome/Nome.')
    df = pd.read_excel(io.BytesIO(data), header=riga_header, dtype=object)
    df.columns = [str(c).strip() for c in df.columns]
    df = df.dropna(how='all').reset_index(drop=True)
    return df, riga_header + 1


def _af_anteprima_excel(nome_file, data, db):
    """Analizza un archivio Excel senza modificare il database federale."""
    df, riga_intestazione = _af_leggi_excel_con_intestazione(data)
    tipo = _af_tipo_excel(df, nome_file)
    validi=[]
    chiavi_record=[]
    righe_non_valide=0
    for _,row in df.iterrows():
        matr=_af_digits(_af_val(row,'Matricola','N° Tessera','Tessera'))
        nome=_af_val(row,'Cognome e Nome','Nome Atleta','Nome')
        if matr and nome:
            validi.append((matr,_af_norm(nome)))
            chiavi_record.append((
                matr,_af_norm(nome),_af_val(row,'Stag','Stagione'),
                _af_norm(_af_val(row,'Società Tesseramento','Societa Tesseramento','Società Appartenenza','Societa Appartenenza','Denominazione')),
                _af_norm(_af_val(row,'Campionato','Serie')),
                _af_ruolo_excel(tipo,row),
            ))
        else:
            righe_non_valide+=1
    persone_uniche=len(set(validi))
    duplicati_esatti=max(0,len(chiavi_record)-len(set(chiavi_record)))
    gia_acquisito=any(d.get('hash_file')==_af_hash(data) for d in db.get('documenti',[]))
    return {
        'File':nome_file,
        'Tipo riconosciuto':tipo,
        'Riga intestazione':riga_intestazione,
        'Righe valide':len(validi),
        'Persone uniche':persone_uniche,
        'Possibili duplicati':duplicati_esatti,
        'Righe incomplete':righe_non_valide,
        'Stato':'Già acquisito' if gia_acquisito else 'Pronto',
    }



def _af_split_nome(nome):
    nome = ' '.join(str(nome or '').split())
    return nome


def _af_parse_camp3_text(text):
    """Estrae solo dati sportivi. Non conserva documenti di identità o dati sanitari."""
    persone = []
    visti = set()
    testo = str(text or '')

    def aggiungi_persona(matricola, nome, ruolo, data_nascita='', numero_maglia=''):
        matr = _af_digits(matricola)
        nome_pulito = ' '.join(str(nome or '').replace('’', "'").split()).strip()
        nome_pulito = re.sub(r'^(?:PC|N)\s+', '', nome_pulito, flags=re.I).strip()
        if not matr or not nome_pulito:
            return
        chiave = (str(ruolo), matr, _af_norm(nome_pulito))
        if chiave in visti:
            return
        visti.add(chiave)
        persone.append({
            'matricola':matr,'nome':nome_pulito,
            'data_nascita':str(data_nascita or '').replace('.','/').replace('-','/'),
            'ruolo_documento':ruolo,'numero_maglia':str(numero_maglia or '').strip()
        })

    # Formato compatto: numero, nominativo, nascita e tessera sulla stessa riga.
    for line in testo.splitlines():
        ln = ' '.join(line.split())
        m = re.search(r'(?i)(?:^|\s)(\d{1,2})\s+([A-ZÀ-ÖØ-Ý\'’` -]{3,}?)\s+(\d{2}[./-]\d{2}[./-]\d{4})\s+(\d{4,9})(?:\s|$)', ln)
        if m:
            aggiungi_persona(m.group(4),m.group(2),'ATLETA',m.group(3),m.group(1))

    # Formato CAMP3 tabellare reale: il PDF espone celle e colonne su righe separate.
    for pagina in re.split(r'(?=ELENCO\s+PARTECIPANTI)', testo, flags=re.I):
        if not re.search(r'Cognome\s+e\s+Nome', pagina, flags=re.I):
            continue
        sezione = re.split(r'Cognome\s+e\s+Nome', pagina, maxsplit=1, flags=re.I)[1]
        sezione = re.split(r'Specificare\s+con\s+S', sezione, maxsplit=1, flags=re.I)[0]
        compatto = ' '.join(sezione.split())
        pattern_atleta = re.compile(
            r"([A-ZÀ-ÖØ-Ý][A-ZÀ-ÖØ-Ý'’ -]{2,}?)\s+"
            r"(?:(?:K|S|L[12]|\*)\s+)?"
            r"(\d{2}[./-]\d{2}[./-]\d{4})\s+(\d{4,9})(?:\s|$)"
        )
        for m in pattern_atleta.finditer(compatto):
            aggiungi_persona(m.group(3),m.group(1),'ATLETA',m.group(2),'')

    lines=[' '.join(x.split()) for x in testo.splitlines() if x.strip()]

    def ruolo_riga(linea):
        n=_af_norm(linea)
        if n=='DIRIGENTE' or n.startswith('DIRIGENTE ACCOMPAGNATORE'): return 'DIRIGENTE'
        if n.startswith('1 ALLENATORE'): return 'ALLENATORE_1'
        if n.startswith('2 ALLENATORE'): return 'ALLENATORE_2'
        if n.startswith('ALL PRATICANTE'): return 'ALLENATORE_PRATICANTE'
        if n.startswith('MEDICO SOCIALE'): return 'MEDICO'
        if n.startswith('FISIOTERAPISTA'): return 'FISIOTERAPISTA'
        if n.startswith('PREPARATORE FISICO'): return 'PREPARATORE_FISICO'
        if n.startswith('SEGNAPUNTI'): return 'SEGNAPUNTI'
        if n.startswith('1 ARBITRO'): return 'ARBITRO_1'
        if n.startswith('2 ARBITRO'): return 'ARBITRO_2'
        if n.startswith('ARBITRO ASSOCIATO') or n=='ARBITRO': return 'ARBITRO'
        if n.startswith('ADDETTO ALL ARBITRO'): return 'ADDETTO_ARBITRO'
        return ''

    # Cerca un nominativo seguito dalla tessera, fermandosi al ruolo successivo.
    for i,linea in enumerate(lines):
        ruolo=ruolo_riga(linea)
        if not ruolo:
            continue
        for j in range(i+1,min(i+15,len(lines))):
            if ruolo_riga(lines[j]):
                break
            candidato=lines[j].strip()
            if not re.fullmatch(r"[A-ZÀ-ÖØ-Ý][A-ZÀ-ÖØ-Ý'’ -]{3,}",candidato):
                continue
            if len(_af_norm(candidato).split())<2:
                continue
            for k in range(j+1,min(j+4,len(lines))):
                if ruolo_riga(lines[k]):
                    break
                if re.fullmatch(r'\d{4,9}',lines[k].strip()):
                    aggiungi_persona(lines[k],candidato,ruolo)
                    break
            else:
                continue
            break
    return persone


def _af_extract_camp3_meta(text):
    """Estrae dal CAMP3 soltanto i metadati sportivi e societari utili."""
    compatto=' '.join(str(text or '').split())
    def trova(pattern):
        m=re.search(pattern,compatto,flags=re.I)
        return ' '.join(m.group(1).split()).strip() if m else ''
    codice_spaziato=trova(r'CODICE DI AFFILIAZIONE\s+.+?\s+((?:\d\s+){5,}\d)')
    return {
        'stagione':trova(r'CAMP3\s+(\d{4}\s*/\s*\d{4})').replace(' ',''),
        'numero_gara':trova(r'DATI DELLA GARA\s*N[°º]?\s*(\d+)'),
        'data':trova(r'Data:\s*(\d{2}[./-]\d{2}[./-]\d{4})').replace('.','/').replace('-','/'),
        'ora':trova(r'Ora:\s*([0-2]?\d[:.]\d{2})').replace('.',':'),
        'localita':trova(r'Località:\s*(.*?)\s+Serie/Cat\./Torne/Amich\.:'),
        'categoria':trova(r'Serie/Cat\./Torne/Amich\.:\s*(.*?)\s+Squadra Ospitante:'),
        'squadra_ospitante':trova(r'Squadra Ospitante:\s*(.*?)\s+Squadra Ospite:'),
        'squadra_ospite':trova(r'Squadra Ospite:\s*(.*?)\s+DENOMINAZIONE DELLA SOCIETA'),
        'societa':trova(r'CODICE DI AFFILIAZIONE\s+(.+?)\s+(?:(?:\d\s+){5,}\d)'),
        'codice_societa':_af_digits(codice_spaziato),
    }


def _af_acquisisci_excel(db, nome_file, data, ente='FIPAV'):
    h=_af_hash(data)
    esistente=next((d for d in db['documenti'] if d.get('hash_file')==h),None)
    if esistente:
        if not esistente.get('contenuto_b64') and _af_incorpora_documento(esistente,data):
            esistente['_allegato_appena_recuperato']=True
            return esistente, 0, ''
        return None, 0, 'Documento già acquisito e originale già conservato.'
    try:
        df, riga_intestazione = _af_leggi_excel_con_intestazione(data)
    except Exception as exc:
        return None, 0, f'Excel non leggibile o intestazione non riconosciuta: {exc}'
    tipo=_af_tipo_excel(df, nome_file)
    doc_id=uuid.uuid4().hex
    stagioni=sorted({x for x in (_af_val(r,'Stag','Stagione') for _,r in df.iterrows()) if x})
    doc={'id':doc_id,'ente':ente,'tipo':tipo,'nome_file':nome_file,'hash_file':h,'stagione':', '.join(stagioni),'societa':'','codice_societa':'','categoria':'','numero_gara':'','riga_intestazione':riga_intestazione,'acquisito_il':ora_italiana().isoformat(timespec='seconds')}
    _af_incorpora_documento(doc,data)
    db['documenti'].append(doc)
    count=0
    duplicati_ignorati=0
    record_visti=set()
    for _,row in df.iterrows():
        matr=_af_digits(_af_val(row,'Matricola','N° Tessera','Tessera'))
        nome=_af_val(row,'Cognome e Nome','Nome Atleta','Nome')
        if not matr or not nome: continue
        stagione=_af_val(row,'Stag','Stagione')
        societa=_af_val(row,'Società Tesseramento','Societa Tesseramento','Società Appartenenza','Societa Appartenenza','Denominazione')
        camp=_af_val(row,'Campionato','Serie')
        ruolo=_af_val(row,'Qual.','Qualifica','Carica','Ruolo','Funzione')
        ruolo_documento=_af_ruolo_excel(tipo,row)
        record_key=(ente,matr,_af_norm(nome),stagione,_af_norm(societa),_af_norm(camp),ruolo_documento,_af_norm(ruolo))
        if record_key in record_visti:
            duplicati_ignorati+=1
            continue
        record_visti.add(record_key)
        pn={'ente':ente,'matricola':matr,'nome':nome,'data_nascita':_af_val(row,'Data Nascita')}
        if not any(p.get('ente')==ente and _af_digits(p.get('matricola'))==matr for p in db['persone']): db['persone'].append(pn)
        part={'id':uuid.uuid4().hex,'id_documento':doc_id,'ente':ente,'matricola':matr,'nome':nome,'stagione':stagione,'societa':societa,'categoria':'','campionato':camp,'ruolo_documento':ruolo_documento,'qualifica_carica':ruolo,'numero_maglia':'','numero_gara':'','fonte':tipo}
        db['partecipazioni'].append(part); count+=1
    if count == 0:
        db['documenti'] = [d for d in db['documenti'] if d.get('id') != doc_id]
        return None, 0, 'Nessuna persona con nome e matricola riconosciuta: documento non acquisito.'
    doc['duplicati_ignorati']=duplicati_ignorati
    return doc, count, ''


def _af_acquisisci_camp3(db, nome_file, data, stagione, societa, codice_societa='', categoria='', numero_gara=''):
    h=_af_hash(data)
    esistente=next((d for d in db['documenti'] if d.get('hash_file')==h),None)
    if esistente:
        if not esistente.get('contenuto_b64') and _af_incorpora_documento(esistente,data):
            esistente['_allegato_appena_recuperato']=True
            return esistente, 0, ''
        return None, 0, 'Documento già acquisito e originale già conservato.'
    text=''
    if nome_file.lower().endswith('.pdf'):
        try:
            from pypdf import PdfReader
            text='\n'.join((p.extract_text() or '') for p in PdfReader(io.BytesIO(data)).pages)
        except Exception as exc:
            return None,0,f'PDF non leggibile: {exc}'
    else:
        return None,0,'Per ora il database centrale acquisisce CAMP3 PDF testuali. Le immagini resteranno disponibili per la fase OCR successiva.'
    parsed=_af_parse_camp3_text(text)
    if not parsed:
        return None,0,'Nessuna persona o incarico riconosciuto nel CAMP3: documento non acquisito.'
    meta=_af_extract_camp3_meta(text)
    stagione_eff=meta.get('stagione') or str(stagione).strip()
    societa_eff=meta.get('societa') or str(societa).strip()
    codice_eff=meta.get('codice_societa') or str(codice_societa).strip()
    categoria_eff=meta.get('categoria') or str(categoria).strip()
    numero_gara_eff=meta.get('numero_gara') or str(numero_gara).strip()
    if not stagione_eff or not societa_eff:
        return None,0,'Metadati CAMP3 incompleti: indicare almeno stagione e società.'
    doc_id=uuid.uuid4().hex
    doc={'id':doc_id,'ente':'FIPAV','tipo':'CAMP3','nome_file':nome_file,'hash_file':h,'stagione':stagione_eff,'societa':societa_eff,'codice_societa':codice_eff,'categoria':categoria_eff,'numero_gara':numero_gara_eff,'data_gara':meta.get('data',''),'ora_gara':meta.get('ora',''),'localita':meta.get('localita',''),'squadra_ospitante':meta.get('squadra_ospitante',''),'squadra_ospite':meta.get('squadra_ospite',''),'metadati_automatici':bool(meta.get('stagione') and meta.get('societa')),'acquisito_il':ora_italiana().isoformat(timespec='seconds')}
    _af_incorpora_documento(doc,data)
    db['documenti'].append(doc)
    for x in parsed:
        matr=_af_digits(x.get('matricola'))
        if not any(p.get('ente')=='FIPAV' and _af_digits(p.get('matricola'))==matr for p in db['persone']):
            db['persone'].append({'ente':'FIPAV','matricola':matr,'nome':x.get('nome',''),'data_nascita':x.get('data_nascita','')})
        db['partecipazioni'].append({'id':uuid.uuid4().hex,'id_documento':doc_id,'ente':'FIPAV','matricola':matr,'nome':x.get('nome',''),'stagione':stagione_eff,'societa':societa_eff,'categoria':categoria_eff,'campionato':categoria_eff,'ruolo_documento':x.get('ruolo_documento',''),'numero_maglia':x.get('numero_maglia',''),'numero_gara':numero_gara_eff,'fonte':'CAMP3'})
    return doc,len(parsed),''


def _af_aggiorna_metadati_camp3(db, nome_file, data):
    """Completa un CAMP3 già acquisito senza ricreare documento, persone o incarichi."""
    h=_af_hash(data)
    doc=next((d for d in db.get('documenti',[]) if d.get('hash_file')==h and d.get('tipo')=='CAMP3'),None)
    if not doc:
        return None,0,'CAMP3 già acquisito non trovato nell’archivio.'
    try:
        from pypdf import PdfReader
        text='\n'.join((p.extract_text() or '') for p in PdfReader(io.BytesIO(data)).pages)
    except Exception as exc:
        return None,0,f'PDF non leggibile: {exc}'
    meta=_af_extract_camp3_meta(text)
    if not meta.get('stagione') or not meta.get('societa'):
        return None,0,'Nel PDF non sono stati riconosciuti stagione e società: metadati non aggiornati.'

    mappa_doc={
        'stagione':'stagione','societa':'societa','codice_societa':'codice_societa',
        'categoria':'categoria','numero_gara':'numero_gara','data':'data_gara',
        'ora':'ora_gara','localita':'localita','squadra_ospitante':'squadra_ospitante',
        'squadra_ospite':'squadra_ospite',
    }
    for chiave_meta,chiave_doc in mappa_doc.items():
        valore=str(meta.get(chiave_meta,'') or '').strip()
        if valore:
            doc[chiave_doc]=valore
    doc['metadati_automatici']=True
    doc['metadati_aggiornati_il']=ora_italiana().isoformat(timespec='seconds')

    aggiornate=0
    for part in db.get('partecipazioni',[]):
        if part.get('id_documento')!=doc.get('id'):
            continue
        part['stagione']=doc.get('stagione','')
        part['societa']=doc.get('societa','')
        part['categoria']=doc.get('categoria','')
        part['campionato']=doc.get('categoria','')
        part['numero_gara']=doc.get('numero_gara','')
        aggiornate+=1
    return doc,aggiornate,''


def _af_sync_atleta_da_db(atleta, db):
    matr_fipav=_af_digits(atleta.get('matricola_fipav',''))
    if not matr_fipav:
        return 0, 'Matricola FIPAV assente nella scheda atleta.'
    parts=[p for p in db.get('partecipazioni',[]) if p.get('ente')=='FIPAV' and _af_digits(p.get('matricola'))==matr_fipav and p.get('ruolo_documento')=='ATLETA']
    docs={d.get('id'):d for d in db.get('documenti',[])}
    dest=atleta.setdefault('storico_carriera',[])
    existing={str(r.get('archivio_federale_partecipazione_id','')) for r in dest}
    n=0
    for p in parts:
        if p.get('id') in existing: continue
        d=docs.get(p.get('id_documento'),{})
        staff=[x for x in db.get('partecipazioni',[]) if x.get('id_documento')==p.get('id_documento') and x.get('ruolo_documento')!='ATLETA']
        def staff_name(role):
            return next((x.get('nome','') for x in staff if x.get('ruolo_documento')==role),'')
        fonte='CAMP3 FIPAV' if d.get('tipo')=='CAMP3' else 'Modulo F / Tesseramento FIPAV'
        note='Presenza documentata nel CAMP3; non equivale automaticamente a ingresso in campo.' if d.get('tipo')=='CAMP3' else 'Record proveniente dall’Archivio Atleti FIPAV.'
        rec={'id':uuid.uuid4().hex,'stagione':p.get('stagione') or d.get('stagione',''),'ente':'FIPAV','societa':p.get('societa') or d.get('societa',''),'squadra':p.get('categoria') or d.get('categoria',''),'categoria':p.get('categoria') or d.get('categoria',''),'campionato':p.get('campionato',''),'ruolo':'','numero_maglia':p.get('numero_maglia',''),'numero_tessera':matr_fipav,'allenatore1':staff_name('ALLENATORE_1'),'allenatore2':staff_name('ALLENATORE_2'),'dirigente':staff_name('DIRIGENTE'),'fonte':fonte,'attendibilita':'🟢 Documento ufficiale','riferimento':f"{d.get('tipo','FIPAV')} — {d.get('nome_file','')}",'note':note,'archivio_federale_documento_id':d.get('id',''),'archivio_federale_partecipazione_id':p.get('id',''),'inserito_il':ora_italiana().isoformat(timespec='seconds'),'operatore':str(st.session_state.get('username_corrente','admin'))}
        dest.append(rec); n+=1
    return n,''


def _af_collegamenti_gestionale(db):
    mats = {_af_digits(a.get('matricola_fipav','')) for a in st.session_state.get('elenco_atlete',[]) if _af_digits(a.get('matricola_fipav',''))}
    fed = {_af_digits(p.get('matricola','')) for p in db.get('persone',[]) if p.get('ente')=='FIPAV'}
    return mats & fed


def _af_elimina_documento(db, documento_id):
    """Elimina una fonte e ripulisce solo le persone rimaste senza partecipazioni."""
    documento_id = str(documento_id or '').strip()
    if not documento_id:
        return 0, 0
    documenti_prima = len(db.get('documenti', []))
    partecipazioni_prima = len(db.get('partecipazioni', []))
    db['documenti'] = [d for d in db.get('documenti', []) if str(d.get('id', '')) != documento_id]
    db['partecipazioni'] = [p for p in db.get('partecipazioni', []) if str(p.get('id_documento', '')) != documento_id]
    chiavi_usate = {
        (str(p.get('ente', '')), _af_digits(p.get('matricola', '')))
        for p in db.get('partecipazioni', [])
        if _af_digits(p.get('matricola', ''))
    }
    db['persone'] = [
        p for p in db.get('persone', [])
        if (str(p.get('ente', '')), _af_digits(p.get('matricola', ''))) in chiavi_usate
    ]
    return documenti_prima - len(db['documenti']), partecipazioni_prima - len(db['partecipazioni'])


def _af_rimuovi_duplicati_identici_stesso_documento(db):
    """Conserva la prima riga e rimuove solo copie integralmente equivalenti nella stessa fonte."""
    viste=set()
    conservate=[]
    eliminate=0
    for p in db.get('partecipazioni',[]):
        chiave=(
            str(p.get('id_documento','')),
            str(p.get('ente','')).upper(),_af_digits(p.get('matricola','')),_af_norm(p.get('nome','')),
            str(p.get('stagione','')).strip(),_af_norm(p.get('societa','')),
            _af_norm(p.get('campionato') or p.get('categoria','')),
            str(p.get('ruolo_documento','')).upper(),_af_digits(p.get('numero_gara','')),
            str(p.get('numero_maglia','')).strip(),
        )
        if chiave in viste:
            eliminate+=1
            continue
        viste.add(chiave)
        conservate.append(p)
    db['partecipazioni']=conservate
    return eliminate


def render_archivio_federale():
    st.markdown('## 🗂️ ARCHIVIO FEDERALE FIPAV / UISP')
    st.caption('Database documentale centrale separato dalle singole schede atleta. Atlete, tecnici, dirigenti, segnapunti e arbitri restano associati alla fonte, alla stagione e alla società/documento di provenienza.')
    db=carica_archivio_federale()
    docs=db.get('documenti',[]); persone=db.get('persone',[]); parts=db.get('partecipazioni',[])
    collegati=_af_collegamenti_gestionale(db)
    m1,m2,m3,m4=st.columns(4)
