    t_import,t_docs,t_stagioni,t_pers,t_staff,t_qualita,t_assoc=st.tabs(['📥 Importa documenti','📁 Documenti acquisiti','📈 Riepilogo stagioni','👥 Persone federali / Staff','🏐 Staff / Squadre','🩺 Controllo qualità','🔗 Collegamenti / Storico'])
