def atlete_per_gruppo_costo(gruppo, stagione):
    g = normalizza_nome_gruppo(gruppo)
    return [
        a for a in st.session_state.get("elenco_atlete", [])
        if a.get("stagione") == stagione
        and a.get("cognome") != "--- Inizializzazione"
        and (normalizza_nome_gruppo(a.get("gruppo", "")).lower() == g.lower()
             or normalizza_nome_gruppo(a.get("gruppo2", "")).lower() == g.lower())
    ]
def quantita_riga_costo(item, gruppo, stagione):
    unita = str(item.get("unita", "pz") or "pz").strip().lower()
    if unita == "totale atlete gruppo":
        return float(len(atlete_per_gruppo_costo(gruppo, stagione)))
    return max(0.0, safe_float(item.get("quantita", item.get("val1", 0))))
def totale_riga_costo(item, gruppo, stagione):
    quantita = quantita_riga_costo(item, gruppo, stagione)
    unitario = max(0.0, safe_float(item.get("costo_unitario", item.get("val2", 0))))
    return round(quantita * unitario, 2)
voci_costi_configurate = carica_json(FILE_CONFIG_VOCI_COSTI, voci_costi_default)

