def permessi_utente_corrente():
    username=str(st.session_state.get('username_corrente','')).strip().lower()
    info=st.session_state.get('utenti',{}).get(username,{})
    ruolo=str(info.get('ruolo',st.session_state.get('ruolo_corrente',''))).strip().lower()
    if username=='admin' or ruolo=='amministratore':
        return set(PERMESSI_AZIONE_LABELS)
    personalizzati=info.get('permessi_azione',None)
    if isinstance(personalizzati,list):
        return {str(x) for x in personalizzati if str(x) in PERMESSI_AZIONE_LABELS}
    return set(PERMESSI_PREDEFINITI_RUOLO.get(ruolo,set()))
def ha_permesso(azione):
    return str(azione) in permessi_utente_corrente()
def squadre_assegnate_utente_corrente():
    """Restituisce le squadre assegnate; None significa accesso tecnico completo."""
    username = str(st.session_state.get('username_corrente','')).strip().lower()
    info = st.session_state.get('utenti', {}).get(username, {})
    ruolo = str(info.get('ruolo', st.session_state.get('ruolo_corrente',''))).strip().lower()
    if username == 'admin' or ruolo in {'amministratore','responsabile'}:
        return None
    if ruolo != 'allenatore':
        return None
    assegnate = info.get('squadre_assegnate', []) if isinstance(info, dict) else []
    if isinstance(assegnate, str):
        assegnate = [assegnate]
    return {str(x).strip().casefold() for x in assegnate if str(x).strip()}
def squadra_visibile_utente(nome_squadra):
    assegnate = squadre_assegnate_utente_corrente()
    return assegnate is None or str(nome_squadra or '').strip().casefold() in assegnate
def e_superadmin_credenziali():
    """Solo l'account proprietario admin può creare account o assegnare credenziali."""
    return str(st.session_state.get('username_corrente','')).strip().lower()=='admin'
def avviso_permesso_negato(azione):
    st.warning(f"Operazione non autorizzata per questo account: {PERMESSI_AZIONE_LABELS.get(str(azione),str(azione))}.")
def verifica_accesso(area_richiesta):
    user_corrente = str(st.session_state.get("username_corrente", "")).strip()
    utenti_accesso = st.session_state.get("utenti", {})
    info_u = utenti_accesso.get(user_corrente, utenti_accesso.get(user_corrente.lower(), {}))
    ruolo_accesso = str(info_u.get("ruolo", st.session_state.get("ruolo_corrente", ""))).strip()
    aree_utente = info_u.get("area", info_u.get("aree_autorizzate", []))
    if isinstance(aree_utente, str):
        aree_utente = [aree_utente]
    if not aree_utente and ruolo_accesso.casefold() == "allenatore":
        # Compatibilità con gli account allenatore creati prima dei permessi per area.
        aree_utente = ["Area Tecnica", "Promozionale", "Giovanile", "Gestionale"]
    aree_normalizzate = {str(x).strip().casefold() for x in (aree_utente or [])}
    is_admin = ruolo_accesso.casefold() == "amministratore" or user_corrente.lower() == "admin"
    aree_base_allenatore = {"area tecnica", "promozionale", "giovanile"}
    if ruolo_accesso.casefold() == "allenatore":
        if str(area_richiesta).strip().casefold() not in aree_base_allenatore:
            st.error(f"⛔ Accesso negato: il profilo Allenatore può utilizzare soltanto Area Tecnica, Promozionale e Giovanile.")
            st.stop()
        return
    if (
        not is_admin
        and "tutte" not in aree_normalizzate
        and str(area_richiesta).strip().casefold() not in aree_normalizzate
    ):
        st.error(f"⛔ Accesso negato: il tuo account non è autorizzato ad accedere a questa sezione ({area_richiesta}).")
        st.stop()
def normalizza_stato_iscrizione(valore):
    v = str(valore or "").strip()
    allowed = {"Confermato", "In attesa", "Sospeso", "Ritirato"}
    if v in allowed: return v
    norm = normalizza_intestazione_colonna(v)
    if norm in {"confermato", "confirmed"}: return "Confermato"
    if norm in {"in attesa", "attesa", "pending"}: return "In attesa"
    if norm in {"sospeso", "suspended"}: return "Sospeso"
    if norm in {"ritirato", "ritirata", "withdrawn"}: return "Ritirato"
    if re.fullmatch(r"[A-Za-z0-9]{16}", v): return "Confermato"
    return "Confermato" if not v else v
