def _estrai_campo_header(colonne, aliases, campo):
    exact = [(len(norm), -idx, original) for original, norm, idx in colonne if norm in aliases]
    if exact:
        exact.sort(reverse=True); return exact[0][2]
    best = None
    for original, norm, idx in colonne:
        nt = set(norm.split())
        for alias in aliases:
            at = set(alias.split()); inter = len(nt & at)
            if not inter: continue
            bonus = 12 if alias in norm else 0
            score = inter * 10 + bonus - abs(len(nt) - len(at))
            if campo == "cognome" and "cognome" not in nt: continue
            if campo == "nome" and "nome" not in nt: continue
            if campo == "sync_key" and not ({"informazioni", "cronologiche"} <= nt or "timestamp" in nt): continue
            cand = (score, len(norm), -idx, original)
            if best is None or cand > best: best = cand
    return best[3] if best else None
def sincronizza_dal_modulo(stagione_attiva):
    try:
        response = requests.get(URL_MASTER_CSV, headers={"User-Agent": "Mozilla/5.0"}, timeout=30)
        response.raise_for_status()
        df = pd.read_csv(io.StringIO(response.text), dtype=str, keep_default_na=False, encoding="utf-8-sig")
        df.columns = [str(c).replace("\ufeff", "").strip() for c in df.columns]
        if df.empty:
            return {"ok": True, "nuove": 0, "aggiornate": 0, "invariate": 0, "saltate": 0, "cf_duplicati": 0, "errori": [], "righe": 0}
        colonne = [(str(c), normalizza_intestazione_colonna(c), i) for i, c in enumerate(df.columns)]
        aliases_norm = {k: [normalizza_intestazione_colonna(x) for x in vals] for k, vals in SYNC_ALIASES.items()}
        col_map = {campo: _estrai_campo_header(colonne, aliases_norm.get(campo, []), campo) for campo in SYNC_ALIASES}
        if col_map.get("stato"):
            norm_stato_header = normalizza_intestazione_colonna(col_map["stato"])
            if norm_stato_header not in {"stato", "stato iscrizione", "stato atleta", "status"}:
                col_map["stato"] = None
        def clean(v):
            v = str(v or "").strip(); return "" if v.lower() in {"nan", "none", "null"} else v
        def get_row_val(row, campo):
            col = col_map.get(campo); return clean(row.get(col, "")) if col else ""
        def norm_persona(v): return re.sub(r"[^a-z0-9]", "", normalizza_intestazione_colonna(v))
        def norm_cf(v): return re.sub(r"[^A-Z0-9]", "", clean(v).upper())
        def norm_date(v):
            v = clean(v)
            if not v: return ""
            for fmt in ("%d/%m/%Y", "%d-%m-%Y", "%Y-%m-%d"):
                try: return datetime.strptime(v, fmt).strftime("%d/%m/%Y")
                except ValueError: pass
            try:
                parsed = pd.to_datetime(v, dayfirst=True, errors="coerce")
                if not pd.isna(parsed): return parsed.strftime("%d/%m/%Y")
            except Exception: pass
            return v
        campi_anagrafici = {
            "cognome", "nome", "sesso", "cf", "data_nas", "luogo_nas", "prov_nas",
            "indirizzo_res", "citta_res", "prov_res", "scuola_frequentata", "classe_scolastica",
            "categoria", "gruppo", "gruppo2", "scad_visita", "gen1", "tel1", "mail1", "gen2", "tel2", "mail2", "stato",
        }
        count_nuove = count_aggiornate = count_invariate = count_saltate = count_cf_duplicati = 0
        count_eliminate = 0
        errori = []; atlete = st.session_state["elenco_atlete"]
        nuove_atlete_sync = []
        tombstones = st.session_state.get("atlete_eliminate_sync", []) or []
        for a in atlete:
            if a.get("stagione") == stagione_attiva:
                a["stato"] = normalizza_stato_iscrizione(a.get("stato", ""))
                a["categoria"] = normalizza_categoria(a.get("categoria", ""), a.get("gruppo", ""))
        by_sync = {str(a.get("sync_key", "")).strip(): a for a in atlete if a.get("stagione") == stagione_attiva and a.get("sync_key")}
        by_name = {}; by_name_cf = {}
        for a in atlete:
            if a.get("stagione") != stagione_attiva: continue
            key_name = (norm_persona(a.get("cognome", "")), norm_persona(a.get("nome", "")))
            if key_name[0] and key_name[1]: by_name.setdefault(key_name, []).append(a)
            c = norm_cf(a.get("cf", ""))
            if c: by_name_cf.setdefault((key_name[0], key_name[1], c), []).append(a)
        for row_num, (_, row) in enumerate(df.iterrows(), start=2):
            try:
                dati = {campo: get_row_val(row, campo) for campo in SYNC_ALIASES}
                def unisci_nome(cognome_p, nome_p, fallback=""):
                    cp, np = clean(cognome_p), clean(nome_p); merged = f"{cp} {np}".strip(); return merged or clean(fallback)
                if dati.get("cognome_gen1") or dati.get("nome_gen1"): dati["gen1"] = unisci_nome(dati.get("cognome_gen1"), dati.get("nome_gen1"))
                if dati.get("cognome_gen2") or dati.get("nome_gen2"): dati["gen2"] = unisci_nome(dati.get("cognome_gen2"), dati.get("nome_gen2"))
                sync_key = dati.get("sync_key", ""); cognome = dati.get("cognome", ""); nome = dati.get("nome", "")
                if not cognome or not nome:
                    nominativo = dati.get("nominativo", "")
                    if nominativo:
                        parti = nominativo.split(None, 1); cognome = cognome or (parti[0] if parti else ""); nome = nome or (parti[1] if len(parti) > 1 else "")
                if not cognome and not nome:
                    count_saltate += 1
                    if len(errori) < 20: errori.append(f"Riga {row_num}: cognome e nome assenti")
                    continue
                if not cognome:
                    count_saltate += 1
                    if len(errori) < 20: errori.append(f"Riga {row_num}: cognome assente")
                    continue
                if not nome: nome = "Senza Nome"
                dati["cognome"] = cognome; dati["nome"] = nome
                # Atleta eliminata manualmente dal gestionale: la riga del modulo
                # resta in Google Sheets ma non deve poterla reinserire automaticamente.
                if _atleta_bloccata_sync({
                    "sync_key": sync_key,
                    "cognome": cognome,
                    "nome": nome,
                    "cf": dati.get("cf", ""),
                }, stagione_attiva, tombstones):
                    count_eliminate += 1
                    continue
                if dati.get("sesso"):
                    sx = normalizza_sesso(dati["sesso"])
                    if sx: dati["sesso"] = sx
                    else: dati.pop("sesso", None)
                if dati.get("data_nas"): dati["data_nas"] = norm_date(dati["data_nas"])
                if dati.get("scad_visita"): dati["scad_visita"] = norm_date(dati["scad_visita"])
                gruppo_letto = normalizza_nome_gruppo(dati.get("gruppo", "")) if dati.get("gruppo") else "Minivolley"
                dati["gruppo"] = gruppo_letto or "Minivolley"
                if "gruppo2" in dati:
                    g2 = clean(dati.get("gruppo2"))
                    dati["gruppo2"] = "" if normalizza_intestazione_colonna(g2) in {"nessuno", "none", "nan"} else (normalizza_nome_gruppo(g2) if g2 else "")
                # CORREZIONE CHIAVE: categoria coerente con il gruppo.
                dati["categoria"] = normalizza_categoria(dati.get("categoria", ""), dati["gruppo"])

                # Dati scolastici previsti SOLO per MINIVOLLEY e SCUOLA.
                gruppo_scuola = normalizza_intestazione_colonna(dati.get("gruppo", ""))
                if gruppo_scuola not in {"minivolley", "scuola"}:
                    dati["scuola_frequentata"] = ""
                    dati["classe_scolastica"] = ""

                if dati["gruppo"] not in st.session_state["gruppi_societa"]:
                    st.session_state["gruppi_societa"].append(dati["gruppo"])
                atleta = by_sync.get(sync_key) if sync_key else None
                if atleta is None:
                    nk = (norm_persona(cognome), norm_persona(nome)); cf = norm_cf(dati.get("cf", ""))
                    candidati_cf = by_name_cf.get((nk[0], nk[1], cf), []) if cf else []
                    if candidati_cf: atleta = candidati_cf[0]
                    else:
                        candidati = by_name.get(nk, [])
                        if len(candidati) == 1: atleta = candidati[0]
                        elif len(candidati) > 1 and cf:
                            stessa = [a for a in candidati if norm_cf(a.get("cf", "")) == cf and cf]
                            atleta = stessa[0] if len(stessa) == 1 else None
                if atleta is not None:
                    modificata = False
                    for campo in campi_anagrafici:
                        val = clean(dati.get(campo, ""))
                        if val and clean(atleta.get(campo, "")) != val:
                            atleta[campo] = val; modificata = True
                    if sync_key and atleta.get("sync_key") != sync_key:
                        atleta["sync_key"] = sync_key; modificata = True
                    cert_url = clean(dati.get("certificato_url", ""))
                    if cert_url and atleta.get("certificato_url", "") != cert_url:
                        atleta["certificato_url"] = cert_url; modificata = True
                    if cert_url:
                        local_cert, cert_err = scarica_certificato_da_google(cert_url, atleta)
                        if local_cert and atleta.get("allegato_visita") != local_cert:
                            atleta["allegato_visita"] = local_cert; modificata = True
                        if cert_err: atleta["certificato_sync_error"] = cert_err
                    atleta["categoria"] = normalizza_categoria(atleta.get("categoria"), atleta.get("gruppo", ""))
                    ricalcola_finanze(atleta)
                    if modificata: count_aggiornate += 1
                    else: count_invariate += 1
                else:
                    cf = norm_cf(dati.get("cf", ""))
                    if cf:
                        collisioni = [a for a in atlete if a.get("stagione") == stagione_attiva and norm_cf(a.get("cf", "")) == cf and (norm_persona(a.get("cognome", "")) != norm_persona(cognome) or norm_persona(a.get("nome", "")) != norm_persona(nome))]
                        if collisioni: count_cf_duplicati += 1
                    dati_nuova = {k: v for k, v in dati.items() if v}
                    for k in ("cognome_gen1", "nome_gen1", "cognome_gen2", "nome_gen2"): dati_nuova.pop(k, None)
                    dati_nuova["sync_key"] = sync_key; dati_nuova["stato"] = dati_nuova.get("stato") or "Confermato"
                    dati_nuova["categoria"] = normalizza_categoria(dati_nuova.get("categoria", ""), dati_nuova.get("gruppo", ""))
                    nuova = crea_scheda_standard(dati_nuova, stagione_attiva=stagione_attiva)
                    cert_url_nuovo = clean(dati.get("certificato_url", ""))
                    if cert_url_nuovo:
                        nuova["certificato_url"] = cert_url_nuovo
                        local_cert, cert_err = scarica_certificato_da_google(cert_url_nuovo, nuova)
                        if local_cert: nuova["allegato_visita"] = local_cert
                        if cert_err: nuova["certificato_sync_error"] = cert_err
                    atlete.append(nuova)
                    nuove_atlete_sync.append(nuova)
                    if sync_key: by_sync[sync_key] = nuova
                    nk = (norm_persona(cognome), norm_persona(nome)); by_name.setdefault(nk, []).append(nuova)
                    cf_n = norm_cf(dati.get("cf", ""))
                    if cf_n: by_name_cf.setdefault((nk[0], nk[1], cf_n), []).append(nuova)
                    count_nuove += 1
            except Exception as row_error:
                count_saltate += 1
                if len(errori) < 20: errori.append(f"Riga {row_num}: {row_error}")
        st.session_state["elenco_atlete"] = atlete
        salva_atlete(atlete)
        privacy_sync = {"inviate": 0, "saltate": 0, "errori": []}
        try:
            privacy_sync = _privacy_invia_automaticamente_nuove(nuove_atlete_sync, stagione_attiva, atlete)
        except Exception as privacy_error:
            privacy_sync = {"inviate": 0, "saltate": len(nuove_atlete_sync), "errori": [str(privacy_error)]}
        st.session_state["elenco_atlete"] = carica_atlete()
        try: salva_json_sicuro(FILE_GRUPPI, st.session_state["gruppi_societa"])
        except Exception: pass
        return {
            "ok": True, "nuove": count_nuove, "aggiornate": count_aggiornate, "invariate": count_invariate,
            "saltate": count_saltate, "cf_duplicati": count_cf_duplicati, "ignorate_eliminate": count_eliminate, "errori": errori, "righe": len(df),
            "colonne_mappate": {k: v for k, v in col_map.items() if v}, "privacy": privacy_sync,
        }
    except requests.RequestException as e:
        return {"ok": False, "error": f"Errore connessione Google: {e}", "nuove": 0, "aggiornate": 0, "invariate": 0, "saltate": 0, "cf_duplicati": 0, "errori": []}
    except Exception as e:
        return {"ok": False, "error": f"Errore durante la sincronizzazione: {e}", "nuove": 0, "aggiornate": 0, "invariate": 0, "saltate": 0, "cf_duplicati": 0, "errori": []}
# ============================================================
# CERTIFICATI / NOTIFICHE
# ============================================================
def _segreto(nome, default=""):
    try:
        val = st.secrets.get(nome, None)
        if val is not None and str(val).strip() != "": return str(val).strip()
    except Exception: pass
    if nome.startswith("SMTP_"):
        key_map = {"SMTP_HOST":"host", "SMTP_PORT":"port", "SMTP_USER":"user", "SMTP_PASSWORD":"password", "SMTP_FROM":"from", "SMTP_USE_TLS":"use_tls"}
        nested_key = key_map.get(nome, nome.lower())
        try:
            smtp_section = st.secrets.get("smtp", None)
            if smtp_section is not None:
                for candidate in (nested_key, nome):
                    try: val2 = smtp_section.get(candidate, None)
                    except Exception: val2 = None
                    if val2 is not None and str(val2).strip() != "": return str(val2).strip()
        except Exception: pass
    return os.getenv(nome, default)
def _append_notifica_log(record):
    storico = st.session_state.setdefault("storico_notifiche", [])
    storico.append(record); storico[:] = storico[-2000:]
    try: salva_json_sicuro(FILE_LOG_NOTIFICHE, storico)
    except Exception: pass
def _safe_email(email):
    e = str(email or "").strip(); return e if e and "@" in e else ""
def _safe_phone(phone):
    digits = re.sub(r"\D", "", str(phone or "")); return digits if len(digits) >= 8 else ""
def _norm_notification_recipient(channel, recipient):
    if channel == "email": return _safe_email(recipient).lower()
    if channel == "whatsapp": return _safe_phone(recipient)
    return str(recipient or "").strip().lower()
def _notification_signature(record_or_key, channel=None, recipient=None, athlete_name=None):
    if isinstance(record_or_key, dict):
        r = record_or_key; athlete = str(r.get("atleta", athlete_name or "") or "").strip().lower()
        tipo = str(r.get("tipo", "") or "").strip().lower(); scad = str(r.get("scadenza", "") or "").strip()
        ch = str(r.get("channel", channel or "") or "").strip().lower(); rcpt = _norm_notification_recipient(ch, r.get("recipient", ""))
        return athlete, tipo, scad, ch, rcpt
    raw = str(record_or_key or ""); parts = raw.split("|")
    if len(parts) >= 5:
        athlete_key = parts[0]; tipo = parts[1].strip().lower(); scad = parts[2].strip()
        ch = (channel or parts[-2]).strip().lower(); rcpt = _norm_notification_recipient(ch, recipient or parts[-1])
        return athlete_name.strip().lower() if athlete_name else athlete_key.lower(), tipo, scad, ch, rcpt
    return (athlete_name.strip().lower() if athlete_name else raw.lower(), "", "", str(channel or "").lower(), _norm_notification_recipient(channel or "", recipient or ""))
def _record_matches_notification(r, key, channel=None, recipient=None, athlete_name=None):
    if channel and str(r.get("channel", "")).strip().lower() != str(channel).strip().lower(): return False
    if recipient is not None:
        rch = str(r.get("channel", channel or "")).strip().lower()
        if _norm_notification_recipient(rch, r.get("recipient", "")) != _norm_notification_recipient(rch, recipient): return False
    if r.get("key") == key: return True
    try:
        target = _notification_signature(key, channel, recipient, athlete_name=athlete_name)
        actual = _notification_signature(r, channel, recipient, athlete_name=athlete_name)
        return target == actual
    except Exception:
        return False
def _notifica_stato(key, channel=None, recipient=None, athlete_name=None):
    for r in reversed(st.session_state.get("storico_notifiche", []) or []):
        if _record_matches_notification(r, key, channel, recipient, athlete_name=athlete_name): return r.get("status", "")
    return ""
def _notifica_inviata(key, channel=None, recipient=None, athlete_name=None):
    return _notifica_stato(key, channel, recipient, athlete_name=athlete_name) == "sent"
def _notifica_gia_tentata_oggi(key, oggi, channel=None, recipient=None, athlete_name=None):
    day = oggi.strftime("%Y-%m-%d")
    for r in reversed(st.session_state.get("storico_notifiche", []) or []):
        if str(r.get("date", ""))[:10] != day: continue
        if not _record_matches_notification(r, key, channel, recipient, athlete_name=athlete_name): continue
        if r.get("status") in {"not_configured", "error", "sent"}: return True
    return False
def _drive_service_from_secret():
    raw = _segreto("GOOGLE_SERVICE_ACCOUNT_JSON", "")
    if not raw:
        return None
    try:
        from google.oauth2 import service_account
        from googleapiclient.discovery import build
        info = json.loads(raw) if isinstance(raw, str) else dict(raw)
        creds = service_account.Credentials.from_service_account_info(
            info,
            scopes=["https://www.googleapis.com/auth/drive"]
        )
        return build(
            "drive",
            "v3",
            credentials=creds,
            cache_discovery=False
        )
    except Exception:
        return None
def _backup_drive_service_from_secret():
    """Usa lo stesso client Drive della persistenza, preferendo OAuth utente."""
    try:
        return _drive_service_persistenza()
    except Exception as exc:
        st.error(f"Errore Google Drive backup: {type(exc).__name__}: {exc}")
        return None


def carica_backup_su_google_drive(zip_bytes, nome_file, folder_id=GOOGLE_DRIVE_BACKUP_FOLDER_ID):
    """Carica un backup ZIP nella cartella Google Drive configurata.
    Usa prima l'account OAuth autorizzato e solo in alternativa il service account.
    Restituisce metadati del file caricato o un errore esplicito.
    """
    if not zip_bytes:
        return {"ok": False, "error": "Backup ZIP vuoto."}
    service = _backup_drive_service_from_secret()
    if service is None:
        return {
            "ok": False,
            "error": "Google Drive backup non configurato: OAuth non valido e Service Account non disponibile."
        }
    try:
        from googleapiclient.http import MediaIoBaseUpload
        body = {
            "name": str(nome_file),
            "parents": [str(folder_id)]
        }
        media = MediaIoBaseUpload(
            io.BytesIO(zip_bytes),
            mimetype="application/zip",
            resumable=False
        )
        file_meta = service.files().create(
            body=body,
            media_body=media,
            fields="id,name,size,createdTime,webViewLink,parents"
        ).execute()
        return {
            "ok": True,
            "id": file_meta.get("id", ""),
            "name": file_meta.get("name", nome_file),
            "size": int(file_meta.get("size", len(zip_bytes)) or len(zip_bytes)),
            "createdTime": file_meta.get("createdTime", ""),
            "webViewLink": file_meta.get("webViewLink", ""),
            "folder_id": folder_id
        }
    except Exception as exc:
        return {
            "ok": False,
            "error": f"Upload Google Drive fallito: {exc}",
            "folder_id": folder_id
        }


# ============================================================
# ARCHIVIO DOCUMENTI GOOGLE DRIVE
# Crea DOCUMENTI_GESTIONALE nel contenitore Drive gia autorizzato e organizza
# i file per stagione, atleta e tipologia. Non usa il registro notifiche.
# ============================================================
def _documenti_drive_root_id():
    try:
        section = st.secrets.get("gcp_documents")
        if section:
            folder_id = str(section.get("folder_id", "") or "").strip()
            if folder_id:
                return folder_id
    except Exception:
        pass
    return str(GOOGLE_DRIVE_BACKUP_FOLDER_ID)


def _documenti_drive_nome(value, fallback="SENZA_NOME"):
    testo = unicodedata.normalize("NFKD", str(value or "")).encode("ascii", "ignore").decode("ascii")
    testo = re.sub(r"[^A-Za-z0-9._-]+", "_", testo).strip("._-")
    return testo[:120] or fallback


def _documenti_drive_trova_cartella(service, nome, parent_id):
    nome_esc = str(nome).replace("\\", "\\\\").replace("'", "\\'")
    parent_esc = str(parent_id).replace("\\", "\\\\").replace("'", "\\'")
    result = service.files().list(
        q=f"name = '{nome_esc}' and '{parent_esc}' in parents and mimeType = 'application/vnd.google-apps.folder' and trashed = false",
        spaces="drive", fields="files(id,name,webViewLink)", pageSize=10,
        supportsAllDrives=True, includeItemsFromAllDrives=True,
    ).execute()
    files = result.get("files", [])
    return files[0] if files else None


def _documenti_drive_cartella(service, nome, parent_id):
    esistente = _documenti_drive_trova_cartella(service, nome, parent_id)
    if esistente:
        return esistente
    return service.files().create(
        body={"name": str(nome), "mimeType": "application/vnd.google-apps.folder", "parents": [str(parent_id)]},
        fields="id,name,webViewLink", supportsAllDrives=True,
    ).execute()


def _documenti_drive_percorso(service, atleta=None, tipo="ALTRI_DOCUMENTI", stagione=""):
    root = _documenti_drive_cartella(service, "DOCUMENTI_GESTIONALE", _documenti_drive_root_id())
    stagione_nome = _documenti_drive_nome(stagione or (atleta or {}).get("stagione", "") or "SENZA_STAGIONE")
    cartella_stagione = _documenti_drive_cartella(service, stagione_nome, root["id"])
    if atleta:
        atleta_nome = _documenti_drive_nome(f"{atleta.get('cognome','')} {atleta.get('nome','')}", "ATLETA")
        atleta_id = _documenti_drive_nome(str(atleta.get("id", ""))[:8], "")
        if atleta_id:
            atleta_nome = f"{atleta_nome}_{atleta_id}"
        cartella_atleta = _documenti_drive_cartella(service, atleta_nome, cartella_stagione["id"])
        destinazione = _documenti_drive_cartella(service, _documenti_drive_nome(tipo), cartella_atleta["id"])
    else:
        destinazione = _documenti_drive_cartella(service, _documenti_drive_nome(tipo), cartella_stagione["id"])
    return destinazione, root


def carica_documento_su_google_drive(dati_bytes, nome_file, atleta=None, tipo="ALTRI_DOCUMENTI", stagione="", mime="application/pdf"):
    if not dati_bytes:
        return {"ok": False, "error": "Documento vuoto."}
    service = _backup_drive_service_from_secret()
    if service is None:
        return {"ok": False, "error": "Google Drive documenti non configurato."}
    try:
        from googleapiclient.http import MediaIoBaseUpload
        cartella, root = _documenti_drive_percorso(service, atleta=atleta, tipo=tipo, stagione=stagione)
        nome = _documenti_drive_nome(nome_file, "documento.pdf")
        esistente = _trova_file_drive(service, nome, cartella["id"])
        media = MediaIoBaseUpload(io.BytesIO(bytes(dati_bytes)), mimetype=mime, resumable=False)
        if esistente:
            meta = service.files().update(fileId=esistente["id"], media_body=media, fields="id,name,size,modifiedTime,webViewLink,parents", supportsAllDrives=True).execute()
        else:
            meta = service.files().create(body={"name": nome, "parents": [cartella["id"]]}, media_body=media, fields="id,name,size,createdTime,webViewLink,parents", supportsAllDrives=True).execute()
        return {"ok": True, **meta, "folder_id": cartella["id"], "folder_link": cartella.get("webViewLink", ""), "root_folder_id": root["id"], "root_folder_link": root.get("webViewLink", "")}
    except Exception as exc:
        return {"ok": False, "error": f"Archivio documenti Drive: {type(exc).__name__}: {exc}"}


def scarica_documento_da_google_drive(file_id):
    if not file_id:
        return b""
    service = _backup_drive_service_from_secret()
    if service is None:
        return b""
    try:
        from googleapiclient.http import MediaIoBaseDownload
        buffer = io.BytesIO(); downloader = MediaIoBaseDownload(buffer, service.files().get_media(fileId=str(file_id), supportsAllDrives=True))
        done = False
        while not done:
            _, done = downloader.next_chunk()
        return buffer.getvalue()
    except Exception:
        return b""


@st.cache_data(ttl=300, show_spinner=False)
def _scarica_documento_drive_cached(file_id):
    """Recupera un allegato da Drive e ne mantiene una copia temporanea in cache."""
    return scarica_documento_da_google_drive(str(file_id or ""))


def _documenti_drive_elenca_figli(service, parent_id):
    parent_esc = str(parent_id).replace("\\", "\\\\").replace("'", "\\'")
    elementi, page_token = [], None
    while True:
        risposta = service.files().list(
            q=f"'{parent_esc}' in parents and trashed = false",
            spaces="drive",
            fields="nextPageToken,files(id,name,mimeType,size,modifiedTime,webViewLink)",
            pageSize=1000,
            pageToken=page_token,
            supportsAllDrives=True,
            includeItemsFromAllDrives=True,
        ).execute()
        elementi.extend(risposta.get("files", []) or [])
        page_token = risposta.get("nextPageToken")
        if not page_token:
            return elementi


def elenca_documenti_atleta_su_drive(atleta):
    """Consulta l'archivio Drive dell'atleta senza creare o modificare cartelle."""
    service = _backup_drive_service_from_secret()
    if service is None:
        return {"ok": False, "error": "Google Drive documenti non configurato.", "files": []}
    try:
        root = _documenti_drive_trova_cartella(service, "DOCUMENTI_GESTIONALE", _documenti_drive_root_id())
        if not root:
            return {"ok": True, "files": [], "message": "Cartella DOCUMENTI_GESTIONALE non trovata."}
        stagione_nome = _documenti_drive_nome(atleta.get("stagione", "") or "SENZA_STAGIONE")
        cartella_stagione = _documenti_drive_trova_cartella(service, stagione_nome, root["id"])
        if not cartella_stagione:
            return {"ok": True, "files": [], "message": f"Cartella stagione {stagione_nome} non trovata."}
        atleta_nome = _documenti_drive_nome(f"{atleta.get('cognome','')} {atleta.get('nome','')}", "ATLETA")
        atleta_id = _documenti_drive_nome(str(atleta.get("id", ""))[:8], "")
        if atleta_id:
            atleta_nome = f"{atleta_nome}_{atleta_id}"
        cartella_atleta = _documenti_drive_trova_cartella(service, atleta_nome, cartella_stagione["id"])
        if not cartella_atleta:
            return {"ok": True, "files": [], "message": "Cartella Drive dell'atleta non trovata."}

        mime_cartella = "application/vnd.google-apps.folder"
        righe = []
        for elemento in _documenti_drive_elenca_figli(service, cartella_atleta["id"]):
            if elemento.get("mimeType") == mime_cartella:
                tipo = str(elemento.get("name", "DOCUMENTI"))
                for file_meta in _documenti_drive_elenca_figli(service, elemento["id"]):
                    if file_meta.get("mimeType") != mime_cartella:
                        righe.append({"tipo": tipo, **file_meta})
            else:
                righe.append({"tipo": "SENZA_TIPO", **elemento})
        righe.sort(key=lambda x: (str(x.get("tipo", "")), str(x.get("name", "")).casefold()))
        return {"ok": True, "files": righe, "folder_link": cartella_atleta.get("webViewLink", "")}
    except Exception as exc:
        return {"ok": False, "error": f"Lettura archivio Drive: {type(exc).__name__}: {exc}", "files": []}


def sincronizza_documenti_esistenti_su_drive(atlete, solo_falliti=False):
    """Copia su Drive gli allegati gia presenti senza cancellare gli originali.

    Con ``solo_falliti=True`` vengono ritentati esclusivamente i documenti il
    cui ultimo caricamento e' terminato in errore. I documenti che possiedono
    gia' un ID Drive non vengono mai duplicati.
    """
    esito = {
        "caricati": 0,
        "gia_presenti_aggiornati": 0,
        "saltati": 0,
        "ritentati": 0,
        "errori": [],
    }
    visti = set()

    def carica_path(atleta, path_value, tipo, nome_preferito="", record=None, prefisso_record="drive"):
        if not str(path_value or "").strip():
            return
        stato_precedente = ""
        errore_precedente = ""
        if record is not None:
            stato_precedente = str(record.get(f"{prefisso_record}_stato", "") or "").strip().upper()
            errore_precedente = str(record.get(f"{prefisso_record}_errore", "") or "").strip()
        drive_id_precedente = ""
        if record is not None:
            drive_id_precedente = str(record.get(f"{prefisso_record}_id", "") or "").strip()
        # Comprende anche gli errori prodotti dalle versioni precedenti, che
        # potevano non salvare esplicitamente lo stato ERRORE nel record.
        caricamento_fallito = (
            stato_precedente == "ERRORE"
            or bool(errore_precedente)
            or (record is not None and not drive_id_precedente and stato_precedente != "CARICATO")
        )
        if solo_falliti and not caricamento_fallito:
            return
        if record is not None and str(record.get(f"{prefisso_record}_id", "")).strip():
            esito["gia_presenti_aggiornati"] += 1
            return
        if solo_falliti:
            esito["ritentati"] += 1
        path = Path(str(path_value or ""))
        if not path.exists() or not path.is_file():
            esito["saltati"] += 1; return
        chiave = (str(atleta.get("id", "")), str(path.resolve()), tipo)
        if chiave in visti:
            return
        visti.add(chiave)
        try:
            dati = path.read_bytes()
            if tipo == "CERTIFICATI_MEDICI" and _documento_sembra_privacy(dati):
                raise ValueError("il file associato come certificato sembra una Privacy")
            ext = path.suffix.lower()
            mime = {".pdf": "application/pdf", ".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".doc": "application/msword", ".docx": "application/vnd.openxmlformats-officedocument.wordprocessingml.document"}.get(ext, "application/octet-stream")
            nome = nome_preferito or _nome_download_documento(atleta, tipo.title(), path)
            risultato = carica_documento_su_google_drive(dati, nome, atleta=atleta, tipo=tipo, stagione=atleta.get("stagione", ""), mime=mime)
            if not risultato.get("ok"):
                raise ValueError(risultato.get("error", "errore Drive"))
            esito["caricati"] += 1
            if record is not None:
                record[f"{prefisso_record}_stato"] = "CARICATO"
                record[f"{prefisso_record}_id"] = risultato.get("id", "")
                record[f"{prefisso_record}_link"] = risultato.get("webViewLink", "")
                record[f"{prefisso_record}_errore"] = ""
        except Exception as exc:
            if record is not None:
                record[f"{prefisso_record}_stato"] = "ERRORE"
                record[f"{prefisso_record}_errore"] = str(exc)
            esito["errori"].append(f"{atleta.get('cognome','')} {atleta.get('nome','')} - {tipo}: {exc}")

    for atleta in atlete or []:
        if atleta.get("cognome") == "--- Inizializzazione":
            continue
        percorsi_richieste = set()
        for richiesta in atleta.get("firme_modulo_f", []) or []:
            for campo, tipo, prefisso in (("pdf_originale", "MODULI_F_DA_FIRMARE", "drive_originale"), ("pdf_firmato", "MODULI_F_FIRMATI", "drive_firmato")):
                valore = richiesta.get(campo)
                if valore: percorsi_richieste.add(str(Path(str(valore))))
                carica_path(atleta, valore, tipo, record=richiesta, prefisso_record=prefisso)
        for richiesta in atleta.get("firme_privacy", []) or []:
            for campo, tipo, prefisso in (("pdf_originale", "PRIVACY_DA_FIRMARE", "drive_originale"), ("pdf_firmato", "PRIVACY_FIRMATE", "drive_firmato")):
                valore = richiesta.get(campo)
                if valore: percorsi_richieste.add(str(Path(str(valore))))
                carica_path(atleta, valore, tipo, record=richiesta, prefisso_record=prefisso)
        carica_path(atleta, atleta.get("allegato_visita"), "CERTIFICATI_MEDICI", record=atleta, prefisso_record="allegato_visita_drive")
        if str(Path(str(atleta.get("allegato_privacy", "")))) not in percorsi_richieste:
            carica_path(atleta, atleta.get("allegato_privacy"), "PRIVACY", record=atleta, prefisso_record="allegato_privacy_drive")
        altri = atleta.get("allegati_altro", atleta.get("allegato_altro", []))
        altri = [altri] if isinstance(altri, str) and altri else (altri or [])
        metadati_altri = atleta.get("allegati_altro_drive", [])
        if not isinstance(metadati_altri, list):
            metadati_altri = []
        for indice, path in enumerate(altri, 1):
            if str(Path(str(path))) not in percorsi_richieste:
                while len(metadati_altri) < indice:
                    metadati_altri.append({})
                metadati_altri[indice - 1]["percorso_locale"] = str(path)
                carica_path(atleta, path, "ALTRI_DOCUMENTI", nome_preferito=_nome_download_documento(atleta, f"Altro_documento_{indice}", path), record=metadati_altri[indice - 1], prefisso_record="drive")
        atleta["allegati_altro_drive"] = metadati_altri

    modello = _privacy_modello_path()
    modello_fallito = (
        str(config_societa.get("privacy_modello_drive_stato", "") or "").strip().upper() == "ERRORE"
        or bool(str(config_societa.get("privacy_modello_drive_errore", "") or "").strip())
    )
    if modello and (not solo_falliti or modello_fallito):
        if solo_falliti:
            esito["ritentati"] += 1
        risultato_modello = carica_documento_su_google_drive(modello.read_bytes(), "Informativa_privacy_Pallavolo_Pinerolo.pdf", atleta=None, tipo="MODELLI_PRIVACY", stagione="GENERALE")
        if risultato_modello.get("ok"):
            esito["caricati"] += 1
            config_societa.update({"privacy_modello_drive_stato": "CARICATO", "privacy_modello_drive_id": risultato_modello.get("id", ""), "privacy_modello_drive_link": risultato_modello.get("webViewLink", ""), "privacy_modello_drive_errore": ""})
            salva_json_sicuro(FILE_CONFIG_SOCIETA, config_societa)
        else:
            config_societa.update({"privacy_modello_drive_stato": "ERRORE", "privacy_modello_drive_errore": risultato_modello.get("error", "errore Drive")})
            salva_json_sicuro(FILE_CONFIG_SOCIETA, config_societa)
            esito["errori"].append(f"Modello Privacy: {risultato_modello.get('error','errore Drive')}")
    salva_atlete(atlete)
    esito["errori"] = esito["errori"][:100]
    return esito


def riepilogo_documenti_atlete(atlete):
    """Crea il quadro tecnico dei documenti senza modificare dati o notifiche."""
    def stato_archivio(presente, percorso="", drive_id="", drive_link="", drive_stato=""):
        if not presente:
            return "DOCUMENTO MANCANTE"
        locale = bool(percorso and Path(str(percorso)).exists())
        remoto = bool(str(drive_id or "").strip() or str(drive_link or "").strip())
        if str(drive_stato or "").upper() == "ERRORE":
            return "DRIVE NON ACCESSIBILE"
        if locale and remoto:
            return "FILE LOCALE + LINK DRIVE"
        if remoto:
            return "LINK DRIVE PRESENTE"
        if locale:
            return "SOLO FILE LOCALE"
        return "DRIVE NON ACCESSIBILE"

    righe = []
    for atleta in atlete or []:
        if atleta.get("cognome") == "--- Inizializzazione":
            continue

        richieste_f = atleta.get("firme_modulo_f", []) or []
        richieste_privacy = atleta.get("firme_privacy", []) or []
        f_firmate = [r for r in richieste_f if str(r.get("stato", "")).upper() == "FIRMATO"]
        f_pending = [r for r in richieste_f if str(r.get("stato", "")).upper() != "FIRMATO"]
        privacy_firmate = [r for r in richieste_privacy if str(r.get("stato", "")).upper() == "FIRMATO"]
        privacy_pending = [r for r in richieste_privacy if str(r.get("stato", "")).upper() != "FIRMATO"]

        certificato_pres = bool(atleta.get("allegato_visita") or atleta.get("allegato_visita_drive_id") or atleta.get("certificato_url"))
        privacy_caricata = bool(atleta.get("allegato_privacy") or atleta.get("allegato_privacy_drive_id"))
        privacy_pres = bool(privacy_firmate or privacy_caricata)
        modulo_f_pres = bool(f_firmate)

        stato_privacy = "FIRMATA" if privacy_firmate else ("PRESENTE" if privacy_caricata else ("DA FIRMARE" if privacy_pending else "MANCANTE"))
        stato_modulo_f = "FIRMATO" if f_firmate else ("DA FIRMARE" if f_pending else "MANCANTE")

        privacy_rif = privacy_firmate[-1] if privacy_firmate else {}
        modulo_f_rif = f_firmate[-1] if f_firmate else {}
        archivio_certificato = stato_archivio(
            certificato_pres,
            atleta.get("allegato_visita", ""),
            atleta.get("allegato_visita_drive_id", ""),
            atleta.get("allegato_visita_drive_link", atleta.get("certificato_url", "")),
            atleta.get("allegato_visita_drive_stato", ""),
        )
        archivio_privacy = stato_archivio(
            privacy_pres,
            privacy_rif.get("pdf_firmato", atleta.get("allegato_privacy", "")),
            privacy_rif.get("drive_firmato_id", atleta.get("allegato_privacy_drive_id", "")),
            privacy_rif.get("drive_firmato_link", atleta.get("allegato_privacy_drive_link", "")),
            privacy_rif.get("drive_firmato_stato", atleta.get("allegato_privacy_drive_stato", "")),
        )
        archivio_modulo_f = stato_archivio(
            modulo_f_pres,
            modulo_f_rif.get("pdf_firmato", ""),
            modulo_f_rif.get("drive_firmato_id", ""),
            modulo_f_rif.get("drive_firmato_link", ""),
            modulo_f_rif.get("drive_firmato_stato", ""),
        )

        # Il riepilogo usa gli stessi riferimenti (ID oppure link Drive) mostrati
        # nelle colonne di dettaglio, così non può risultare PARZIALE quando i
        # singoli documenti indicano già un collegamento Drive presente.
        stati_archiviati = {"FILE LOCALE + LINK DRIVE", "LINK DRIVE PRESENTE"}
        elementi_drive = []
        if certificato_pres:
            elementi_drive.append(archivio_certificato in stati_archiviati)
        if privacy_pres:
            elementi_drive.append(archivio_privacy in stati_archiviati)
        if modulo_f_pres:
            elementi_drive.append(archivio_modulo_f in stati_archiviati)
        drive_stato = "ARCHIVIATI" if elementi_drive and all(elementi_drive) else ("PARZIALE" if any(elementi_drive) else "NON ARCHIVIATI")

        problemi = []
        if not certificato_pres: problemi.append("Certificato medico")
        if not privacy_pres: problemi.append("Privacy")
        if not modulo_f_pres: problemi.append("Modulo F")
        if elementi_drive and not all(elementi_drive): problemi.append("Copia Drive incompleta")

        righe.append({
            "_Atleta ID": str(atleta.get("id", "")),
            "Stagione": atleta.get("stagione", "") or "SENZA STAGIONE",
            "Cognome": atleta.get("cognome", ""),
            "Nome": atleta.get("nome", ""),
            "Gruppo": atleta.get("gruppo", ""),
            "Certificato medico": "PRESENTE" if certificato_pres else "MANCANTE",
            "Scadenza visita": atleta.get("scad_visita", "") or "—",
            "Privacy": stato_privacy,
            "Modulo F": stato_modulo_f,
            "Archivio certificato": archivio_certificato,
            "Archivio Privacy": archivio_privacy,
            "Archivio Modulo F": archivio_modulo_f,
            "Archivio file presenti": drive_stato,
            "Da completare": ", ".join(problemi) if problemi else "TUTTO COMPLETO",
        })
    return righe


def excel_riepilogo_documenti(df):
    output = io.BytesIO()
    with pd.ExcelWriter(output, engine="openpyxl") as writer:
        df.to_excel(writer, index=False, sheet_name="Controllo documenti")
        ws = writer.sheets["Controllo documenti"]
        ws.freeze_panes = "A2"
        ws.auto_filter.ref = ws.dimensions
        for colonna in ws.columns:
            larghezza = min(max(len(str(c.value or "")) for c in colonna) + 2, 45)
            ws.column_dimensions[colonna[0].column_letter].width = larghezza
    output.seek(0)
    return output.getvalue()

# ============================================================
# BACKUP AUTOMATICO VERSIONATO GOOGLE DRIVE
# ============================================================
BACKUP_AUTOMATICO_PREFISSO = "backup_auto_completo_monviso_"
BACKUP_AUTOMATICO_INTERVALLO_ORE = 6

def _ultimo_backup_auto_drive(service, folder_id=GOOGLE_DRIVE_BACKUP_FOLDER_ID):
    try:
        folder_esc = str(folder_id).replace("'", "\\'")
        q = (
            f"'{folder_esc}' in parents and trashed = false and "
            f"name contains '{BACKUP_AUTOMATICO_PREFISSO}'"
        )
        res = service.files().list(
            q=q,
            spaces="drive",
            fields="files(id,name,createdTime,modifiedTime,size,webViewLink)",
            orderBy="createdTime desc",
            pageSize=1,
        ).execute()
        files = res.get("files", [])
        return files[0] if files else None
    except Exception:
        return None

def _drive_time_to_datetime(value):
    try:
        txt = str(value or "").strip()
        if not txt:
            return None
        dt = datetime.fromisoformat(txt.replace("Z", "+00:00"))
        return dt.astimezone(ROME_TZ).replace(tzinfo=None)
    except Exception:
        return None

def esegui_backup_automatico_drive(force=False):
    """Backup ZIP completo automatico, al massimo ogni 6 ore."""
    session_key = "backup_auto_controllato_sessione"
    if st.session_state.get(session_key) and not force:
        return st.session_state.get("ultimo_backup_automatico_drive", {})

    service = _backup_drive_service_from_secret()
    if service is None:
        result = {
            "ok": False,
            "skipped": True,
            "error": "Google Drive non configurato per il backup automatico.",
        }
        st.session_state["ultimo_backup_automatico_drive"] = result
        st.session_state[session_key] = True
        return result

    ultimo = _ultimo_backup_auto_drive(service)
    ora = ora_italiana()
    ultimo_dt = _drive_time_to_datetime((ultimo or {}).get("createdTime"))

    if not force and ultimo_dt is not None:
        ore = (ora - ultimo_dt).total_seconds() / 3600.0
        if ore < BACKUP_AUTOMATICO_INTERVALLO_ORE:
            result = {
                "ok": True,
                "skipped": True,
                "reason": "Backup automatico recente già presente.",
                "timestamp_locale": ultimo_dt.strftime("%d/%m/%Y %H:%M:%S"),
                "file_name": (ultimo or {}).get("name", ""),
                "id": (ultimo or {}).get("id", ""),
                "webViewLink": (ultimo or {}).get("webViewLink", ""),
            }
            st.session_state["ultimo_backup_automatico_drive"] = result
            st.session_state[session_key] = True
            return result

    try:
        zip_completo = crea_backup_zip(include_allegati=True)
        nome = f"{BACKUP_AUTOMATICO_PREFISSO}{ora.strftime('%Y%m%d_%H%M%S')}.zip"
        result = carica_backup_su_google_drive(
            zip_completo, nome, folder_id=GOOGLE_DRIVE_BACKUP_FOLDER_ID
        )
        result["skipped"] = False
        result["timestamp_locale"] = ora.strftime("%d/%m/%Y %H:%M:%S")
        result["file_name"] = nome
        st.session_state["ultimo_backup_automatico_drive"] = result
        st.session_state[session_key] = True
        return result
    except Exception as exc:
        result = {
            "ok": False,
            "skipped": False,
            "error": f"{type(exc).__name__}: {exc}",
            "timestamp_locale": ora.strftime("%d/%m/%Y %H:%M:%S"),
        }
        st.session_state["ultimo_backup_automatico_drive"] = result
        st.session_state[session_key] = True
        return result

# Il backup ZIP automatico non parte all'apertura dell'app.
# Viene controllato solo dopo un vero salvataggio, così login e pagine restano veloci.

def _extract_drive_file_id(url):
    """Estrae l'ID di un file Google Drive da diversi formati di URL.

    Supporta i formati /file/d/ID, ?id=ID, /open?id=ID e
    /uc?export=download&id=ID. Restituisce una stringa vuota se
    l'ID non viene trovato.
    """
    url = str(url or "").strip()
    if not url:
        return ""

    # https://drive.google.com/file/d/FILE_ID/view
    match = re.search(r"/file/d/([a-zA-Z0-9_-]+)", url)
    if match:
        return match.group(1)

    # Gestisce /open?id=FILE_ID, /uc?id=FILE_ID e qualsiasi URL con id=...
    try:
        parsed = urlparse(url)
        query = parse_qs(parsed.query)
        file_id = query.get("id", [""])[0]
        if file_id:
            return str(file_id).strip()
    except Exception:
        pass

    # Fallback robusto per URL con parametri concatenati.
    match = re.search(r"[?&]id=([a-zA-Z0-9_-]+)", url)
    if match:
        return match.group(1)

    return ""

def scarica_certificato_da_google(url, atleta, timeout=30):
    url = str(url or "").strip()
    if not url: return "", ""
    athlete_id = str(atleta.get("id", "")) or uuid.uuid4().hex
    folder = Path(CARTELLA_ALLEGATI) / "atleti" / athlete_id
    try: folder.mkdir(parents=True, exist_ok=True)
    except OSError: return "", "impossibile creare la cartella dell'atleta"
    file_id = _extract_drive_file_id(url); data = b""; nome_file = "certificato_medico"; api_error = ""
    if file_id:
        service = _drive_service_from_secret()
        if service:
            try:
                from googleapiclient.http import MediaIoBaseDownload
                meta = service.files().get(fileId=file_id, fields="name,mimeType").execute(); nome_file = meta.get("name") or nome_file
                req = service.files().get_media(fileId=file_id); fh = io.BytesIO(); downloader = MediaIoBaseDownload(fh, req); done = False
                while not done: _, done = downloader.next_chunk()
                data = fh.getvalue()
            except Exception as exc:
                api_error = f"Drive API: {exc}"
        if not data:
            try:
                dl = f"https://drive.google.com/uc?export=download&id={file_id}"
                r = requests.get(dl, headers={"User-Agent":"Mozilla/5.0"}, timeout=timeout)
                if r.ok and r.content and "text/html" not in str(r.headers.get("content-type", "")): data = r.content
                else: api_error = api_error or f"File Drive non scaricabile (HTTP {r.status_code})"
            except Exception as exc: api_error = api_error or str(exc)
    else:
        try:
            r = requests.get(url, headers={"User-Agent":"Mozilla/5.0"}, timeout=timeout)
            if r.ok and r.content:
                data = r.content; cd = r.headers.get("content-disposition", ""); m = re.search(r'filename=["\']?([^"\';]+)', cd)
                if m: nome_file = m.group(1)
            else: api_error = f"URL non scaricabile (HTTP {r.status_code})"
        except Exception as exc: api_error = str(exc)
    if not data: return "", api_error or "file non accessibile; mantengo il collegamento online"
    if len(data) > MAX_UPLOAD_BYTES: return "", "certificato oltre il limite di 10 MB"
    ext = Path(nome_file).suffix.lower()
    if ext not in {".pdf", ".png", ".jpg", ".jpeg"}: ext = ".pdf"
    safe_prefix = re.sub(r"[^A-Za-z0-9_-]+", "_", f"{atleta.get('cognome','atleta')}_{atleta.get('nome','')}_certificato").strip("_") or "certificato"
    dest = folder / f"{safe_prefix}_{uuid.uuid4().hex[:8]}{ext}"
    try: dest.write_bytes(data); return str(dest), ""
    except OSError as exc: return "", str(exc)
def _smtp_settings():
    try: port = int(_segreto("SMTP_PORT", "587") or 587)
    except ValueError: port = 587
    return {
        "host": _segreto("SMTP_HOST", ""), "port": port, "user": _segreto("SMTP_USER", ""),
        "password": _segreto("SMTP_PASSWORD", ""), "from": _segreto("SMTP_FROM", "") or _segreto("SMTP_USER", ""),
        "tls": str(_segreto("SMTP_USE_TLS", "true")).lower() not in {"0", "false", "no"},
    }
def invia_email_automatica(recipient, subject, body):
    recipient = _safe_email(recipient); cfg = _smtp_settings()
    if not recipient: return False, "indirizzo email non valido"
    if not cfg["host"] or not cfg["user"] or not cfg["password"]: return False, "SMTP non configurato nei Secrets/variabili d'ambiente"
    msg = EmailMessage(); msg["From"] = cfg["from"]; msg["To"] = recipient; msg["Subject"] = subject; msg.set_content(body)
    try:
        with smtplib.SMTP(cfg["host"], cfg["port"], timeout=30) as server:
            if cfg["tls"]: server.starttls()
            server.login(cfg["user"], cfg["password"]); server.send_message(msg)
        return True, ""
    except Exception as exc: return False, str(exc)

def invia_email_con_allegato(recipient, subject, body, allegato_bytes, nome_allegato, bcc=""):
    """Invia un PDF tramite la configurazione SMTP gia usata dalle notifiche."""
    recipient = _safe_email(recipient); cfg = _smtp_settings()
    if not recipient: return False, "indirizzo email non valido"
    if not cfg["host"] or not cfg["user"] or not cfg["password"]:
        return False, "SMTP non configurato nei Secrets/variabili d'ambiente"
    if not allegato_bytes: return False, "allegato PDF vuoto"
    bcc = _safe_email(bcc)
    msg = EmailMessage(); msg["From"] = cfg["from"]; msg["To"] = recipient; msg["Subject"] = subject
    if bcc and bcc.lower() != recipient.lower(): msg["Bcc"] = bcc
    msg.set_content(body)
    msg.add_attachment(bytes(allegato_bytes), maintype="application", subtype="pdf", filename=str(nome_allegato or "documento.pdf"))
    try:
        with smtplib.SMTP(cfg["host"], cfg["port"], timeout=30) as server:
            if cfg["tls"]: server.starttls()
            server.login(cfg["user"], cfg["password"]); server.send_message(msg)
        return True, ""
    except Exception as exc: return False, str(exc)


# ============================================================
# FIRMA MOBILE MODULO F FIPAV
# Il registro e conservato dentro atlete.json; originali e firmati usano la
# cartella allegati gia gestita dal gestionale. Non modifica notifiche o rate.
# ============================================================
FIRMA_MODULO_BOX = {
    1: (400, 449, 160, 18),
    2: (400, 287, 160, 18),
    3: (400, 125, 160, 18),
}


def _firma_modulo_nome_sicuro(value):
    return re.sub(r"[^A-Za-z0-9_-]+", "_", str(value or "")).strip("_") or "documento"


@st.cache_data(show_spinner=False)
def _firma_qr_svg(link):
    """Genera un QR SVG senza dipendenze aggiuntive, usando ReportLab."""
    from reportlab.graphics.barcode.qr import QrCodeWidget
    from reportlab.graphics.shapes import Drawing
    from reportlab.graphics import renderSVG
    valore = str(link or "").strip()
    if not valore.startswith(("http://", "https://")):
        return ""
    qr = QrCodeWidget(valore)
    x0, y0, x1, y1 = qr.getBounds()
    lato, margine = 220, 12
    scala = min((lato - margine * 2) / max(x1 - x0, 1), (lato - margine * 2) / max(y1 - y0, 1))
    disegno = Drawing(
        lato, lato,
        transform=[scala, 0, 0, scala, margine - x0 * scala, margine - y0 * scala],
    )
    disegno.add(qr)
    return renderSVG.drawToString(disegno)


@st.cache_data(show_spinner=False)
def _qr_svg_con_etichetta(link, etichetta):
    """Genera un QR stampabile con una dicitura grande sotto al codice."""
    from reportlab.graphics.barcode.qr import QrCodeWidget
    from reportlab.graphics.shapes import Drawing, String, Group
    from reportlab.graphics import renderSVG
    valore = str(link or "").strip()
    testo = str(etichetta or "CODICE QR").strip().upper()
    if not valore.startswith(("http://", "https://")):
        return ""
    qr = QrCodeWidget(valore)
    x0, y0, x1, y1 = qr.getBounds()
    larghezza, altezza, lato, margine = 260, 285, 220, 12
    scala = min((lato - margine * 2) / max(x1 - x0, 1), (lato - margine * 2) / max(y1 - y0, 1))
    disegno = Drawing(larghezza, altezza)
    # Centra il QR nella parte superiore e lascia spazio alla descrizione.
    spostamento_x = (larghezza - lato) / 2 + margine - x0 * scala
    spostamento_y = 52 + margine - y0 * scala
    gruppo_qr = Group(qr)
    gruppo_qr.transform = [scala, 0, 0, scala, spostamento_x, spostamento_y]
    disegno.add(gruppo_qr)
    dimensione = 17 if len(testo) <= 24 else (14 if len(testo) <= 34 else 11)
    disegno.add(String(
        larghezza / 2, 28, testo, textAnchor="middle",
        fontName="Helvetica-Bold", fontSize=dimensione, fillColor=colors.HexColor('#0b5fa5')
    ))
    return renderSVG.drawToString(disegno)


def mostra_qr_firma(link, titolo, key):
    link = str(link or "").strip()
    if not link.startswith(("http://", "https://")):
        return
    svg = _firma_qr_svg(link)
    st.markdown(f"#### 📱 {titolo}")
    q1, q2 = st.columns([1, 2.4], vertical_alignment="center")
    with q1:
        if svg:
            # Streamlit/Pillow non interpreta sempre i byte SVG come immagine.
            # Il QR viene quindi incorporato direttamente come data URI SVG.
            svg_b64 = base64.b64encode(svg.encode("utf-8")).decode("ascii")
            st.markdown(
                f'<img src="data:image/svg+xml;base64,{svg_b64}" '
                'width="220" height="220" alt="Codice QR per la firma">',
                unsafe_allow_html=True,
            )
    with q2:
        st.write("Inquadra il codice QR con la fotocamera del telefono o del tablet.")
        st.code(link, language=None)
        st.link_button("APRI PAGINA DI FIRMA", link, use_container_width=True)
        if svg:
            st.download_button(
                "SCARICA CODICE QR",
                svg.encode("utf-8"),
                file_name=f"QR_{_firma_modulo_nome_sicuro(titolo)}.svg",
                mime="image/svg+xml",
                use_container_width=True,
                key=f"qr_download_{key}",
                on_click="ignore",
            )


def _firma_modulo_ritaglia(image):
    image = image.convert("RGBA")
    bianco = Image.new("RGBA", image.size, (255, 255, 255, 255))
    diff = ImageChops.difference(image, bianco).convert("L")
    bbox = diff.point(lambda p: 255 if p > 20 else 0).getbbox()
    if not bbox:
        raise ValueError("Firma vuota: firma nel riquadro prima di confermare.")
    cropped = image.crop(bbox)
    px = cropped.load()
    for yy in range(cropped.height):
        for xx in range(cropped.width):
            r, g, b, _ = px[xx, yy]
            px[xx, yy] = (15, 35, 90, 255 - min(r, g, b))
    # Il riquadro PDF e molto basso: dopo il ridimensionamento un tratto normale
    # diventerebbe quasi invisibile. Dilatiamo solo l'inchiostro, senza cambiare
    # dimensione o posizione della firma.
    alpha = cropped.getchannel("A").filter(ImageFilter.MaxFilter(7))
    cropped.putalpha(alpha)
    return cropped


def _firma_modulo_applica_pdf(pdf_bytes, pagina, posizione, firma_image):
    from pypdf import PdfReader, PdfWriter
    reader = PdfReader(io.BytesIO(pdf_bytes), strict=False)
    pagina = int(pagina)
    posizione = int(posizione)
    if pagina < 1 or pagina > len(reader.pages):
        raise ValueError("Pagina del PDF non valida.")
    if posizione not in FIRMA_MODULO_BOX:
        raise ValueError("Posizione dell'atleta non valida.")
    x, y, w, h = FIRMA_MODULO_BOX[posizione]
    sig = _firma_modulo_ritaglia(firma_image)
    sig_buffer = io.BytesIO()
    sig.save(sig_buffer, format="PNG")
    sig_buffer.seek(0)
    page = reader.pages[pagina - 1]
    page_w, page_h = float(page.mediabox.width), float(page.mediabox.height)
    overlay_buffer = io.BytesIO()
    overlay = canvas.Canvas(overlay_buffer, pagesize=(page_w, page_h))
    margin = 3
    scale = min((w - 2 * margin) / sig.width, (h - 5) / sig.height)
    draw_w, draw_h = sig.width * scale, sig.height * scale
    draw_x = x + (w - draw_w) / 2
    draw_y = y + 3 + (h - 3 - draw_h) / 2
    overlay.drawImage(ImageReader(sig_buffer), draw_x, draw_y, width=draw_w, height=draw_h, mask="auto")
    overlay.save()
    overlay_buffer.seek(0)
    page.merge_page(PdfReader(overlay_buffer).pages[0])
    writer = PdfWriter()
    for source_page in reader.pages:
        writer.add_page(source_page)
    output = io.BytesIO()
    writer.write(output)
    return output.getvalue()


def _firma_modulo_trova(token):
    token = str(token or "").strip()
    if not token:
        return None, None
    for atleta in st.session_state.get("elenco_atlete", []):
        for richiesta in atleta.get("firme_modulo_f", []) or []:
            if hmac.compare_digest(str(richiesta.get("token", "")), token):
                return atleta, richiesta
    return None, None


def _firma_modulo_salva_risultato(atleta_corrente, richiesta_corrente, firmato_path):
    """Unisce il risultato della sessione mobile con l'archivio piu recente.

    Telefono e pagina amministrativa sono sessioni Streamlit diverse: prima di
    salvare rileggiamo atlete.json e aggiorniamo solo la richiesta interessata.
    """
    archivio = carica_atlete()
    atleta_id = str((atleta_corrente or {}).get("id", ""))
    richiesta_id = str((richiesta_corrente or {}).get("id", ""))
    atleta_archivio = next((a for a in archivio if str(a.get("id", "")) == atleta_id), None)
    if atleta_archivio is None:
        raise ValueError("Scheda atleta non trovata nell'archivio aggiornato.")
    richieste = atleta_archivio.setdefault("firme_modulo_f", [])
    richiesta_archivio = next((r for r in richieste if str(r.get("id", "")) == richiesta_id), None)
    if richiesta_archivio is None:
        richieste.append(dict(richiesta_corrente))
    else:
        richiesta_archivio.update(dict(richiesta_corrente))
    altri = atleta_archivio.get("allegati_altro", atleta_archivio.get("allegato_altro", []))
    altri = [altri] if isinstance(altri, str) and altri else ([] if not isinstance(altri, list) else altri)
    if str(firmato_path) not in altri:
        altri.append(str(firmato_path))
    atleta_archivio["allegati_altro"] = altri
    salva_atlete(archivio)
    st.session_state["elenco_atlete"] = archivio
    return atleta_archivio


def _firma_modulo_email_societa():
    cfg = _smtp_settings()
    return _safe_email(
        config_societa.get("email_societa_certificazioni", "")
        or cfg.get("from", "")
        or cfg.get("user", "")
    )


def _firma_modulo_invia(atleta, richiesta, pdf_bytes, nome_file):
    modalita = str(richiesta.get("destinazione_pdf", "SOLO_SOCIETA"))
    atleta_nome = f"{atleta.get('cognome','')} {atleta.get('nome','')}".strip().upper()
    email_genitore = _safe_email(richiesta.get("email_genitore", ""))
    email_societa = _firma_modulo_email_societa()
    destinatari_pdf = []
    if modalita in {"SOLO_SOCIETA", "SOCIETA_E_GENITORE"} and email_societa:
        destinatari_pdf.append(("SOCIETA", email_societa))
    if modalita in {"SOLO_GENITORE", "SOCIETA_E_GENITORE"} and email_genitore:
        destinatari_pdf.append(("GENITORE", email_genitore))
    esiti = []
    oggetto = f"{nome_societa} - Modulo F FIPAV firmato - {atleta_nome}"
    corpo = (
        f"In allegato il Modulo F FIPAV firmato relativo all'atleta {atleta_nome}.\n\n"
        f"Richiesta creata dal Gestionale {nome_societa}."
    )
    for tipo, email in destinatari_pdf:
        ok, errore = invia_email_con_allegato(email, oggetto, corpo, pdf_bytes, nome_file)
        esiti.append({"tipo": tipo, "email": email, "stato": "INVIATA" if ok else "ERRORE", "errore": errore})
    if modalita == "SOLO_SOCIETA" and email_genitore:
        ok, errore = invia_email_automatica(
            email_genitore,
            f"{nome_societa} - Firma Modulo F acquisita - {atleta_nome}",
            f"Gentile genitore,\n\nla firma del Modulo F relativa a {atleta_nome} e stata acquisita correttamente. "
            f"Il documento completo e stato trasmesso alla societa.\n\nCordiali saluti,\n{nome_societa}",
        )
        esiti.append({"tipo": "CONFERMA_GENITORE", "email": email_genitore, "stato": "INVIATA" if ok else "ERRORE", "errore": errore})
    if not destinatari_pdf:
        esiti.append({"tipo": "PDF", "email": "", "stato": "ERRORE", "errore": "Nessun destinatario PDF configurato"})
    return esiti


def render_firma_modulo_pubblica(token):
    atleta, richiesta = _firma_modulo_trova(token)
    st.markdown("## Firma Modulo F FIPAV")
    if not atleta or not richiesta:
        st.error("Collegamento non valido o non piu disponibile.")
        return
    atleta_nome = f"{atleta.get('cognome','')} {atleta.get('nome','')}".strip().upper()
    if richiesta.get("stato") == "FIRMATO":
        st.success(f"La firma per {atleta_nome} e gia stata acquisita il {richiesta.get('firmato_il','')}.")
        return
    try:
        scadenza = datetime.fromisoformat(str(richiesta.get("scade_il", "")))
        if ora_italiana().replace(tzinfo=None) > scadenza.replace(tzinfo=None):
            richiesta["stato"] = "SCADUTA"
            salva_atlete(st.session_state["elenco_atlete"])
            st.error("Il collegamento di firma e scaduto. Contatta la societa per riceverne uno nuovo.")
            return
    except Exception:
        pass
    st.info(f"Atleta: **{atleta_nome}**")
    st.caption("In questa pagina sono mostrati soltanto il nome dell'atleta e il riquadro di firma. Il modulo completo non viene visualizzato.")
    if not FIRMA_MOBILE_CANVAS_DISPONIBILE:
        st.error("Componente firma non installato. Aggiorna requirements.txt con streamlit-drawable-canvas-fix==0.9.8.")
        return
    firmatario = st.text_input("Nome e cognome del genitore/tutore che firma")
    consenso = st.checkbox("Confermo di essere il genitore/tutore dell'atleta e di voler sottoscrivere il modulo.")
    st.markdown("**Firma nel riquadro usando il dito, il pennino o il mouse:**")
    drawing = st_canvas(
        stroke_width=5, stroke_color="#0f235a", background_color="#ffffff",
        height=170, width=340, drawing_mode="freedraw", key=f"firma_modulo_canvas_{richiesta.get('id','')}"
    )
    st.caption("Per rifare la firma usa il cestino presente nel riquadro.")
    if st.button("CONFERMA FIRMA E GENERA PDF", type="primary", use_container_width=True, disabled=not consenso):
        if len(firmatario.strip()) < 5:
            st.error("Inserisci nome e cognome del firmatario.")
            return
        if drawing.image_data is None:
            st.error("Firma nel riquadro prima di confermare.")
            return
        try:
            originale_path = Path(str(richiesta.get("pdf_originale", "")))
            if not originale_path.exists():
                recuperato = scarica_documento_da_google_drive(richiesta.get("drive_originale_id", ""))
                if recuperato:
                    originale_path.parent.mkdir(parents=True, exist_ok=True); originale_path.write_bytes(recuperato)
                else:
                    raise FileNotFoundError("Il PDF originale non e disponibile.")
            firmato = _firma_modulo_applica_pdf(
                originale_path.read_bytes(), richiesta.get("pagina", 1), richiesta.get("posizione", 1),
                Image.fromarray(drawing.image_data.astype("uint8")),
            )
            folder = Path(CARTELLA_ALLEGATI) / "firme_modulo_f"
            folder.mkdir(parents=True, exist_ok=True)
            nome_atleta_file = _firma_modulo_nome_sicuro(atleta_nome)
            stagione_file = _firma_modulo_nome_sicuro(atleta.get("stagione", "SENZA_STAGIONE"))
            data_file = ora_italiana().strftime("%Y%m%d")
            nome_file = f"{nome_atleta_file}_Modulo_F_{stagione_file}_{data_file}.pdf"
            firmato_path = folder / nome_file
            firmato_path.write_bytes(firmato)
            drive_firmato = carica_documento_su_google_drive(
                firmato, nome_file, atleta=atleta, tipo="MODULI_F_FIRMATI", stagione=atleta.get("stagione", "")
            )
            firmato_il = ora_italiana().strftime("%d/%m/%Y %H:%M:%S")
            richiesta.update({
                "stato": "FIRMATO", "firmatario": firmatario.strip().upper(), "firmato_il": firmato_il,
                "pdf_firmato": str(firmato_path), "hash_firmato": hashlib.sha256(firmato).hexdigest(),
                "drive_firmato_stato": "CARICATO" if drive_firmato.get("ok") else "ERRORE",
                "drive_firmato_id": drive_firmato.get("id", ""), "drive_firmato_link": drive_firmato.get("webViewLink", ""),
                "drive_firmato_errore": drive_firmato.get("error", ""),
            })
            richiesta["email_esiti"] = _firma_modulo_invia(atleta, richiesta, firmato, nome_file)
            richiesta["email_stato"] = (
                "INVIATA" if richiesta["email_esiti"] and all(x.get("stato") == "INVIATA" for x in richiesta["email_esiti"])
                else "PARZIALE" if any(x.get("stato") == "INVIATA" for x in richiesta["email_esiti"])
                else "ERRORE"
            )
            _firma_modulo_salva_risultato(atleta, richiesta, firmato_path)
            if richiesta["email_stato"] == "INVIATA":
                st.success("Firma acquisita e invio completato correttamente.")
            else:
                errori = "; ".join(x.get("errore", "") for x in richiesta["email_esiti"] if x.get("stato") == "ERRORE")
                st.warning(f"Firma acquisita e PDF salvato. Invio e-mail da verificare: {errori}")
        except Exception as exc:
            st.error(f"Impossibile completare la firma: {exc}")


def render_firma_modulo_admin(atleta, suffix):
    st.markdown("### Firma mobile Modulo F FIPAV")
    st.caption("Carica il Modulo F, indica pagina e posizione dell'atleta e genera il collegamento da inviare al genitore.")
    # Rilegge solo i dati della firma dalla copia piu recente: evita che la
    # sessione aperta sul PC continui a mostrare DA FIRMARE dopo la firma mobile.
    try:
        archivio_fresco = carica_atlete()
        atleta_fresca = next((a for a in archivio_fresco if str(a.get("id", "")) == str(atleta.get("id", ""))), None)
        if atleta_fresca is not None:
            atleta["firme_modulo_f"] = atleta_fresca.get("firme_modulo_f", [])
            atleta["allegati_altro"] = atleta_fresca.get("allegati_altro", atleta.get("allegati_altro", []))
    except Exception:
        pass
    if st.button("AGGIORNA STATO FIRME", use_container_width=True, key=f"firma_mod_refresh_{suffix}"):
        st.rerun()
    email_genitori = _email_genitori_atleta(atleta)
    email_genitore = st.selectbox(
        "E-mail del genitore/tutore", email_genitori or [""],
        format_func=lambda x: x or "Nessuna e-mail registrata", key=f"firma_mod_email_{suffix}"
    )
    modalita_label = st.selectbox(
        "Destinazione del PDF completo",
        ["Solo societa", "Societa e genitore", "Solo genitore"],
        key=f"firma_mod_dest_{suffix}",
        help="Il Modulo F puo contenere dati di altre atlete. L'impostazione consigliata e Solo societa."
    )
    modalita = {"Solo societa": "SOLO_SOCIETA", "Societa e genitore": "SOCIETA_E_GENITORE", "Solo genitore": "SOLO_GENITORE"}[modalita_label]
    if modalita != "SOLO_SOCIETA":
        st.warning("Il PDF completo puo contenere dati personali di altre atlete. Verifica il documento prima di inviarlo al genitore.")
    upload = st.file_uploader("Modulo F FIPAV da firmare", type=["pdf"], key=f"firma_mod_pdf_{suffix}")
    c1, c2 = st.columns(2)
    pagina = c1.number_input("Pagina del PDF", min_value=1, value=1, step=1, key=f"firma_mod_pag_{suffix}")
    posizione = c2.selectbox("Posizione atleta nella pagina", [1, 2, 3], format_func=lambda x: f"{x}a atleta", key=f"firma_mod_pos_{suffix}")
    base_url = st.text_input(
        "Indirizzo pubblico del gestionale", value=str(_segreto("APP_PUBLIC_URL", "") or ""),
        placeholder="https://nome-gestionale.streamlit.app", key=f"firma_mod_url_{suffix}"
    )
    if st.button("CREA COLLEGAMENTO DI FIRMA", type="primary", use_container_width=True, key=f"firma_mod_crea_{suffix}", disabled=not ha_permesso("gestisci_documenti")):
        societa_email = _firma_modulo_email_societa()
        if not upload:
            st.error("Carica prima il Modulo F in PDF.")
        elif not str(base_url).startswith("http"):
            st.error("Inserisci l'indirizzo pubblico completo del gestionale.")
        elif not email_genitore:
            st.error("Nella scheda atleta manca l'e-mail del genitore.")
        elif modalita in {"SOLO_SOCIETA", "SOCIETA_E_GENITORE"} and not societa_email:
            st.error("Configura l'e-mail della societa oppure SMTP_FROM nei Secrets.")
        else:
            richiesta_id = uuid.uuid4().hex
            token = secrets.token_urlsafe(32)
            folder = Path(CARTELLA_ALLEGATI) / "firme_modulo_f"
            folder.mkdir(parents=True, exist_ok=True)
            nome_atleta_originale = _firma_modulo_nome_sicuro(f"{atleta.get('cognome','')} {atleta.get('nome','')}")
            stagione_originale = _firma_modulo_nome_sicuro(atleta.get("stagione", "SENZA_STAGIONE"))
            originale_path = folder / f"{nome_atleta_originale}_Modulo_F_da_firmare_{stagione_originale}_{richiesta_id[:8]}.pdf"
            originale_path.write_bytes(upload.getvalue())
            drive_originale = carica_documento_su_google_drive(
                upload.getvalue(), originale_path.name, atleta=atleta,
                tipo="MODULI_F_DA_FIRMARE", stagione=atleta.get("stagione", "")
            )
            ora = ora_italiana().replace(tzinfo=None)
            richiesta = {
                "id": richiesta_id, "token": token, "stato": "DA FIRMARE",
                "atleta_id": str(atleta.get("id", "")), "email_genitore": email_genitore,
                "destinazione_pdf": modalita, "pagina": int(pagina), "posizione": int(posizione),
                "pdf_originale": str(originale_path), "nome_originale": upload.name,
                "hash_originale": hashlib.sha256(upload.getvalue()).hexdigest(),
                "drive_originale_stato": "CARICATO" if drive_originale.get("ok") else "ERRORE",
                "drive_originale_id": drive_originale.get("id", ""), "drive_originale_link": drive_originale.get("webViewLink", ""),
                "drive_originale_errore": drive_originale.get("error", ""),
                "creata_il": ora.strftime("%d/%m/%Y %H:%M:%S"),
                "scade_il": (ora + timedelta(days=30)).isoformat(timespec="seconds"),
                "link": f"{str(base_url).rstrip('/')}?firma_modulo={token}",
            }
            atleta.setdefault("firme_modulo_f", []).append(richiesta)
            salva_atlete(st.session_state["elenco_atlete"])
            atleta_nome = f"{atleta.get('cognome','')} {atleta.get('nome','')}".strip().upper()
            link_ok, link_errore = invia_email_automatica(
                email_genitore,
                f"{nome_societa} - Firma Modulo F FIPAV - {atleta_nome}",
                f"Gentile genitore/tutore,\n\n"
                f"per firmare il Modulo F FIPAV relativo a {atleta_nome}, apra dal telefono, tablet o computer il seguente collegamento:\n\n"
                f"{richiesta['link']}\n\n"
                f"Il collegamento e personale e scade dopo 30 giorni. Non inoltrarlo ad altre persone.\n\n"
                f"Cordiali saluti,\n{nome_societa}",
            )
            richiesta["invio_link_stato"] = "INVIATO" if link_ok else "ERRORE"
            richiesta["invio_link_il"] = ora_italiana().strftime("%d/%m/%Y %H:%M:%S")
            richiesta["invio_link_errore"] = link_errore
            salva_atlete(st.session_state["elenco_atlete"])
            if link_ok:
                st.success(f"Collegamento creato e inviato a {email_genitore}.")
            else:
                st.warning(f"Collegamento creato, ma e-mail non inviata: {link_errore}")
            st.code(richiesta["link"], language=None)
            st.link_button("APRI PAGINA DI FIRMA", richiesta["link"], use_container_width=True)
    richieste = list(reversed(atleta.get("firme_modulo_f", []) or []))
    if richieste:
        st.markdown("#### Stato richieste")
        st.dataframe(pd.DataFrame([{
            "Creata": r.get("creata_il", ""), "Stato": r.get("stato", ""),
            "Pagina/posizione": f"{r.get('pagina','')}/{r.get('posizione','')}",
            "Destinazione": r.get("destinazione_pdf", ""), "Firmatario": r.get("firmatario", ""),
            "Invio link": r.get("invio_link_stato", "NON INVIATO"),
            "Invio PDF": r.get("email_stato", "NON INVIATO"), "Google Drive": r.get("drive_firmato_stato", r.get("drive_originale_stato", "NON CARICATO")),
        } for r in richieste]), use_container_width=True, hide_index=True)
        da_firmare = next((r for r in richieste if r.get("stato") == "DA FIRMARE" and r.get("link")), None)
        if da_firmare:
            mostra_qr_firma(
                da_firmare.get("link", ""),
                "Codice QR Modulo F",
                f"modulo_f_{suffix}_{da_firmare.get('id','')}",
            )
        ultima_firmata = next((r for r in richieste if r.get("pdf_firmato") and Path(str(r.get("pdf_firmato"))).exists()), None)
        if ultima_firmata:
            p = Path(str(ultima_firmata["pdf_firmato"]))
            st.download_button("SCARICA ULTIMO MODULO FIRMATO", p.read_bytes(), file_name=p.name, mime="application/pdf", use_container_width=True, key=f"firma_mod_dl_{suffix}")

def _privacy_trova(token):
    token = str(token or "").strip()
    if not token:
        return None, None
    for atleta in st.session_state.get("elenco_atlete", []):
        for richiesta in atleta.get("firme_privacy", []) or []:
            if hmac.compare_digest(str(richiesta.get("token", "")), token):
                return atleta, richiesta
    return None, None


def _privacy_salva_risultato(atleta_corrente, richiesta_corrente, firmato_path):
    archivio = carica_atlete()
    atleta_id = str((atleta_corrente or {}).get("id", ""))
    richiesta_id = str((richiesta_corrente or {}).get("id", ""))
    atleta_archivio = next((a for a in archivio if str(a.get("id", "")) == atleta_id), None)
    if atleta_archivio is None:
        raise ValueError("Scheda atleta non trovata nell'archivio aggiornato.")
    richieste = atleta_archivio.setdefault("firme_privacy", [])
    richiesta_archivio = next((r for r in richieste if str(r.get("id", "")) == richiesta_id), None)
    if richiesta_archivio is None:
        richieste.append(dict(richiesta_corrente))
    else:
        richiesta_archivio.update(dict(richiesta_corrente))
    atleta_archivio["allegato_privacy"] = str(firmato_path)
    salva_atlete(archivio)
    st.session_state["elenco_atlete"] = archivio
    return atleta_archivio


def _privacy_valore_scelta(valore):
    return "DO IL CONSENSO" if str(valore).upper().startswith("DO ") else "NEGO IL CONSENSO"


def _privacy_genera_pdf(originale_bytes, atleta, richiesta, dati, firma_image):
    """Aggiunge all'informativa originale una pagina riepilogativa sottoscritta."""
    from pypdf import PdfReader, PdfWriter
    firma = _firma_modulo_ritaglia(firma_image)
    firma_buf = io.BytesIO(); firma.save(firma_buf, format="PNG"); firma_buf.seek(0)
    page_buf = io.BytesIO()
    c = canvas.Canvas(page_buf, pagesize=A4)
    larghezza, altezza = A4
    c.setTitle("Consenso privacy atleta minorenne")
    c.setFont("Helvetica-Bold", 13)
    c.drawString(42, altezza - 48, "CONSENSO PRIVACY E LIBERATORIA ATLETA MINORE")
    c.setFont("Helvetica", 8)
    c.drawString(42, altezza - 64, "Informativa Pallavolo Pinerolo S.S.D. A.R.L. - riepilogo compilazione elettronica")
    y = altezza - 90
    righe = [
        ("Atleta", f"{atleta.get('cognome','')} {atleta.get('nome','')}".strip().upper()),
        ("Nato/a a", f"{atleta.get('luogo_nas','')} ({atleta.get('prov_nas','')}) il {atleta.get('data_nas','')}".strip()),
        ("Residente", f"{atleta.get('indirizzo_res','')} - {atleta.get('citta_res','')} ({atleta.get('prov_res','')})".strip()),
        ("Genitore/tutore", dati.get("firmatario", "")),
        ("Nato/a a", f"{dati.get('luogo_nascita_genitore','')} il {dati.get('data_nascita_genitore','')}".strip()),
        ("Altro genitore", dati.get("altro_genitore", "")),
        ("Luogo e data", f"{dati.get('luogo','Pinerolo')}, {dati.get('data','')}"),
    ]
    for etichetta, valore in righe:
        c.setFont("Helvetica-Bold", 9); c.drawString(42, y, f"{etichetta}:")
        c.setFont("Helvetica", 9); c.drawString(145, y, str(valore or "-")[:92]); y -= 18
    y -= 5
    consensi = [
        ("Finalita obbligatorie indicate al punto 1", dati.get("consenso_obbligatorie")),
        ("Finalita facoltative indicate al punto 2", dati.get("consenso_facoltative")),
        ("Comunicazioni commerciali del Titolare", dati.get("consenso_comunicazioni")),
        ("Comunicazioni promozionali di soggetti terzi", dati.get("consenso_terzi")),
        ("Acquisizione, pubblicazione e utilizzo di immagini, video e audio", dati.get("consenso_immagini")),
    ]
    c.setFont("Helvetica-Bold", 10); c.drawString(42, y, "SCELTE ESPRESSE"); y -= 20
    for descrizione, valore in consensi:
        scelta = _privacy_valore_scelta(valore)
        c.setFont("Helvetica-Bold", 8.5)
        c.drawString(48, y, "[X]" if scelta == "DO IL CONSENSO" else "[ ]")
        c.drawString(72, y, "DO IL CONSENSO")
        c.drawString(190, y, "[X]" if scelta == "NEGO IL CONSENSO" else "[ ]")
        c.drawString(214, y, "NEGO IL CONSENSO")
        c.setFont("Helvetica", 8.5); c.drawString(72, y - 13, descrizione[:93]); y -= 38
    c.setFont("Helvetica", 8)
    testo = "Il firmatario dichiara di aver letto l'informativa allegata, di esercitare la responsabilita genitoriale e di confermare le scelte sopra indicate."
    for linea in (testo[:105], testo[105:]):
        c.drawString(42, y, linea); y -= 12
    y -= 8
    c.setFont("Helvetica-Bold", 9); c.drawString(42, y, "Firma del genitore/tutore")
    max_w, max_h = 235, 72
    scala = min(max_w / firma.width, max_h / firma.height)
    fw, fh = firma.width * scala, firma.height * scala
    c.drawImage(ImageReader(firma_buf), 230, y - 52, width=fw, height=fh, mask="auto")
    c.line(225, y - 58, 520, y - 58)
    y -= 83
    c.setFont("Helvetica", 7.5)
    c.drawString(42, y, f"Sottoscritto il {dati.get('firmato_il','')} - richiesta {richiesta.get('id','')}")
    c.drawString(42, y - 12, f"E-mail destinataria: {richiesta.get('email_genitore','')}")
    c.save(); page_buf.seek(0)
    writer = PdfWriter()
    for pagina in PdfReader(io.BytesIO(originale_bytes), strict=False).pages:
        writer.add_page(pagina)
    for pagina in PdfReader(page_buf).pages:
        writer.add_page(pagina)
    output = io.BytesIO(); writer.write(output); return output.getvalue()


def render_privacy_pubblica(token):
    atleta, richiesta = _privacy_trova(token)
    st.markdown("## Privacy e liberatoria atleta minorenne")
    if not atleta or not richiesta:
        st.error("Collegamento non valido o non piu disponibile."); return
    atleta_nome = f"{atleta.get('cognome','')} {atleta.get('nome','')}".strip().upper()
    if richiesta.get("stato") == "FIRMATO":
        st.success(f"La privacy di {atleta_nome} e gia stata firmata il {richiesta.get('firmato_il','')}."); return
    try:
        if ora_italiana().replace(tzinfo=None) > datetime.fromisoformat(str(richiesta.get("scade_il", ""))).replace(tzinfo=None):
            st.error("Il collegamento e scaduto. Contatta la societa per riceverne uno nuovo."); return
    except Exception:
        pass
    originale = Path(str(richiesta.get("pdf_originale", "")))
    if not originale.exists():
        recuperato = scarica_documento_da_google_drive(richiesta.get("drive_originale_id", ""))
        if not recuperato:
            modello = _privacy_modello_path(); recuperato = modello.read_bytes() if modello else b""
        if recuperato:
            originale.parent.mkdir(parents=True, exist_ok=True); originale.write_bytes(recuperato)
        else:
            st.error("L'informativa originale non e disponibile."); return
    st.info(f"Atleta: **{atleta_nome}**")
    st.download_button("LEGGI E SCARICA L'INFORMATIVA COMPLETA", originale.read_bytes(), file_name=richiesta.get("nome_originale", "Informativa_privacy.pdf"), mime="application/pdf", use_container_width=True)
    st.caption("Prima di proseguire leggi l'informativa completa di Pallavolo Pinerolo S.S.D. A.R.L.")
    firmatario = st.text_input("Nome e cognome del genitore/tutore", value=str(richiesta.get("genitore_predefinito", "")))
    c1, c2 = st.columns(2)
    luogo_nascita = c1.text_input("Luogo di nascita del genitore/tutore")
    data_nascita = c2.text_input("Data di nascita del genitore/tutore", placeholder="gg/mm/aaaa")
    altro_genitore = st.selectbox("Altro genitore", ["PRESENTE E INFORMATO", "ASSENTE, MA INFORMATO E AUTORIZZA", "NON APPLICABILE / UNICO ESERCENTE"])
    luogo = st.text_input("Luogo", value="Pinerolo")
    opzioni = ["DO IL CONSENSO", "NEGO IL CONSENSO"]
    st.markdown("### Consensi")
    obbl = st.radio("Finalita obbligatorie indicate al punto 1", opzioni, horizontal=True)
    fac = st.radio("Finalita facoltative indicate al punto 2", opzioni, horizontal=True, index=1)
    comm = st.radio("Comunicazioni commerciali del Titolare", opzioni, horizontal=True, index=1)
    terzi = st.radio("Comunicazioni promozionali di soggetti terzi", opzioni, horizontal=True, index=1)
    immagini = st.radio("Liberatoria per immagini, video e registrazioni audio", opzioni, horizontal=True, index=1)
    presa_visione = st.checkbox("Dichiaro di aver letto l'informativa completa e confermo di essere il genitore/tutore dell'atleta.")
    if not FIRMA_MOBILE_CANVAS_DISPONIBILE:
        st.error("Componente firma non installato. Verifica requirements.txt."); return
    st.markdown("**Firma usando il dito, il pennino o il mouse:**")
    drawing = st_canvas(stroke_width=5, stroke_color="#0f235a", background_color="#ffffff", height=170, width=340, drawing_mode="freedraw", key=f"privacy_canvas_{richiesta.get('id','')}")
    if st.button("CONFERMA CONSENSI, FIRMA E GENERA PDF", type="primary", use_container_width=True, disabled=not presa_visione):
        if len(firmatario.strip()) < 5 or not luogo_nascita.strip() or not data_nascita.strip():
            st.error("Completa nome, luogo e data di nascita del genitore/tutore."); return
        if drawing.image_data is None:
            st.error("Inserisci la firma nel riquadro."); return
        try:
            firmato_il = ora_italiana().strftime("%d/%m/%Y %H:%M:%S")
            dati = {"firmatario": firmatario.strip().upper(), "luogo_nascita_genitore": luogo_nascita.strip(), "data_nascita_genitore": data_nascita.strip(), "altro_genitore": altro_genitore, "luogo": luogo.strip() or "Pinerolo", "data": ora_italiana().strftime("%d/%m/%Y"), "firmato_il": firmato_il, "consenso_obbligatorie": obbl, "consenso_facoltative": fac, "consenso_comunicazioni": comm, "consenso_terzi": terzi, "consenso_immagini": immagini}
            pdf = _privacy_genera_pdf(originale.read_bytes(), atleta, richiesta, dati, Image.fromarray(drawing.image_data.astype("uint8")))
            folder = Path(CARTELLA_ALLEGATI) / "privacy_firmate"; folder.mkdir(parents=True, exist_ok=True)
            nome_atleta_file = _firma_modulo_nome_sicuro(atleta_nome)
            stagione_file = _firma_modulo_nome_sicuro(atleta.get("stagione", "SENZA_STAGIONE"))
            data_file = ora_italiana().strftime("%Y%m%d")
            nome_file = f"{nome_atleta_file}_Privacy_{stagione_file}_{data_file}.pdf"
            firmato_path = folder / nome_file; firmato_path.write_bytes(pdf)
            drive_firmato = carica_documento_su_google_drive(pdf, nome_file, atleta=atleta, tipo="PRIVACY_FIRMATE", stagione=atleta.get("stagione", ""))
            richiesta.update(dati); richiesta.update({"stato": "FIRMATO", "pdf_firmato": str(firmato_path), "hash_firmato": hashlib.sha256(pdf).hexdigest(), "drive_firmato_stato": "CARICATO" if drive_firmato.get("ok") else "ERRORE", "drive_firmato_id": drive_firmato.get("id", ""), "drive_firmato_link": drive_firmato.get("webViewLink", ""), "drive_firmato_errore": drive_firmato.get("error", "")})
            ok, errore = invia_email_con_allegato(richiesta.get("email_genitore", ""), f"{nome_societa} - Privacy firmata - {atleta_nome}", f"Gentile genitore/tutore,\n\nin allegato trova l'informativa privacy e liberatoria firmata relativa a {atleta_nome}.\n\nCordiali saluti,\n{nome_societa}", pdf, nome_file)
            richiesta["email_stato"] = "INVIATA" if ok else "ERRORE"; richiesta["email_errore"] = errore
            _privacy_salva_risultato(atleta, richiesta, firmato_path)
            if ok: st.success("Privacy firmata, archiviata e inviata via e-mail.")
            else: st.warning(f"Privacy firmata e archiviata. Invio e-mail da verificare: {errore}")
        except Exception as exc:
            st.error(f"Impossibile completare la firma: {exc}")


def _privacy_modello_path():
    path = Path(str(config_societa.get("privacy_modello_path", "") or ""))
    if path.exists() and path.is_file():
        return path
    recuperato = scarica_documento_da_google_drive(config_societa.get("privacy_modello_drive_id", ""))
    if recuperato:
        path = path if str(path) not in {"", "."} else Path(CARTELLA_ALLEGATI) / "privacy_modello" / "Informativa_privacy_Pallavolo_Pinerolo.pdf"
        path.parent.mkdir(parents=True, exist_ok=True); path.write_bytes(recuperato)
        config_societa["privacy_modello_path"] = str(path)
        return path
    return None


def _privacy_modello_da_richieste_esistenti():
    for atleta in st.session_state.get("elenco_atlete", []):
        for richiesta in reversed(atleta.get("firme_privacy", []) or []):
            candidato = Path(str(richiesta.get("pdf_originale", "") or ""))
            if candidato.exists() and candidato.is_file():
                return candidato, str(richiesta.get("nome_originale", candidato.name))
    return None, ""


def _privacy_atleta_minorenne(atleta, riferimento=None):
    testo = str((atleta or {}).get("data_nas", "") or "").strip()
    nascita = None
    for fmt in ("%d/%m/%Y", "%d-%m-%Y", "%Y-%m-%d"):
        try:
            nascita = datetime.strptime(testo, fmt).date(); break
        except ValueError:
            pass
    if nascita is None:
        return False
    oggi = riferimento or ora_italiana().date()
    eta = oggi.year - nascita.year - ((oggi.month, oggi.day) < (nascita.month, nascita.day))
    return eta < 18


def _privacy_richiesta_stagione(atleta, stagione):
    stagione = str(stagione or atleta.get("stagione", ""))
    richieste = atleta.get("firme_privacy", []) or []
    return next((r for r in reversed(richieste) if str(r.get("stagione", "")) == stagione and r.get("stato") in {"DA FIRMARE", "FIRMATO"}), None)


def _privacy_crea_e_invia_richiesta(atleta, email, stagione, base_url):
    modello = _privacy_modello_path()
    if not modello:
        return None, False, "Modello privacy generale non configurato"
    email = _safe_email(email)
    if not email:
        return None, False, "E-mail del genitore assente o non valida"
    if not str(base_url or "").startswith("http"):
        return None, False, "Indirizzo pubblico del gestionale non configurato"
    esistente = _privacy_richiesta_stagione(atleta, stagione)
    if esistente:
        return esistente, False, "Privacy gia richiesta o firmata per questa stagione"
    rid, token = uuid.uuid4().hex, secrets.token_urlsafe(32)
    folder = Path(CARTELLA_ALLEGATI) / "privacy_firmate"; folder.mkdir(parents=True, exist_ok=True)
    nome_atleta_originale = _firma_modulo_nome_sicuro(f"{atleta.get('cognome','')} {atleta.get('nome','')}")
    stagione_originale = _firma_modulo_nome_sicuro(stagione or atleta.get("stagione", "SENZA_STAGIONE"))
    originale = folder / f"{nome_atleta_originale}_Privacy_da_firmare_{stagione_originale}_{rid[:8]}.pdf"
    originale.write_bytes(modello.read_bytes())
    drive_originale = carica_documento_su_google_drive(
        originale.read_bytes(), originale.name, atleta=atleta,
        tipo="PRIVACY_DA_FIRMARE", stagione=stagione or atleta.get("stagione", "")
    )
    ora = ora_italiana().replace(tzinfo=None)
    atleta_nome = f"{atleta.get('cognome','')} {atleta.get('nome','')}".strip().upper()
    richiesta = {
        "id": rid, "token": token, "stato": "DA FIRMARE", "stagione": str(stagione or atleta.get("stagione", "")),
        "atleta_id": str(atleta.get("id", "")), "email_genitore": email,
        "genitore_predefinito": atleta.get("gen1", ""), "pdf_originale": str(originale),
        "nome_originale": config_societa.get("privacy_modello_nome", modello.name),
        "hash_originale": hashlib.sha256(originale.read_bytes()).hexdigest(),
        "drive_originale_stato": "CARICATO" if drive_originale.get("ok") else "ERRORE",
        "drive_originale_id": drive_originale.get("id", ""), "drive_originale_link": drive_originale.get("webViewLink", ""),
        "drive_originale_errore": drive_originale.get("error", ""),
        "creata_il": ora.strftime("%d/%m/%Y %H:%M:%S"),
        "scade_il": (ora + timedelta(days=30)).isoformat(timespec="seconds"),
        "link": f"{str(base_url).rstrip('/')}?firma_privacy={token}",
    }
    atleta.setdefault("firme_privacy", []).append(richiesta)
    ok, errore = invia_email_automatica(
        email, f"{nome_societa} - Privacy e liberatoria - {atleta_nome}",
        f"Gentile genitore/tutore,\n\nper leggere, compilare e firmare la privacy e liberatoria relativa a {atleta_nome}, "
        f"apra dal telefono, tablet o computer questo collegamento personale:\n\n{richiesta['link']}\n\n"
        f"Il collegamento scade dopo 30 giorni.\n\nCordiali saluti,\n{nome_societa}",
    )
    richiesta["invio_link_stato"] = "INVIATO" if ok else "ERRORE"
    richiesta["invio_link_il"] = ora_italiana().strftime("%d/%m/%Y %H:%M:%S")
    richiesta["invio_link_errore"] = errore
    return richiesta, ok, errore


def _privacy_reinvia_link(atleta, richiesta):
    email = _safe_email(richiesta.get("email_genitore", ""))
    atleta_nome = f"{atleta.get('cognome','')} {atleta.get('nome','')}".strip().upper()
    if not email or not richiesta.get("link"):
        return False, "E-mail o collegamento non disponibile"
    ok, errore = invia_email_automatica(
        email, f"{nome_societa} - Reinvio privacy e liberatoria - {atleta_nome}",
        f"Gentile genitore/tutore,\n\nle inviamo nuovamente il collegamento personale per compilare e firmare la privacy relativa a {atleta_nome}:\n\n{richiesta['link']}\n\nCordiali saluti,\n{nome_societa}",
    )
    richiesta["invio_link_stato"] = "INVIATO" if ok else "ERRORE"
    richiesta["invio_link_il"] = ora_italiana().strftime("%d/%m/%Y %H:%M:%S")
    richiesta["invio_link_errore"] = errore
    return ok, errore


def _privacy_invia_automaticamente_nuove(nuove_atlete, stagione, archivio):
    esito = {"inviate": 0, "saltate": 0, "errori": []}
    if not config_societa.get("privacy_invio_automatico", False) or not _privacy_modello_path():
        esito["saltate"] = len(nuove_atlete or []); return esito
    base_url = str(_segreto("APP_PUBLIC_URL", "") or "")
    for atleta in nuove_atlete or []:
        if not _privacy_atleta_minorenne(atleta):
            esito["saltate"] += 1; continue
        email = _safe_email(atleta.get("mail1", "")) or _safe_email(atleta.get("mail2", ""))
        richiesta, ok, errore = _privacy_crea_e_invia_richiesta(atleta, email, stagione, base_url)
        if ok: esito["inviate"] += 1
        else:
            esito["saltate"] += 1
            if errore and "gia richiesta" not in errore.lower(): esito["errori"].append(f"{atleta.get('cognome','')} {atleta.get('nome','')}: {errore}")
    salva_atlete(archivio)
    return esito


def render_privacy_admin(atleta, suffix):
    st.markdown("### Privacy e liberatoria digitale")
    st.caption("Il modello generale di Pallavolo Pinerolo viene caricato una sola volta e riutilizzato per tutte le atlete.")
