def _tec_contatti_atleta(atleta):
    """Recupera in modo robusto i contatti per gli avvisi tecnici."""
    if not isinstance(atleta, dict):
        return []

    def _primo_valore(*chiavi):
        for k in chiavi:
            v = atleta.get(k, "")
            if v is not None and str(v).strip() and str(v).strip().lower() not in {"nan", "none", "nat"}:
                return v
        return ""

    candidati = [
        (_primo_valore("gen1","genitore1","genitore_1","tutore1","tutore_1") or "Genitore/Tutore 1",
         _primo_valore("tel1","telefono1","telefono_1","cell1","cellulare1","telefono_gen1","tel_gen1"),
         _primo_valore("mail1","email1","email_1","mail_gen1","email_gen1")),
        (_primo_valore("gen2","genitore2","genitore_2","tutore2","tutore_2") or "Genitore/Tutore 2",
         _primo_valore("tel2","telefono2","telefono_2","cell2","cellulare2","telefono_gen2","tel_gen2"),
         _primo_valore("mail2","email2","email_2","mail_gen2","email_gen2")),
        ("Atleta",
         _primo_valore("tel","telefono","cellulare","cell","telefono_atleta","tel_atleta"),
         _primo_valore("mail","email","email_atleta","mail_atleta")),
    ]

    out, seen = [], set()

    def _aggiungi(nome, tel="", mail=""):
        tel_p = _safe_phone(tel) if tel else ""
        mail_p = _safe_email(mail) if mail else ""
        if not tel_p and not mail_p:
            return
        key = (tel_p, (mail_p or "").lower())
        if key in seen:
            return
        seen.add(key)
        out.append({"nome": str(nome or "Contatto").strip(), "tel": tel_p, "mail": mail_p})

    for nome, tel, mail in candidati:
        _aggiungi(nome, tel, mail)

    # Compatibilità con vecchie importazioni/anagrafiche con nomi campo diversi.
    for k, v in atleta.items():
        if v is None or not str(v).strip():
            continue
        kl = str(k).strip().lower()
        if "mail" in kl or "email" in kl:
            _aggiungi("Contatto anagrafica", "", v)
        elif any(x in kl for x in ("telefono", "tel_", "cellulare", "cell_", "phone")):
            _aggiungi("Contatto anagrafica", v, "")

    return out

def _tec_wa_url(telefono, messaggio):
    """Crea il link wa.me; non invia automaticamente il messaggio."""
    tel = _safe_phone(telefono) if telefono else ''
    if not tel:
        return ''
    # wa.me richiede solo cifre, prefisso internazionale incluso.
    digits = ''.join(ch for ch in str(tel) if ch.isdigit())
    if not digits:
        return ''
    # Per numeri italiani salvati senza prefisso, aggiunge 39.
    if len(digits) in (9, 10) and not digits.startswith('39'):
        digits = '39' + digits
    return f"https://wa.me/{digits}?text={quote_plus(str(messaggio or ''))}"

def _tec_mailto(email, oggetto, messaggio):
    mail = _safe_email(email) if email else ''
    if not mail:
        return ''
    return f"mailto:{mail}?subject={quote_plus(str(oggetto or ''))}&body={quote_plus(str(messaggio or ''))}"
def _rate_alerts(atlete, oggi=None):
    oggi = oggi or ora_italiana(); alerts = []
    for a in atlete:
        try: ricalcola_finanze(a)
        except Exception: pass
        nome = f"{a.get('cognome','')} {a.get('nome','')}".strip(); mail, tel = _contatto_genitore(a)
        conf = trova_configurazione_quote(a.get("gruppo", "")); pagati = pagamenti_per_rata(a)
        for i in range(1,5):
            imp_raw = a.get(f"r{i}_imp", None); data_raw = a.get(f"r{i}_data", "")
            if (imp_raw is None or str(imp_raw).strip() in {"", "nan", "None"}) and conf: imp_raw = conf.get(f"r{i}_imp", 0)
            if (not str(data_raw or '').strip() or str(data_raw).strip().lower() in {"nan","none"}) and conf: data_raw = conf.get(f"r{i}_data", "")
            dovuto = max(0.0, safe_float(imp_raw, 0))
            if dovuto <= 0: continue
            pagato = max(0.0, float(pagati.get(i, safe_float(a.get(f"r{i}_versato",0))))); pagato = min(pagato, dovuto)
            residuo = max(0.0, dovuto - pagato)
            if residuo <= 0.009: continue
            scad = _parse_date_safe(data_raw)
            if not scad: continue
            delta = (scad.date() - oggi.date()).days
            if 1 <= delta <= 2: tipo = "Rata in scadenza entro 2 giorni"; colore = "giallo"
            elif delta <= -15: tipo = "Rata scaduta da almeno 15 giorni"; colore = "rosso"
            else: continue
            testo = (f"{nome_societa} - {tipo}. Gentile genitore, la {i}ª rata di € {dovuto:,.2f} per {nome} "
                     f"ha scadenza {scad.strftime('%d/%m/%Y')} ed è ancora da saldare per € {residuo:,.2f}.")
            alerts.append({"atleta":nome,"rata":i,"scadenza":scad,"residuo":residuo,"tipo":tipo,"colore":colore,"mail":mail,"tel":tel,"testo":testo})
    return alerts
def _visita_alerts(atlete, oggi=None):
    oggi = oggi or ora_italiana(); alerts = []
    for a in atlete:
        nome = f"{a.get('cognome','')} {a.get('nome','')}".strip(); scad = _parse_date_safe(a.get("scad_visita", ""))
        if not scad: continue
        delta = (scad.date() - oggi.date()).days
        if delta == 30: tipo = "Visita medica in scadenza tra 30 giorni"; colore = "giallo"
        elif 1 <= delta <= 7: tipo = "Visita medica in scadenza entro 7 giorni"; colore = "giallo"
        elif delta < 0: tipo = "Visita medica scaduta"; colore = "rosso"
        else: continue
        mail, tel = _contatto_genitore(a)
        testo = (f"{nome_societa} - {tipo}. Gentile genitore di {nome}, la visita medica scadrà il {scad.strftime('%d/%m/%Y')}. "
                 "Vi chiediamo di provvedere al rinnovo.")
        alerts.append({"atleta":nome,"scadenza":scad,"tipo":tipo,"colore":colore,"mail":mail,"tel":tel,"testo":testo})
    return alerts
def processa_notifiche_automatiche(atlete, dry_run=False, force=False):
    cfg = st.session_state.get("config_notifiche", {}) or {}
    oggi = ora_italiana()
    alerts = _visita_alerts(atlete, oggi) + _rate_alerts(atlete, oggi)
    # Rispetta le impostazioni attive per ciascun tipo di avviso.
    filtri = {
        "Visita medica in scadenza tra 30 giorni": bool(cfg.get("visita_30", True)),
        "Visita medica in scadenza entro 7 giorni": bool(cfg.get("visita_7", True)),
        "Visita medica scaduta": bool(cfg.get("visita_scaduta", True)),
        "Rata in scadenza entro 2 giorni": bool(cfg.get("rata_2", True)),
        "Rata scaduta da almeno 15 giorni": bool(cfg.get("rata_15", True)),
    }
    alerts = [a for a in alerts if filtri.get(a.get("tipo", ""), True)]
    result = {"alerts": len(alerts), "email_sent": 0, "wa_sent": 0, "errors": [], "skipped": 0, "preview": []}
    for al in alerts:
        a_nome = al.get("atleta", "")
        atleta = next((x for x in atlete if f"{x.get('cognome','')} {x.get('nome','')}".strip() == a_nome), None)
        if atleta is None: result["skipped"] += 1; continue
        recipients = _alert_recipients(atleta)
        scad_key = al.get("scadenza").strftime("%Y-%m-%d") if al.get("scadenza") else ""
        base_key = f"{atleta.get('id','')}|{al.get('tipo','')}|{scad_key}"
        for channel, recipient, parent in recipients:
            key = f"{base_key}|{channel}|{recipient}"
            if not force and _notifica_inviata(key, channel, recipient, athlete_name=a_nome): result["skipped"] += 1; continue
            if not force and _notifica_gia_tentata_oggi(key, oggi, channel, recipient, athlete_name=a_nome): result["skipped"] += 1; continue
            subject = f"{nome_societa} - {al.get('tipo','Avviso')}"; body = al.get("testo", "")
            if dry_run:
                result["preview"].append(f"{a_nome} — {al.get('tipo','Avviso')} — scadenza {al.get('scadenza').strftime('%d/%m/%Y')} — {channel}: {recipient}")
                continue
            if channel == "email" and cfg.get("email", True):
                ok, err = invia_email_automatica(recipient, subject, body); result["email_sent"] += 1 if ok else 0
            elif channel == "whatsapp" and cfg.get("whatsapp", True):
                template = cfg.get(_alert_template_key(al.get("tipo", "")), "")
                ok, err = invia_whatsapp_automatico(recipient, template, cfg.get("wa_language", "it"), _alert_params(al))
                result["wa_sent"] += 1 if ok else 0
            else:
                ok, err = False, "canale disabilitato"
            _append_notifica_log({
                "key": key, "date": oggi.strftime("%Y-%m-%d %H:%M:%S"), "atleta": a_nome,
                "tipo": al.get("tipo"), "scadenza": scad_key, "channel": channel,
                "recipient": recipient, "status": "sent" if ok else ("not_configured" if "non configurata" in err else "error"),
                "error": "" if ok else err,
            })
            if not ok and err != "canale disabilitato": result["errors"].append(f"{a_nome} {channel}: {err}")
    _append_notifica_log({"key":f"RUN|{oggi.strftime('%Y-%m-%d %H:%M')}", "date":oggi.strftime("%Y-%m-%d %H:%M:%S"), "atleta":"", "tipo":"ESECUZIONE AUTOMATICA", "channel":"system", "recipient":"", "status":"sent", "error":f"alert={result['alerts']} email={result['email_sent']} wa={result['wa_sent']} skipped={result['skipped']}"})
    return result
def diagnostica_scadenze_visite(atlete, oggi=None):
    oggi = oggi or ora_italiana(); out = []
    for a in atlete:
        nome = f"{a.get('cognome','')} {a.get('nome','')}".strip() or '(senza nome)'; raw = a.get('scad_visita',''); scad = _parse_date_safe(raw); stato = controlla_visita(raw)
        delta = int((scad.date() - oggi.date()).days) if scad else None
        trigger = 'Nessuno'
        if delta == 30: trigger = 'VISITA 30 GIORNI'
        elif isinstance(delta, int) and 1 <= delta <= 7: trigger = 'VISITA ENTRO 7 GIORNI'
        elif isinstance(delta, int) and delta <= 0: trigger = 'VISITA SCADUTA'
        out.append({'atleta':nome,'dato_originale':str(raw or ''),'data_riconosciuta':scad.strftime('%d/%m/%Y') if scad else 'NON RICONOSCIUTA','giorni':delta if delta is not None else '—','stato':stato,'trigger':trigger,'email':_safe_email(a.get('mail1','')) or 'assente','telefono':_safe_phone(a.get('tel1','')) or 'assente'})
    return out
def diagnostica_scadenze_rate(atlete, oggi=None):
    oggi = oggi or ora_italiana(); out = []
    for a in atlete:
        nome = f"{a.get('cognome','')} {a.get('nome','')}".strip() or '(senza nome)'; mail = _safe_email(a.get('mail1','')) or 'assente'; tel = _safe_phone(a.get('tel1','')) or 'assente'
        for i in range(1,5):
            dovuto = max(0.0, safe_float(a.get(f"r{i}_imp", 0)))
            if dovuto <= 0: continue
            pagato = max(0.0, float(pagamenti_per_rata(a).get(i, 0.0))); residuo = max(0.0, dovuto - pagato); scad = _parse_date_safe(a.get(f"r{i}_data", ""))
            if not scad: continue
            delta = int((scad.date() - oggi.date()).days)
            trigger = "RATA COMPLETA" if residuo <= 0.009 else ("RATA ENTRO 2 GIORNI" if 1 <= delta <= 2 else ("SOLLECITO RATA 15 GIORNI" if delta <= -15 else "Nessun avviso"))
            out.append({"atleta":nome,"rata":f"{i}ª rata","scadenza":scad.strftime("%d/%m/%Y"),"giorni":delta,"dovuto":f"€ {dovuto:,.2f}","pagato":f"€ {pagato:,.2f}","residuo":f"€ {residuo:,.2f}","trigger":trigger,"email":mail,"telefono":tel})
    return out

