def categoria_dashboard(a):
    """Categoria definitiva: il gruppo configurato ha priorita assoluta."""
    gruppo = str(a.get("gruppo", "")).strip()
    by_group = categoria_da_gruppo(gruppo)
    if by_group:
        return by_group
    raw = str(a.get("categoria", "")).strip().upper()
    if "PROMOZIONALE" in raw:
        return "PROMOZIONALE"
    if "GIOVANILE" in raw:
        return "GIOVANILE"
    txt = f"{raw} {gruppo.upper()}"
    if "PROMO" in txt or "MINI" in txt or "SCUOLA" in txt or any(x in txt for x in ["2015","2016","2017","2018","SILVER"]):
        return "PROMOZIONALE"
    if "GIOVAN" in txt or "UNDER" in txt or any(x in txt for x in ["U13","U14","U15","U17","U19","GOLD"]) or "SERIE" in txt or "DIVISIONE" in txt:
        return "GIOVANILE"
    return "ALTRO"
