    perc_valide=(n_valide/n_atlete*100) if n_atlete else 0
    perc_critiche=((n_scadute+n_mancanti)/n_atlete*100) if n_atlete else 0
    st.markdown(f"<div class='dash59-head'><div><div class='dash59-title'>⌂ &nbsp;Dashboard</div><div class='dash59-user'>Panoramica operativa · Stagione {stagione_selezionata}</div></div><div class='dash59-user'>👤 Benvenuto, <b>{st.session_state.get('username_corrente','admin')}</b><br>{st.session_state.get('ruolo_corrente','Amministratore')}</div></div>",unsafe_allow_html=True)
