                    filtro_team_gir = f1.selectbox('Filtra squadra', ['TUTTE'] + squadre_girone, key='girone_filter_team')
                    solo_ris = f2.checkbox('Solo gare con risultato', value=False, key='girone_only_results')
                    df_show = df_gir.copy()
