        # Le 4 voci base restano compatibili con lo storico esistente.
        base_voci = [
            ('Battute punto', 'battute_punto'),
            ('Ricezioni positive', 'ricezioni_positive'),
            ('Attacchi punto', 'attacchi_punto'),
            ('Muri punto', 'muri_punto'),
        ]
        voci_custom = []
        for voce in st.session_state.get('voci_scout_config', []):
            nome_voce = str(voce or '').strip()
            if not nome_voce:
                continue
            if nome_voce.lower() in {x[0].lower() for x in base_voci}:
                continue
            chiave = 'custom_' + re.sub(r'[^a-z0-9]+', '_', normalizza_intestazione_colonna(nome_voce)).strip('_')
            if chiave == 'custom_':
                continue
            # Chiavi duplicate vengono rese univoche senza perdere la voce mostrata all'utente.
            gia = {k for _, k in voci_custom}
            base_chiave = chiave; n = 2
            while chiave in gia:
                chiave = f'{base_chiave}_{n}'; n += 1
            voci_custom.append((nome_voce, chiave))
        gare_scout_db = st.session_state.setdefault('calendario_gare', {})
        gare_scout_visibili = [
            gara for gara in (gare_scout_db.get(stagione_selezionata, []) or [])
            if squadra_visibile_utente(gara.get('squadra',''))
        ]
        mappa_gare_scout_completa = {}
        for gara_scout in sorted(gare_scout_visibili, key=lambda g: str(g.get('data','')), reverse=True):
            prefisso_gara_scout = f"{gara_scout.get('sigla_campionato','')} N° {gara_scout.get('numero_gara','')} — " if gara_scout.get('sigla_campionato') or gara_scout.get('numero_gara') else ''
            etichetta_gara_scout = f"{prefisso_gara_scout}{gara_scout.get('data','')} — {gara_scout.get('squadra','')} vs {gara_scout.get('avversaria','')}"
            if etichetta_gara_scout in mappa_gare_scout_completa:
                etichetta_gara_scout += f" — {str(gara_scout.get('id',''))[:6]}"
            mappa_gare_scout_completa[etichetta_gara_scout] = gara_scout
        ricerca_gara_scout = st.text_input(
            '🔎 Cerca gara', placeholder='Numero gara, sigla, data, squadra o avversaria', key='sc_ricerca_gara'
        )
